const c=4,n="dao-duc",i="Đạo đức lớp 4",h="internal",t=[{id:"biet-on-nguoi-lao-dong",title:"Biết ơn người lao động",lessons:[{id:"dd4-nguoi-lao-dong",title:"Bài 1: Người lao động quanh em",weeks:[1,2],learn:[{title:"Người lao động là ai?",text:"Người lao động là những người làm ra của cải, sản phẩm hoặc làm những công việc có ích cho mọi người.",example:"👩‍🌾 nông dân · 👷 công nhân · 👩‍⚕️ bác sĩ · 🧑‍🏫 thầy cô"},{title:"Nghề nào cũng đáng quý",text:"Lao động chân tay hay lao động trí óc đều có ích. Mỗi nghề góp một phần làm cho cuộc sống tốt đẹp hơn.",example:"🧹 lao công · 🧑‍🔬 nhà khoa học · 🧑‍🍳 đầu bếp"},{title:"Vì sao phải biết ơn?",text:"Cơm ta ăn, áo ta mặc, đường ta đi đều nhờ công sức của người lao động. Biết ơn họ là sống có tình nghĩa.",example:"🍚 hạt gạo – công người nông dân"}],practice:[{questions:[{id:"dd4-nguoi-lao-dong-01",type:"mc",q:"Ai làm ra hạt gạo cho chúng ta ăn hằng ngày?",options:["Người nông dân","Người thợ may","Người bán sách"],answer:0,emoji:"👩‍🌾",explain:"Người nông dân cày cấy, chăm sóc cây lúa để có hạt gạo."},{id:"dd4-nguoi-lao-dong-02",type:"mc",q:"Ai giữ cho đường phố sạch sẽ mỗi sáng?",options:["Người lái xe taxi chở khách","Công nhân vệ sinh môi trường","Người thợ điện sửa đường dây"],answer:1,emoji:"🧹",explain:"Công nhân vệ sinh môi trường quét dọn, thu gom rác cho phố phường sạch đẹp."},{id:"dd4-nguoi-lao-dong-03",type:"mc",q:"Ai khám bệnh và chữa bệnh cho mọi người?",options:["Kiến trúc sư","Nhà báo","Bác sĩ"],answer:2,emoji:"👩‍⚕️",explain:"Bác sĩ khám và chữa bệnh, giúp mọi người khỏe mạnh."},{id:"dd4-nguoi-lao-dong-04",type:"tf",q:"Người lao động là người làm ra của cải hoặc làm những việc có ích cho xã hội.",answer:!0,explain:"Đúng vậy, đó chính là người lao động."},{id:"dd4-nguoi-lao-dong-05",type:"tf",q:"Chỉ những người làm việc ở văn phòng mới là người lao động.",answer:!1,explain:"Sai rồi. Người nông dân, công nhân, người bán hàng… cũng đều là người lao động."},{id:"dd4-nguoi-lao-dong-06",type:"tf",q:"Thầy cô giáo cũng là người lao động.",answer:!0,explain:"Đúng. Thầy cô lao động trí óc, dạy dỗ học sinh nên người."},{id:"dd4-nguoi-lao-dong-07",type:"match",q:"Nối nghề với công việc phù hợp.",pairs:[["Thợ xây","Xây nhà cửa"],["Thợ may","May quần áo"],["Bác sĩ","Chữa bệnh"],["Giáo viên","Dạy học"]],explain:"Mỗi nghề làm một công việc riêng, đều có ích cho mọi người."},{id:"dd4-nguoi-lao-dong-08",type:"mc",q:"Ai mang thư và bưu phẩm đến từng nhà?",options:["Nhân viên bưu chính","Người đánh cá trên biển","Người trồng rau ngoài đồng"],answer:0,emoji:"📮",explain:"Nhân viên bưu chính mang thư, bưu phẩm đến tận tay mọi người."},{id:"dd4-nguoi-lao-dong-09",type:"multi",q:"Những ai dưới đây là người lao động?",options:["Chú công nhân xây dựng","Cô bán hàng ở chợ","Bác sĩ ở bệnh viện","Cô giáo dạy em"],answers:[0,1,2,3],explain:"Tất cả đều là người lao động, vì họ đều làm việc có ích cho xã hội."}]},{questions:[{id:"dd4-nguoi-lao-dong-10",type:"mc",q:"Vì sao chúng ta phải biết ơn người lao động?",options:["Vì họ luôn có rất nhiều tiền bạc","Vì nhờ họ mà ta có cái ăn, cái mặc","Vì họ đều là người quen của gia đình mình"],answer:1,explain:"Thức ăn, quần áo, nhà cửa, trường học… đều có được nhờ người lao động."},{id:"dd4-nguoi-lao-dong-11",type:"tf",q:"Lao động chân tay không đáng quý bằng lao động trí óc.",answer:!1,explain:"Sai. Lao động chân tay và trí óc đều có ích, đều đáng quý như nhau."},{id:"dd4-nguoi-lao-dong-12",type:"match",q:"Nối đồ vật với người lao động làm ra nó.",pairs:[["Bát cơm","Người nông dân"],["Chiếc áo","Người thợ may"],["Ngôi nhà","Người thợ xây"],["Quyển sách","Tác giả và người làm sách"]],explain:"Mỗi đồ vật quen thuộc đều chứa công sức của người lao động."},{id:"dd4-nguoi-lao-dong-13",type:"mc",q:"Câu “Ai ơi bưng bát cơm đầy, dẻo thơm một hạt, đắng cay muôn phần” nhắc em điều gì?",options:["Cần ăn thật nhanh khi cơm còn nóng hổi","Cơm phải dẻo và thơm thì mới đáng ăn","Hạt gạo chứa bao vất vả của nhà nông"],answer:2,emoji:"🍚",explain:"Câu ca dao nhắc em trân trọng công sức vất vả của người làm ra hạt gạo."},{id:"dd4-nguoi-lao-dong-14",type:"tf",q:"Nhờ chú bảo vệ trông giữ, trường lớp được an toàn.",answer:!0,explain:"Đúng. Chú bảo vệ cũng là người lao động đáng quý."},{id:"dd4-nguoi-lao-dong-15",type:"multi",q:"Cuộc sống của em hôm nay có nhờ công sức của những ai?",options:["Người trồng rau","Bác tài xế xe buýt","Cô cấp dưỡng nấu ăn ở trường"],answers:[0,1,2],explain:"Rất nhiều người lao động góp công cho một ngày bình thường của em."},{id:"dd4-nguoi-lao-dong-16",type:"mc",q:"Nghề nào dưới đây là lao động trí óc nhiều hơn?",options:["Nghiên cứu khoa học","Bốc vác hàng hóa","Quét đường"],answer:0,explain:"Nhà khoa học chủ yếu dùng trí óc để tìm tòi, nghiên cứu."},{id:"dd4-nguoi-lao-dong-17",type:"tf",q:"Người làm nghề đơn giản thì không cần được tôn trọng.",answer:!1,explain:"Sai. Mọi nghề nghiệp chân chính đều đáng được tôn trọng."},{id:"dd4-nguoi-lao-dong-18",type:"mc",q:"Nếu không có công nhân vệ sinh môi trường, điều gì có thể xảy ra?",options:["Đường phố vẫn sạch như thường ngày","Rác thải ứ đọng, phố phường bẩn và hôi","Mọi người sẽ có thêm chỗ vui chơi"],answer:1,explain:"Công việc thầm lặng của họ giữ cho môi trường sạch sẽ mỗi ngày."}]},{questions:[{id:"dd4-nguoi-lao-dong-19",type:"mc",q:"Đi chợ cùng mẹ, Lan thấy bác bán rau dậy từ rất sớm. Lan nên nghĩ thế nào?",options:["Bán rau là việc nhàn, chẳng có gì vất vả","Bác dậy sớm là chuyện của bác, không liên quan","Bác thật vất vả, mình cần quý công sức của bác"],answer:2,explain:"Hiểu nỗi vất vả của người lao động giúp em biết trân trọng họ."},{id:"dd4-nguoi-lao-dong-20",type:"tf",q:"Ăn hết phần cơm, không bỏ thừa là một cách biết ơn người nông dân.",answer:!0,explain:"Đúng. Không lãng phí là trân trọng công sức của người làm ra lương thực."},{id:"dd4-nguoi-lao-dong-21",type:"mc",q:"Minh nói: “Nghề quét rác chẳng có gì hay.” Em nên nói với Minh thế nào?",options:["Nghề nào cũng có ích, nhờ cô chú mà phố sạch","Ừ, nghề đó vất vả mà chẳng ai cần đến cả","Tớ không quan tâm, việc đó không liên quan"],answer:0,explain:"Em nhẹ nhàng giúp bạn hiểu rằng nghề nào cũng đáng trân trọng."},{id:"dd4-nguoi-lao-dong-22",type:"multi",q:"Những việc nào cho thấy em biết ơn người lao động?",options:["Chào hỏi lễ phép cô lao công ở trường","Vẽ bậy lên tường vừa sơn","Giữ gìn sách vở, đồ dùng","Bỏ thừa thức ăn"],answers:[0,2],explain:"Lễ phép và giữ gìn sản phẩm là cách thể hiện lòng biết ơn."},{id:"dd4-nguoi-lao-dong-23",type:"tf",q:"Vứt rác bừa bãi vì đã có người quét dọn là không sao.",answer:!1,explain:"Sai. Như vậy là không tôn trọng công sức của công nhân vệ sinh."},{id:"dd4-nguoi-lao-dong-24",type:"mc",q:"Khi được chú thợ sửa xe sửa giúp chiếc xe đạp, em nên làm gì?",options:["Đi ngay không nói gì","Cảm ơn chú","Chê chú sửa chậm"],answer:1,explain:"Lời cảm ơn chân thành là cách đơn giản để thể hiện lòng biết ơn."},{id:"dd4-nguoi-lao-dong-25",type:"order",q:"Sắp xếp các bước làm ra hạt gạo của người nông dân.",items:["Làm đất","Gieo mạ, cấy lúa","Chăm sóc lúa","Gặt lúa","Phơi khô và xay thành gạo"],explain:"Hạt gạo trải qua nhiều bước vất vả mới đến bữa cơm của em."},{id:"dd4-nguoi-lao-dong-26",type:"tf",q:"Biết ơn người lao động cũng có nghĩa là quý trọng sản phẩm họ làm ra.",answer:!0,explain:"Đúng. Quý trọng sản phẩm là quý trọng công sức của người lao động."},{id:"dd4-nguoi-lao-dong-27",type:"mc",q:"Trong giờ ăn bán trú, Khoa chê món ăn và đổ đi gần hết. Em nên góp ý thế nào?",options:["Không thích thì cứ đổ đi, còn món khác mà","Mình cũng sẽ đổ bớt đi cho giống với bạn","Lần sau lấy vừa đủ, cô cấp dưỡng nấu vất vả lắm"],answer:2,explain:"Lấy vừa đủ, không bỏ phí là tôn trọng công sức của cô cấp dưỡng."}]}],challenge:{questions:[{id:"dd4-nguoi-lao-dong-28",type:"mc",q:"Câu tục ngữ nào nói về lòng biết ơn người lao động?",options:["Ăn quả nhớ kẻ trồng cây","Ăn trông nồi, ngồi trông hướng","Có công mài sắt có ngày nên kim"],answer:0,explain:"Ăn quả nhớ kẻ trồng cây nhắc ta nhớ ơn người đã làm ra thành quả."},{id:"dd4-nguoi-lao-dong-29",type:"multi",q:"Những ý nào nói đúng về người lao động?",options:["Họ làm ra của cải cho xã hội","Chỉ người có học vị cao mới là người lao động","Lao động chân tay và trí óc đều đáng quý","Họ đáng được tôn trọng"],answers:[0,2,3],explain:"Mọi người lao động chân chính đều có ích và đáng được tôn trọng."},{id:"dd4-nguoi-lao-dong-30",type:"tf",q:"Người lao động chỉ cần nhận tiền công, không cần lời cảm ơn.",answer:!1,explain:"Sai. Lời cảm ơn và sự tôn trọng làm người lao động vui và thêm động lực."},{id:"dd4-nguoi-lao-dong-13",type:"mc",q:"Câu “Ai ơi bưng bát cơm đầy, dẻo thơm một hạt, đắng cay muôn phần” nhắc em điều gì?",options:["Cần ăn thật nhanh khi cơm còn nóng hổi","Cơm phải dẻo và thơm thì mới đáng ăn","Hạt gạo chứa bao vất vả của nhà nông"],answer:2,emoji:"🍚",explain:"Câu ca dao nhắc em trân trọng công sức vất vả của người làm ra hạt gạo."},{id:"dd4-nguoi-lao-dong-22",type:"multi",q:"Những việc nào cho thấy em biết ơn người lao động?",options:["Chào hỏi lễ phép cô lao công ở trường","Vẽ bậy lên tường vừa sơn","Giữ gìn sách vở, đồ dùng","Bỏ thừa thức ăn"],answers:[0,2],explain:"Lễ phép và giữ gìn sản phẩm là cách thể hiện lòng biết ơn."},{id:"dd4-nguoi-lao-dong-25",type:"order",q:"Sắp xếp các bước làm ra hạt gạo của người nông dân.",items:["Làm đất","Gieo mạ, cấy lúa","Chăm sóc lúa","Gặt lúa","Phơi khô và xay thành gạo"],explain:"Hạt gạo trải qua nhiều bước vất vả mới đến bữa cơm của em."}]},summary:["Người lao động làm ra của cải và những công việc có ích cho xã hội.","Mọi nghề nghiệp chân chính đều đáng được tôn trọng.","Cuộc sống của em có được là nhờ công sức của rất nhiều người lao động."]},{id:"dd4-the-hien-biet-on",title:"Bài 2: Thể hiện lòng biết ơn người lao động",weeks:[3,4],learn:[{title:"Biết ơn bằng lời nói",text:"Chào hỏi lễ phép, nói lời cảm ơn khi được người lao động giúp đỡ hay phục vụ.",example:"🙏 “Cháu cảm ơn cô ạ!”"},{title:"Biết ơn bằng việc làm",text:"Giữ gìn, tiết kiệm sản phẩm lao động; không làm bẩn nơi người khác vừa dọn; giúp đỡ người lao động khi có thể.",example:"🍚 ăn hết cơm · 📚 giữ sách cẩn thận"},{title:"Không nên làm",text:"Chê bai, coi thường người lao động; phá hỏng, lãng phí sản phẩm họ làm ra.",example:"🚫 vẽ bậy · 🚫 bỏ thừa thức ăn"}],practice:[{questions:[{id:"dd4-the-hien-biet-on-01",type:"tf",q:"Nói lời cảm ơn bác bảo vệ khi bác mở cổng giúp là việc làm đúng.",answer:!0,explain:"Đúng. Lời cảm ơn thể hiện em biết ơn người lao động."},{id:"dd4-the-hien-biet-on-02",type:"tf",q:"Viết, vẽ lên bàn ghế mới là việc bình thường.",answer:!1,explain:"Sai. Bàn ghế là sản phẩm của người lao động, em cần giữ gìn."},{id:"dd4-the-hien-biet-on-03",type:"mc",q:"Việc làm nào thể hiện lòng biết ơn người lao động?",options:["Giữ gìn quần áo sạch đẹp","Bẻ cành cây trong công viên","Đổ nước ra hành lang vừa lau"],answer:0,explain:"Giữ gìn quần áo là trân trọng công sức người thợ may và bố mẹ."},{id:"dd4-the-hien-biet-on-04",type:"mc",q:"Khi gặp cô lao công trong trường, em nên làm gì?",options:["Đi lướt qua","Chào cô lễ phép","Chê cô làm chậm"],answer:1,explain:"Lời chào lễ phép là cách thể hiện sự tôn trọng người lao động."},{id:"dd4-the-hien-biet-on-05",type:"multi",q:"Những việc nào thể hiện lòng biết ơn người lao động?",options:["Ăn hết phần cơm của mình","Bỏ rác đúng nơi quy định","Làm rách sách giáo khoa","Cảm ơn cô bán hàng"],answers:[0,1,3],explain:"Tiết kiệm, giữ vệ sinh và nói lời cảm ơn đều là biết ơn người lao động."},{id:"dd4-the-hien-biet-on-06",type:"tf",q:"Tắt điện, khóa vòi nước khi không dùng cũng là trân trọng sức lao động.",answer:!0,explain:"Đúng. Điện và nước sạch có được nhờ công sức nhiều người."},{id:"dd4-the-hien-biet-on-07",type:"mc",q:"Việc làm nào là coi thường người lao động?",options:["Gửi thư cảm ơn các chú công an","Phụ mẹ dọn mâm sau bữa cơm","Chế giễu nghề nghiệp của người khác"],answer:2,explain:"Chế giễu nghề nghiệp là thiếu tôn trọng người lao động."},{id:"dd4-the-hien-biet-on-08",type:"mc",q:"Ngày 20 tháng 11, em có thể làm gì để thể hiện lòng biết ơn thầy cô?",options:["Làm tấm thiệp và viết lời chúc","Nghỉ học để đi chơi cả ngày","Không làm gì vì đó là ngày nghỉ"],answer:0,emoji:"✉️",explain:"Một tấm thiệp tự làm là món quà chân thành gửi thầy cô."},{id:"dd4-the-hien-biet-on-09",type:"tf",q:"Thể hiện lòng biết ơn thì phải tặng quà đắt tiền.",answer:!1,explain:"Sai. Lời cảm ơn, việc làm tốt và sự lễ phép là đủ chân thành."}]},{questions:[{id:"dd4-the-hien-biet-on-10",type:"match",q:"Nối việc làm với người lao động em đang biết ơn.",pairs:[["Ăn hết cơm","Người nông dân"],["Không vứt rác bừa bãi","Công nhân vệ sinh"],["Giữ sách vở cẩn thận","Người làm sách"],["Chăm chú nghe giảng","Thầy cô giáo"]],explain:"Mỗi việc làm nhỏ đều là cách biết ơn một nhóm người lao động."},{id:"dd4-the-hien-biet-on-11",type:"mc",q:"Vì sao không nên giẫm lên bồn cỏ vừa được chăm sóc?",options:["Vì giẫm lên thì cỏ sẽ mọc nhanh hơn","Vì làm hỏng công sức của người chăm cây","Vì giẫm lên cỏ sẽ bị lấm bẩn giày"],answer:1,explain:"Giữ gìn bồn cỏ là tôn trọng công sức của người làm vườn."},{id:"dd4-the-hien-biet-on-12",type:"tf",q:"Lắng nghe, làm theo lời dặn của bác sĩ cũng là tôn trọng người lao động.",answer:!0,explain:"Đúng. Làm theo lời dặn là trân trọng công sức chăm sóc của bác sĩ."},{id:"dd4-the-hien-biet-on-13",type:"multi",q:"Hành vi nào chưa biết ơn người lao động?",options:["Lấy thật nhiều thức ăn rồi bỏ thừa","Xếp dép gọn gàng","Bôi bẩn lên tường vừa sơn","Nói trống không với người phục vụ"],answers:[0,2,3],explain:"Lãng phí, làm bẩn và thiếu lễ phép là chưa trân trọng người lao động."},{id:"dd4-the-hien-biet-on-14",type:"mc",q:"Câu nào thể hiện thái độ đúng với người lao động?",options:["Nhanh lên, sao chậm thế","Ai mà chẳng làm được việc này","Cháu cảm ơn bác đã sửa giúp cháu ạ"],answer:2,explain:"Lời lẽ lễ phép, biết ơn làm người lao động vui lòng."},{id:"dd4-the-hien-biet-on-15",type:"tf",q:"Chỉ cần biết ơn người lao động trong gia đình mình.",answer:!1,explain:"Sai. Em biết ơn tất cả những người lao động, cả người em không quen."},{id:"dd4-the-hien-biet-on-16",type:"mc",q:"Vì sao em nên giữ gìn bộ bàn ghế trong lớp?",options:["Vì đó là công sức của người thợ làm ra","Vì bàn ghế cũ rồi nên không cần giữ nữa","Vì chỉ khi cô giáo nhìn thấy mới phải giữ"],answer:0,explain:"Bàn ghế được làm ra vất vả và còn phục vụ nhiều lớp học sinh."},{id:"dd4-the-hien-biet-on-17",type:"tf",q:"Viết thư hay vẽ tranh tặng chú bộ đội, chú công an là một cách thể hiện lòng biết ơn.",answer:!0,explain:"Đúng. Đó là những món quà tinh thần đầy ý nghĩa."},{id:"dd4-the-hien-biet-on-18",type:"mc",q:"Lời nói nào phù hợp khi em nhận hàng từ chú giao hàng?",options:["Để đó đi, cháu đang bận lắm","Cháu cảm ơn chú, chú vất vả quá ạ","Sao chú giao hàng lâu thế ạ"],answer:1,explain:"Lời cảm ơn ấm áp là sự ghi nhận công sức của người lao động."}]},{questions:[{id:"dd4-the-hien-biet-on-19",type:"mc",q:"Hà thấy bạn vứt vỏ bánh xuống sân trường vừa được quét. Hà nên làm gì?",options:["Lờ đi như không nhìn thấy","Vứt thêm vài vỏ bánh cho vui","Nhắc bạn nhặt bỏ vào thùng rác"],answer:2,explain:"Nhắc bạn nhẹ nhàng giúp giữ sạch trường và tôn trọng công sức cô lao công."},{id:"dd4-the-hien-biet-on-20",type:"mc",q:"Ở nhà hàng, Nam thấy anh phục vụ làm đổ cốc nước. Cách cư xử nào là đúng?",options:["Nhẹ nhàng nói không sao và giúp lau","Quát mắng anh ấy","Chụp ảnh đăng lên mạng chê bai"],answer:0,explain:"Ai cũng có lúc sơ suất; thông cảm và giúp đỡ là cách cư xử đẹp."},{id:"dd4-the-hien-biet-on-21",type:"tf",q:"Không làm ồn, giữ trật tự trong bệnh viện là biết tôn trọng công việc của bác sĩ, y tá.",answer:!0,explain:"Đúng. Yên tĩnh giúp các bác sĩ làm việc tốt và người bệnh nghỉ ngơi."},{id:"dd4-the-hien-biet-on-22",type:"multi",q:"Tùng muốn tỏ lòng biết ơn bác bảo vệ trường. Tùng có thể làm gì?",options:["Chào bác mỗi sáng","Dắt xe vào đúng chỗ, xếp gọn","Làm tấm thiệp cảm ơn bác","Trèo qua cổng khi bác đã khóa"],answers:[0,1,2],explain:"Lễ phép và chấp hành nội quy là cách biết ơn bác bảo vệ."},{id:"dd4-the-hien-biet-on-23",type:"mc",q:"Thảo dùng giấy trắng chỉ để vẽ vài nét rồi vứt. Em khuyên Thảo thế nào?",options:["Giấy rẻ lắm, bạn cứ vứt cũng được","Bạn dùng cả hai mặt giấy cho đỡ phí nhé","Bạn lấy thêm tờ mới mà vẽ tiếp đi"],answer:1,explain:"Tiết kiệm giấy là tôn trọng người lao động và bảo vệ cây xanh."},{id:"dd4-the-hien-biet-on-24",type:"order",q:"Sắp xếp các bước làm tấm thiệp cảm ơn cô lao công.",items:["Chuẩn bị giấy, bút màu","Gấp giấy thành tấm thiệp","Viết lời cảm ơn và trang trí thiệp","Trao thiệp và nói lời cảm ơn cô"],explain:"Làm thiệp theo từng bước giúp món quà thêm chu đáo."},{id:"dd4-the-hien-biet-on-25",type:"tf",q:"Thấy bác thợ điện đang sửa đường dây, Bình đến gần đùa nghịch với dụng cụ của bác.",answer:!1,explain:"Sai. Đùa nghịch làm phiền công việc và rất nguy hiểm."},{id:"dd4-the-hien-biet-on-26",type:"mc",q:"Bé Ngọc làm vỡ chiếc bát. Mẹ dặn: “Mỗi chiếc bát cũng là công sức của bao người.” Ngọc nên rút ra điều gì?",options:["Bát vỡ thì mua ngay cái khác là xong","Từ nay không bao giờ rửa bát nữa","Cần cẩn thận, giữ gìn đồ dùng trong nhà"],answer:2,explain:"Biết quý đồ dùng là biết ơn người làm ra chúng."},{id:"dd4-the-hien-biet-on-27",type:"mc",q:"Bạn Vy nói: “Mình sẽ nói cảm ơn mọi người lao động em gặp, dù họ làm nghề gì.” Em thấy thế nào?",options:["Đáng khen, vì người lao động nào cũng đáng quý","Không cần thiết, cảm ơn nhiều làm gì","Chỉ nên cảm ơn những người làm nghề lớn"],answer:0,explain:"Tôn trọng mọi nghề là thái độ đúng đắn của người biết ơn."}]}],challenge:{questions:[{id:"dd4-the-hien-biet-on-28",type:"multi",q:"Những câu nào nói đúng về cách thể hiện lòng biết ơn người lao động?",options:["Biết ơn bằng cả lời nói và việc làm","Chỉ cần nghĩ trong lòng, không cần làm","Giữ gìn, tiết kiệm sản phẩm lao động","Góp ý khi bạn coi thường người lao động"],answers:[0,2,3],explain:"Lòng biết ơn cần được thể hiện bằng thái độ, lời nói và việc làm."},{id:"dd4-the-hien-biet-on-29",type:"mc",q:"Khoa xé giấy vở gấp máy bay rồi vứt khắp lớp. Theo em, điều gì đúng?",options:["Đó chỉ là trò chơi vô hại, không sao","Khoa lãng phí giấy và làm khổ người dọn dẹp","Khoa rất sáng tạo nên không có gì sai"],answer:1,explain:"Việc làm đó chưa tôn trọng sản phẩm và công sức người lao động."},{id:"dd4-the-hien-biet-on-30",type:"tf",q:"Học tập chăm chỉ cũng là một cách biết ơn thầy cô và cha mẹ.",answer:!0,explain:"Đúng. Kết quả học tốt là món quà ý nghĩa với những người vất vả vì em."},{id:"dd4-the-hien-biet-on-20",type:"mc",q:"Ở nhà hàng, Nam thấy anh phục vụ làm đổ cốc nước. Cách cư xử nào là đúng?",options:["Nhẹ nhàng nói không sao và giúp lau","Quát mắng anh ấy","Chụp ảnh đăng lên mạng chê bai"],answer:0,explain:"Ai cũng có lúc sơ suất; thông cảm và giúp đỡ là cách cư xử đẹp."},{id:"dd4-the-hien-biet-on-22",type:"multi",q:"Tùng muốn tỏ lòng biết ơn bác bảo vệ trường. Tùng có thể làm gì?",options:["Chào bác mỗi sáng","Dắt xe vào đúng chỗ, xếp gọn","Làm tấm thiệp cảm ơn bác","Trèo qua cổng khi bác đã khóa"],answers:[0,1,2],explain:"Lễ phép và chấp hành nội quy là cách biết ơn bác bảo vệ."},{id:"dd4-the-hien-biet-on-24",type:"order",q:"Sắp xếp các bước làm tấm thiệp cảm ơn cô lao công.",items:["Chuẩn bị giấy, bút màu","Gấp giấy thành tấm thiệp","Viết lời cảm ơn và trang trí thiệp","Trao thiệp và nói lời cảm ơn cô"],explain:"Làm thiệp theo từng bước giúp món quà thêm chu đáo."}]},summary:["Em thể hiện lòng biết ơn bằng lời nói lễ phép và việc làm phù hợp.","Quý trọng, tiết kiệm sản phẩm là quý trọng công sức người lao động.","Em góp ý nhẹ nhàng khi thấy bạn coi thường người lao động."]}]},{id:"cam-thong-giup-do",title:"Cảm thông, giúp đỡ người gặp khó khăn",lessons:[{id:"dd4-nguoi-gap-kho-khan",title:"Bài 3: Nhận biết người gặp khó khăn",weeks:[5,6],learn:[{title:"Ai đang gặp khó khăn?",text:"Người già yếu, người khuyết tật, người bị ốm, bạn có hoàn cảnh khó khăn, người gặp thiên tai… là những người cần được quan tâm.",example:"👵 cụ già · 🧑‍🦽 người khuyết tật · 🌊 vùng lũ"},{title:"Cảm thông là gì?",text:"Cảm thông là hiểu và chia sẻ nỗi buồn, nỗi vất vả của người khác như thể đặt mình vào hoàn cảnh của họ.",example:"💗 “Nếu mình là bạn ấy…”"},{title:"Vì sao cần cảm thông?",text:"Sự cảm thông giúp người gặp khó khăn thấy ấm lòng, có thêm sức mạnh. Người biết cảm thông cũng được mọi người quý mến.",example:"🤝 lá lành đùm lá rách"}],practice:[{questions:[{id:"dd4-nguoi-gap-kho-khan-01",type:"multi",q:"Những ai dưới đây đang gặp khó khăn, cần được giúp đỡ?",options:["Cụ già đi lại khó khăn","Bạn bị gãy tay phải nghỉ học","Bạn đang vui vẻ chơi đá cầu","Gia đình bị lũ cuốn trôi nhà cửa"],answers:[0,1,3],explain:"Người già yếu, người bị ốm, người gặp thiên tai đều cần được quan tâm."},{id:"dd4-nguoi-gap-kho-khan-02",type:"tf",q:"Cảm thông là hiểu và chia sẻ với nỗi khó khăn của người khác.",answer:!0,explain:"Đúng. Đặt mình vào hoàn cảnh của người khác giúp em biết cảm thông."},{id:"dd4-nguoi-gap-kho-khan-03",type:"tf",q:"Chế giễu bạn khuyết tật chỉ là đùa vui.",answer:!1,explain:"Sai. Chế giễu làm bạn buồn và tổn thương; em cần tôn trọng, giúp đỡ bạn."},{id:"dd4-nguoi-gap-kho-khan-04",type:"mc",q:"Câu tục ngữ nào nói về sự đùm bọc, giúp đỡ nhau?",options:["Lá lành đùm lá rách","Tốt gỗ hơn tốt nước sơn","Ăn chắc mặc bền"],answer:0,explain:"Lá lành đùm lá rách khuyên người may mắn giúp đỡ người gặp khó khăn."},{id:"dd4-nguoi-gap-kho-khan-05",type:"mc",q:"Người khiếm thị gặp khó khăn gì nhất khi đi trên phố?",options:["Không nghe được tiếng xe","Không nhìn thấy đường đi","Không nói được"],answer:1,emoji:"🧑‍🦯",explain:"Người khiếm thị không nhìn rõ, nên rất cần người dẫn đường khi qua đường."},{id:"dd4-nguoi-gap-kho-khan-06",type:"tf",q:"Bạn có hoàn cảnh gia đình khó khăn cũng cần được các bạn quan tâm, chia sẻ.",answer:!0,explain:"Đúng. Một lời hỏi han, chia sẻ đồ dùng sẽ làm bạn thấy ấm áp."},{id:"dd4-nguoi-gap-kho-khan-07",type:"mc",q:"Thái độ nào đúng với người gặp khó khăn?",options:["Tránh xa cho đỡ phiền","Thờ ơ, coi như không thấy","Cảm thông, sẵn lòng giúp đỡ"],answer:2,explain:"Cảm thông và giúp đỡ là thái độ đúng, thể hiện tình yêu thương."},{id:"dd4-nguoi-gap-kho-khan-08",type:"tf",q:"Chỉ người lớn mới cần quan tâm đến người gặp khó khăn.",answer:!1,explain:"Sai. Trẻ em cũng có thể quan tâm, giúp đỡ bằng việc làm vừa sức."},{id:"dd4-nguoi-gap-kho-khan-09",type:"mc",q:"Câu nào thể hiện sự cảm thông với bạn đang buồn?",options:["Bạn đang buồn à, mình ngồi cùng bạn nhé","Buồn thì kệ bạn, mình đi chơi đây","Có thế mà cũng buồn à"],answer:0,explain:"Lời hỏi han nhẹ nhàng giúp bạn thấy mình không cô đơn."}]},{questions:[{id:"dd4-nguoi-gap-kho-khan-10",type:"mc",q:"Vì sao cần cảm thông với người gặp khó khăn?",options:["Vì giúp người khác để được mọi người khen","Vì sự chia sẻ giúp họ ấm lòng, vượt khó","Vì có người bắt buộc mình phải làm vậy"],answer:1,explain:"Cảm thông xuất phát từ tình yêu thương, giúp người khó khăn vững vàng hơn."},{id:"dd4-nguoi-gap-kho-khan-11",type:"match",q:"Nối người gặp khó khăn với điều họ có thể cần.",pairs:[["Cụ già xách nặng","Giúp xách đồ"],["Bạn ốm nghỉ học","Cho mượn vở chép bài"],["Người khiếm thị","Dẫn qua đường"],["Bạn mới chuyển đến","Rủ cùng chơi"]],explain:"Mỗi người gặp khó khăn cần một kiểu giúp đỡ khác nhau."},{id:"dd4-nguoi-gap-kho-khan-12",type:"tf",q:"Người biết cảm thông thường được mọi người yêu quý.",answer:!0,explain:"Đúng. Lòng tốt giúp em có nhiều bạn và được mọi người tin yêu."},{id:"dd4-nguoi-gap-kho-khan-13",type:"tf",q:"Giúp đỡ người khác thì mình sẽ bị thiệt.",answer:!1,explain:"Sai. Giúp đỡ người khác làm em vui và mọi người gắn bó với nhau hơn."},{id:"dd4-nguoi-gap-kho-khan-14",type:"multi",q:"Những việc làm nào thể hiện sự cảm thông?",options:["Hỏi thăm bạn bị ốm","Nhường ghế cho người già trên xe buýt","Cười khi bạn bị ngã","Góp sách vở tặng bạn vùng lũ"],answers:[0,1,3],explain:"Hỏi han, nhường nhịn, chia sẻ đều là biểu hiện của sự cảm thông."},{id:"dd4-nguoi-gap-kho-khan-15",type:"mc",q:"Bạn Phúc đi tập tễnh vì chân bị đau. Bạn nào cư xử đúng?",options:["Bạn Nam bắt chước dáng đi của Phúc","Bạn Minh làm như không thấy","Bạn Thảo đỡ Phúc lên cầu thang"],answer:2,explain:"Đỡ bạn lên cầu thang là việc làm cảm thông, đúng lúc."},{id:"dd4-nguoi-gap-kho-khan-16",type:"mc",q:"Sự cảm thông nên xuất phát từ đâu?",options:["Tình yêu thương thật lòng","Mong muốn được thưởng quà","Nỗi sợ bị cô phê bình"],answer:0,explain:"Giúp đỡ chân thành từ tình yêu thương mới đáng quý."},{id:"dd4-nguoi-gap-kho-khan-17",type:"tf",q:"Ủng hộ đồng bào vùng bão lũ là thể hiện truyền thống tương thân tương ái.",answer:!0,explain:"Đúng. Tương thân tương ái là truyền thống tốt đẹp của người Việt Nam."},{id:"dd4-nguoi-gap-kho-khan-18",type:"mc",q:"Câu nào nói không đúng về người gặp khó khăn?",options:["Họ cần được mọi người tôn trọng","Họ gặp khó khăn là do họ kém cỏi","Họ cần được quan tâm, giúp đỡ"],answer:1,explain:"Khó khăn có thể đến với bất kì ai; không nên đánh giá, coi thường họ."}]},{questions:[{id:"dd4-nguoi-gap-kho-khan-19",type:"mc",q:"Lan thấy một bà cụ đứng mãi ở ngã tư không qua đường được. Lan nên làm gì?",options:["Đứng xem bà khi nào qua được thì thôi","Chạy ra kéo tay bà qua đường thật nhanh","Hỏi bà và nhờ người lớn giúp bà qua đường"],answer:2,explain:"Em hỏi han và nhờ người lớn để giúp bà an toàn."},{id:"dd4-nguoi-gap-kho-khan-20",type:"mc",q:"Bạn Dũng mới chuyển đến lớp, nói giọng vùng khác nên có bạn trêu. Em sẽ làm gì?",options:["Nhắc các bạn đừng trêu và rủ Dũng chơi cùng","Cười theo các bạn cho thật vui","Mặc kệ vì không phải việc của mình"],answer:0,explain:"Giúp bạn hòa nhập là thể hiện sự cảm thông, tôn trọng."},{id:"dd4-nguoi-gap-kho-khan-21",type:"tf",q:"Khi bạn trong lớp có bố bị ốm nặng, em có thể hỏi thăm và động viên bạn.",answer:!0,explain:"Đúng. Lời động viên chân thành giúp bạn vững lòng hơn."},{id:"dd4-nguoi-gap-kho-khan-22",type:"multi",q:"Lớp em có bạn nhà nghèo, thiếu sách vở. Cả lớp có thể làm gì?",options:["Gom sách cũ còn tốt tặng bạn","Cùng học nhóm, giảng bài cho bạn","Bàn tán về hoàn cảnh nhà bạn","Báo cô chủ nhiệm để cùng giúp bạn"],answers:[0,1,3],explain:"Giúp bạn bằng việc làm thiết thực và tế nhị, không làm bạn ngại."},{id:"dd4-nguoi-gap-kho-khan-23",type:"mc",q:"Khi giúp đỡ bạn khó khăn, em nên chú ý điều gì?",options:["Kể cho cả trường biết mình giúp","Giúp tế nhị để bạn không thấy ngại","Đòi bạn trả ơn"],answer:1,explain:"Giúp đỡ tế nhị giữ được lòng tự trọng của người được giúp."},{id:"dd4-nguoi-gap-kho-khan-24",type:"tf",q:"Thấy người bị ngã xe, Nam đứng quay video đăng lên mạng là đúng.",answer:!1,explain:"Sai. Nam nên gọi người lớn đến giúp, không nên quay video người gặp nạn."},{id:"dd4-nguoi-gap-kho-khan-25",type:"mc",q:"Ngọc thấy bạn Vy ngồi khóc một mình trong giờ ra chơi. Cách làm nào phù hợp nhất?",options:["Gọi cả lớp đến xem bạn khóc","Bảo bạn nín ngay, khóc làm gì","Đến ngồi cạnh, hỏi han nhẹ nhàng"],answer:2,explain:"Sự quan tâm nhẹ nhàng giúp bạn mở lòng chia sẻ."},{id:"dd4-nguoi-gap-kho-khan-26",type:"order",q:"Sắp xếp các bước khi muốn giúp một người gặp khó khăn.",items:["Quan sát, nhận ra người cần giúp","Hỏi xem họ cần gì","Giúp bằng việc làm vừa sức","Hỏi lại xem họ đã ổn chưa"],explain:"Hỏi trước, giúp vừa sức và quan tâm đến cùng giúp việc tốt đạt hiệu quả."},{id:"dd4-nguoi-gap-kho-khan-27",type:"mc",q:"Khoa nói: “Bạn ấy nghèo nên mình không chơi cùng.” Em nên nói gì với Khoa?",options:["Bạn ấy vẫn đáng quý, mình nên chơi cùng bạn","Đúng rồi, chơi với bạn ấy chẳng có lợi gì","Thế thì mình cũng sẽ không chơi với bạn ấy"],answer:0,explain:"Em giúp Khoa hiểu rằng ai cũng xứng đáng được tôn trọng."}]}],challenge:{questions:[{id:"dd4-nguoi-gap-kho-khan-28",type:"multi",q:"Những câu nào nói đúng về sự cảm thông?",options:["Là hiểu và chia sẻ với người khác","Chỉ dành cho người quen","Giúp người gặp khó khăn thấy ấm lòng","Thể hiện qua lời nói và việc làm"],answers:[0,2,3],explain:"Cảm thông dành cho tất cả mọi người, thể hiện bằng lời nói và hành động."},{id:"dd4-nguoi-gap-kho-khan-29",type:"tf",q:"Giúp đỡ người khác là phải cho thật nhiều tiền.",answer:!1,explain:"Sai. Một lời hỏi thăm, một việc làm nhỏ vừa sức cũng rất ý nghĩa."},{id:"dd4-nguoi-gap-kho-khan-30",type:"mc",q:"Câu “Một miếng khi đói bằng một gói khi no” có ý nghĩa gì?",options:["Ăn ít khi đói thì tốt cho sức khỏe","Giúp đỡ đúng lúc khó khăn là rất quý","Nên để dành thật nhiều đồ ăn khi no"],answer:1,explain:"Sự giúp đỡ đúng lúc người ta cần là vô cùng quý giá."},{id:"dd4-nguoi-gap-kho-khan-20",type:"mc",q:"Bạn Dũng mới chuyển đến lớp, nói giọng vùng khác nên có bạn trêu. Em sẽ làm gì?",options:["Nhắc các bạn đừng trêu và rủ Dũng chơi cùng","Cười theo các bạn cho thật vui","Mặc kệ vì không phải việc của mình"],answer:0,explain:"Giúp bạn hòa nhập là thể hiện sự cảm thông, tôn trọng."},{id:"dd4-nguoi-gap-kho-khan-22",type:"multi",q:"Lớp em có bạn nhà nghèo, thiếu sách vở. Cả lớp có thể làm gì?",options:["Gom sách cũ còn tốt tặng bạn","Cùng học nhóm, giảng bài cho bạn","Bàn tán về hoàn cảnh nhà bạn","Báo cô chủ nhiệm để cùng giúp bạn"],answers:[0,1,3],explain:"Giúp bạn bằng việc làm thiết thực và tế nhị, không làm bạn ngại."},{id:"dd4-nguoi-gap-kho-khan-26",type:"order",q:"Sắp xếp các bước khi muốn giúp một người gặp khó khăn.",items:["Quan sát, nhận ra người cần giúp","Hỏi xem họ cần gì","Giúp bằng việc làm vừa sức","Hỏi lại xem họ đã ổn chưa"],explain:"Hỏi trước, giúp vừa sức và quan tâm đến cùng giúp việc tốt đạt hiệu quả."}]},summary:["Quanh em có những người đang gặp khó khăn cần được quan tâm.","Cảm thông là hiểu và chia sẻ với hoàn cảnh của người khác.","Không chế giễu, xa lánh người gặp khó khăn."]},{id:"dd4-giup-do-vua-suc",title:"Bài 4: Giúp đỡ người gặp khó khăn",weeks:[7,8],learn:[{title:"Giúp đỡ vừa sức",text:"Em giúp bằng những việc vừa sức như hỏi han, chia sẻ đồ dùng, giảng bài, dẫn đường, quyên góp.",example:"📚 cho mượn vở · 🎒 góp đồ dùng"},{title:"Giúp đỡ an toàn",text:"Việc quá sức hoặc nguy hiểm (người bị tai nạn, đuối nước, cháy…) thì em gọi ngay người lớn hoặc số khẩn cấp.",example:"📞 113 · 114 · 115"},{title:"Giúp đỡ chân thành",text:"Giúp bằng tấm lòng, tế nhị, không chê bai, không kể công, không đòi trả ơn.",example:"💗 tế nhị · 🤝 thật lòng"}],practice:[{questions:[{id:"dd4-giup-do-vua-suc-01",type:"match",q:"Nối số điện thoại khẩn cấp với việc cần gọi.",pairs:[["113","Công an, cần giúp về an ninh"],["114","Cứu hỏa, cứu nạn"],["115","Cấp cứu y tế"]],explain:"Ba số khẩn cấp em cần nhớ: 113, 114, 115."},{id:"dd4-giup-do-vua-suc-02",type:"mc",q:"Thấy khói bốc lên nghi có cháy, em gọi số nào?",options:["114","113","115"],answer:0,emoji:"🔥",explain:"114 là số gọi lực lượng phòng cháy, chữa cháy và cứu nạn."},{id:"dd4-giup-do-vua-suc-03",type:"mc",q:"Có người bị ngất cần cấp cứu, em gọi số nào?",options:["113","115","114"],answer:1,emoji:"🚑",explain:"115 là số gọi cấp cứu y tế."},{id:"dd4-giup-do-vua-suc-04",type:"tf",q:"Giảng bài cho bạn bị ốm nghỉ học là việc giúp đỡ vừa sức.",answer:!0,explain:"Đúng. Đó là việc em làm được và rất có ích cho bạn."},{id:"dd4-giup-do-vua-suc-05",type:"tf",q:"Thấy bạn bị đuối nước, em nên tự nhảy xuống cứu dù không biết bơi giỏi.",answer:!1,explain:"Sai. Em cần hô to gọi người lớn, ném phao hoặc vật nổi; tự nhảy xuống rất nguy hiểm."},{id:"dd4-giup-do-vua-suc-06",type:"multi",q:"Việc nào là giúp đỡ vừa sức với học sinh lớp 4?",options:["Đẩy xe lăn giúp bạn trên sân bằng phẳng","Nhặt giúp đồ bị rơi","Tự sửa đường dây điện bị đứt","Quyên góp sách vở cũ"],answers:[0,1,3],explain:"Em chọn những việc vừa sức, an toàn để giúp đỡ."},{id:"dd4-giup-do-vua-suc-07",type:"mc",q:"Khi giúp đỡ người khác, em nên làm với thái độ thế nào?",options:["Kể công với mọi người","Đòi người ta trả ơn","Chân thành, tế nhị"],answer:2,explain:"Giúp đỡ chân thành mới mang lại niềm vui thật sự."},{id:"dd4-giup-do-vua-suc-08",type:"tf",q:"Gom quần áo cũ còn lành để ủng hộ vùng lũ là việc làm tốt.",answer:!0,explain:"Đúng. Quần áo còn dùng được sẽ giúp ích cho người gặp thiên tai."},{id:"dd4-giup-do-vua-suc-09",type:"mc",q:"Câu nào thể hiện tinh thần giúp đỡ nhau?",options:["Một con ngựa đau, cả tàu bỏ cỏ","Mạnh ai nấy lo, chẳng cần ai","Đèn nhà ai nấy rạng mà thôi"],answer:0,explain:"Câu tục ngữ nói về sự đồng cảm, chia sẻ khi người khác gặp nạn."}]},{questions:[{id:"dd4-giup-do-vua-suc-10",type:"mc",q:"Vì sao gặp việc nguy hiểm em nên gọi người lớn?",options:["Vì em không cần phải giúp ai cả, việc đó khó","Vì người lớn giúp hiệu quả hơn, em cũng an toàn","Vì người lớn thích được trẻ em nhờ việc"],answer:1,explain:"Người lớn có sức và kinh nghiệm để giúp đúng cách."},{id:"dd4-giup-do-vua-suc-11",type:"tf",q:"Đọc truyện cho ông bà mắt kém nghe là việc làm thể hiện sự quan tâm.",answer:!0,explain:"Đúng. Đó là việc nhỏ nhưng làm ông bà vui."},{id:"dd4-giup-do-vua-suc-12",type:"multi",q:"Những cách giúp đỡ nào là tế nhị?",options:["Cho bạn mượn bút mà không kể với ai","Tặng quà rồi đi khoe khắp lớp","Rủ bạn cùng làm bài nhóm","Nhắc mãi rằng mình đã giúp bạn"],answers:[0,2],explain:"Giúp tế nhị là giúp mà không làm người được giúp thấy ngại."},{id:"dd4-giup-do-vua-suc-13",type:"mc",q:"Hành vi nào chưa đúng khi giúp đỡ người khác?",options:["Hỏi xem người đó cần giúp gì","Giúp những việc vừa sức mình","Làm thay toàn bộ bài tập cho bạn"],answer:2,explain:"Làm thay bài khiến bạn không tiến bộ; em nên giảng cho bạn hiểu."},{id:"dd4-giup-do-vua-suc-14",type:"tf",q:"Giúp đỡ bạn tức là cho bạn chép bài trong giờ kiểm tra.",answer:!1,explain:"Sai. Cho chép bài là không trung thực và không giúp bạn tiến bộ."},{id:"dd4-giup-do-vua-suc-15",type:"order",q:"Sắp xếp các việc khi thấy người bị thương trên đường.",items:["Giữ bình tĩnh, đứng ở chỗ an toàn","Gọi người lớn gần đó","Nhờ người lớn gọi 115","Ở lại để chỉ chỗ khi người lớn cần"],explain:"Giữ an toàn cho mình rồi tìm người lớn là cách giúp đúng."},{id:"dd4-giup-do-vua-suc-16",type:"mc",q:"Bà hàng xóm sống một mình bị ốm. Gia đình An có thể làm gì?",options:["Sang thăm hỏi, nấu giúp bát cháo","Không quan tâm vì không phải người nhà","Kể chuyện bà ốm cho cả xóm cười"],answer:0,explain:"Hàng xóm tối lửa tắt đèn có nhau, quan tâm nhau lúc ốm đau."},{id:"dd4-giup-do-vua-suc-17",type:"tf",q:"Kể cả khi không có tiền, em vẫn có thể giúp đỡ người khác.",answer:!0,explain:"Đúng. Em có thể giúp bằng công sức, lời động viên và sự quan tâm."},{id:"dd4-giup-do-vua-suc-18",type:"mc",q:"Bạn Chi bị khiếm thính. Cách nào giúp Chi tham gia giờ học tốt hơn?",options:["Nói thật to vào tai bạn mọi lúc","Ngồi gần, viết ra giấy những điều cô dặn","Không cho Chi tham gia giờ học"],answer:1,explain:"Viết ra giấy giúp Chi nắm được bài, đó là cách giúp đỡ phù hợp."}]},{questions:[{id:"dd4-giup-do-vua-suc-19",type:"mc",q:"Minh thấy em nhỏ lạc mẹ đang khóc ở siêu thị. Minh nên làm gì?",options:["Dắt em bé về nhà mình để chờ mẹ","Đứng nhìn một lúc rồi bỏ đi chỗ khác","Nhờ nhân viên siêu thị hoặc bảo vệ giúp tìm mẹ"],answer:2,explain:"Nhân viên siêu thị có thể thông báo tìm người thân an toàn nhất."},{id:"dd4-giup-do-vua-suc-20",type:"multi",q:"Lớp Tùng tổ chức quyên góp giúp các bạn vùng cao. Tùng có thể góp gì?",options:["Sách giáo khoa cũ còn tốt","Áo ấm còn mặc được","Đồ chơi đã hỏng","Một phần tiền tiết kiệm của mình"],answers:[0,1,3],explain:"Em góp những đồ còn tốt, dùng được để thật sự giúp ích cho bạn."},{id:"dd4-giup-do-vua-suc-21",type:"tf",q:"Bạn Hà gặp khó khăn trong môn Toán, Lan nên làm hộ hết bài về nhà cho Hà.",answer:!1,explain:"Sai. Lan nên cùng ôn bài, giảng giải để Hà tự làm được."},{id:"dd4-giup-do-vua-suc-22",type:"mc",q:"Thấy chú đi xe máy bị ngã, rơi đồ tung tóe, Phúc nên làm gì?",options:["Gọi người lớn đến giúp, đứng ở nơi an toàn","Chạy ngay ra giữa đường nhặt đồ giúp chú","Đứng cười một lúc rồi đi tiếp"],answer:0,explain:"Giữ an toàn và gọi người lớn là cách giúp đỡ phù hợp với em."},{id:"dd4-giup-do-vua-suc-23",type:"mc",q:"Bạn Vy bị bỏng nhẹ ở tay do chạm vào nồi nóng. Ngọc nên làm gì đầu tiên?",options:["Bôi thật nhiều kem đánh răng lên vết bỏng","Gọi người lớn và để vết bỏng dưới vòi nước mát","Lấy băng dính dán chặt lên vết bỏng"],answer:1,explain:"Gọi người lớn và làm mát vết bỏng bằng nước sạch là đúng; không bôi kem đánh răng."},{id:"dd4-giup-do-vua-suc-24",type:"order",q:"Sắp xếp các bước tổ chức một buổi quyên góp nhỏ ở lớp.",items:["Cùng cô bàn kế hoạch","Thông báo cho các bạn","Thu gom và phân loại đồ","Trao tặng đến người cần giúp"],explain:"Có kế hoạch rõ ràng giúp buổi quyên góp thành công."},{id:"dd4-giup-do-vua-suc-25",type:"tf",q:"Sau khi giúp đỡ người khác, em không cần kể công hay đòi trả ơn.",answer:!0,explain:"Đúng. Giúp đỡ bằng tấm lòng mới là giúp đỡ chân thành."},{id:"dd4-giup-do-vua-suc-26",type:"mc",q:"Bình muốn giúp bạn khuyết tật nhưng sợ bạn tự ái. Bình nên làm gì?",options:["Thôi không giúp bạn ấy nữa","Cứ giúp mà không cần hỏi gì","Hỏi bạn: “Bạn có cần mình giúp không?”"],answer:2,explain:"Hỏi trước thể hiện sự tôn trọng và giúp đúng điều bạn cần."},{id:"dd4-giup-do-vua-suc-27",type:"mc",q:"Thấy người lạ nhờ dẫn đường vào ngõ vắng, em nên làm gì?",options:["Chỉ đường bằng lời, không đi theo","Đi theo ngay vì người đó cần giúp","Dẫn vào ngõ rồi về một mình"],answer:0,explain:"Giúp đỡ nhưng vẫn phải giữ an toàn cho bản thân."}]}],challenge:{questions:[{id:"dd4-giup-do-vua-suc-28",type:"multi",q:"Những điều nào em cần nhớ khi giúp đỡ người gặp khó khăn?",options:["Giúp vừa sức, an toàn","Gọi người lớn khi việc nguy hiểm","Giúp xong thì kể khắp nơi","Tôn trọng người được giúp"],answers:[0,1,3],explain:"Giúp an toàn, vừa sức và tôn trọng là ba điều quan trọng."},{id:"dd4-giup-do-vua-suc-29",type:"mc",q:"Trong tình huống nào em gọi 113?",options:["Có người bị ngất trên phố","Thấy kẻ gian đang trộm cắp","Thấy nhà hàng xóm bị cháy"],answer:1,explain:"113 là số gọi công an khi có việc về an ninh, trật tự."},{id:"dd4-giup-do-vua-suc-30",type:"tf",q:"Muốn giúp bạn thì cứ làm theo ý mình, không cần hỏi bạn.",answer:!1,explain:"Sai. Em nên hỏi bạn cần gì để giúp đúng và tôn trọng bạn."},{id:"dd4-giup-do-vua-suc-19",type:"mc",q:"Minh thấy em nhỏ lạc mẹ đang khóc ở siêu thị. Minh nên làm gì?",options:["Dắt em bé về nhà mình để chờ mẹ","Đứng nhìn một lúc rồi bỏ đi chỗ khác","Nhờ nhân viên siêu thị hoặc bảo vệ giúp tìm mẹ"],answer:2,explain:"Nhân viên siêu thị có thể thông báo tìm người thân an toàn nhất."},{id:"dd4-giup-do-vua-suc-22",type:"mc",q:"Thấy chú đi xe máy bị ngã, rơi đồ tung tóe, Phúc nên làm gì?",options:["Gọi người lớn đến giúp, đứng ở nơi an toàn","Chạy ngay ra giữa đường nhặt đồ giúp chú","Đứng cười một lúc rồi đi tiếp"],answer:0,explain:"Giữ an toàn và gọi người lớn là cách giúp đỡ phù hợp với em."},{id:"dd4-giup-do-vua-suc-27",type:"mc",q:"Thấy người lạ nhờ dẫn đường vào ngõ vắng, em nên làm gì?",options:["Chỉ đường bằng lời, không đi theo","Đi theo ngay vì người đó cần giúp","Dẫn vào ngõ rồi về một mình"],answer:0,explain:"Giúp đỡ nhưng vẫn phải giữ an toàn cho bản thân."}]},summary:["Em giúp đỡ người gặp khó khăn bằng những việc làm vừa sức.","Việc nguy hiểm thì gọi người lớn hoặc số khẩn cấp.","Giúp đỡ chân thành, tế nhị, không kể công."]}]},{id:"yeu-lao-dong",title:"Yêu lao động",lessons:[{id:"dd4-y-nghia-lao-dong",title:"Bài 5: Vì sao phải yêu lao động?",weeks:[9,10],learn:[{title:"Lao động là gì?",text:"Lao động là làm việc để tạo ra sản phẩm, của cải hoặc giúp ích cho mình, gia đình và mọi người.",example:"🧹 quét nhà · 🌱 trồng cây · 📚 học tập"},{title:"Ý nghĩa của lao động",text:"Lao động giúp em khỏe mạnh, khéo léo, tự lập, biết quý sức lao động và được mọi người yêu quý.",example:"💪 khỏe · 🙌 khéo tay · 😊 vui"},{title:"Biểu hiện yêu lao động",text:"Chăm chỉ làm việc nhà, việc trường vừa sức; làm đến nơi đến chốn; không ngại khó, ngại bẩn.",example:"✅ làm đến cùng"}],practice:[{questions:[{id:"dd4-y-nghia-lao-dong-01",type:"tf",q:"Lao động giúp con người làm ra của cải và cuộc sống tốt đẹp hơn.",answer:!0,explain:"Đúng. Mọi thứ quanh em đều nhờ lao động mà có."},{id:"dd4-y-nghia-lao-dong-02",type:"multi",q:"Những việc nào là lao động vừa sức của học sinh lớp 4?",options:["Quét nhà","Tưới cây","Trực nhật lớp","Sửa mái nhà"],answers:[0,1,2],explain:"Quét nhà, tưới cây, trực nhật là những việc em làm được."},{id:"dd4-y-nghia-lao-dong-03",type:"mc",q:"Câu tục ngữ nào khuyên chúng ta chăm chỉ lao động?",options:["Tay làm hàm nhai, tay quai miệng trễ","Ăn cỗ đi trước, lội nước theo sau","Đi một ngày đàng, học một sàng khôn"],answer:0,explain:"Có làm thì mới có ăn, lười biếng thì sẽ thiếu thốn."},{id:"dd4-y-nghia-lao-dong-04",type:"tf",q:"Trẻ em không cần tham gia lao động, chỉ cần học.",answer:!1,explain:"Sai. Trẻ em nên làm việc nhà, việc trường vừa sức để rèn luyện bản thân."},{id:"dd4-y-nghia-lao-dong-05",type:"mc",q:"Biểu hiện nào cho thấy một bạn yêu lao động?",options:["Hay tìm cách trốn trực nhật","Hăng hái nhận việc và làm đến cùng","Luôn đợi người khác làm hộ mình"],answer:1,explain:"Hăng hái, làm đến nơi đến chốn là biểu hiện của người yêu lao động."},{id:"dd4-y-nghia-lao-dong-06",type:"tf",q:"Học tập chăm chỉ cũng là một hình thức lao động của học sinh.",answer:!0,explain:"Đúng. Học tập là lao động trí óc của học sinh."},{id:"dd4-y-nghia-lao-dong-07",type:"mc",q:"Biểu hiện nào là lười lao động?",options:["Tự gấp chăn màn mỗi sáng thức dậy","Phụ bố mẹ nấu cơm vào buổi chiều","Ngại bẩn nên không dọn vườn trường"],answer:2,explain:"Ngại bẩn, né tránh công việc chung là biểu hiện lười lao động."},{id:"dd4-y-nghia-lao-dong-08",type:"mc",q:"Lao động mang lại điều gì cho bản thân em?",options:["Khỏe mạnh, khéo léo, tự lập","Mệt mỏi và buồn chán","Chẳng được gì cả"],answer:0,explain:"Lao động giúp em rèn sức khỏe, sự khéo léo và tính tự lập."},{id:"dd4-y-nghia-lao-dong-09",type:"tf",q:"Chỉ những việc lớn mới gọi là lao động.",answer:!1,explain:"Sai. Việc nhỏ như rửa cốc, nhặt rau cũng là lao động có ích."}]},{questions:[{id:"dd4-y-nghia-lao-dong-10",type:"match",q:"Nối việc làm với lợi ích của nó.",pairs:[["Quét nhà","Nhà cửa sạch sẽ"],["Tưới cây","Cây xanh tốt"],["Tự giặt khăn","Biết tự lập"],["Trực nhật","Lớp học gọn gàng"]],explain:"Mỗi việc làm đều đem lại lợi ích rõ ràng."},{id:"dd4-y-nghia-lao-dong-11",type:"mc",q:"Vì sao nói “lao động là vinh quang”?",options:["Vì lao động giúp ai cũng giàu có","Vì lao động tạo ra giá trị cho đời","Vì lao động là việc rất dễ làm"],answer:1,explain:"Người lao động chân chính góp phần làm đẹp cuộc sống nên đáng được tôn vinh."},{id:"dd4-y-nghia-lao-dong-12",type:"tf",q:"Làm việc nhà giúp em hiểu sự vất vả của bố mẹ.",answer:!0,explain:"Đúng. Khi tự làm, em sẽ thêm thương và biết ơn bố mẹ."},{id:"dd4-y-nghia-lao-dong-13",type:"multi",q:"Những biểu hiện nào là yêu lao động?",options:["Tự giác dọn dẹp góc học tập","Không ngại khó khi làm việc","Làm qua loa cho xong","Vui vẻ nhận phần việc được giao"],answers:[0,1,3],explain:"Tự giác, kiên trì và vui vẻ là những biểu hiện của người yêu lao động."},{id:"dd4-y-nghia-lao-dong-14",type:"tf",q:"Người yêu lao động là người làm thật nhanh, dù làm sai cũng được.",answer:!1,explain:"Sai. Yêu lao động là làm cẩn thận, đến nơi đến chốn."},{id:"dd4-y-nghia-lao-dong-15",type:"mc",q:"Bạn nào yêu lao động?",options:["Bạn An nhờ em gái làm hộ việc của mình","Bạn Chi trốn đi chơi khi cả nhà dọn dẹp","Bạn Bình tự giác rửa bát sau bữa cơm"],answer:2,explain:"Tự giác làm phần việc của mình là yêu lao động."},{id:"dd4-y-nghia-lao-dong-16",type:"mc",q:"Ý kiến nào đúng?",options:["Ai cũng cần lao động, tùy theo sức của mình","Lao động chỉ là việc của người lớn","Lao động chỉ làm mất thời gian học"],answer:0,explain:"Mỗi người, kể cả trẻ em, đều lao động theo sức của mình."},{id:"dd4-y-nghia-lao-dong-17",type:"tf",q:"Người yêu lao động thường được mọi người tin tưởng và quý mến.",answer:!0,explain:"Đúng. Sự chăm chỉ, trách nhiệm làm mọi người tin cậy."},{id:"dd4-y-nghia-lao-dong-18",type:"mc",q:"“Có công mài sắt, có ngày nên kim” khuyên em điều gì?",options:["Phải mài sắt thật nhiều mỗi ngày","Kiên trì làm việc thì sẽ thành công","Sắt có thể mài thành cây kim"],answer:1,explain:"Câu tục ngữ khuyên em kiên trì, bền bỉ trong lao động và học tập."}]},{questions:[{id:"dd4-y-nghia-lao-dong-19",type:"mc",q:"Đến lượt trực nhật nhưng Nam muốn ra chơi ngay. Nam nên làm gì?",options:["Bỏ trực nhật để đi chơi ngay","Nhờ bạn làm hộ mà không hỏi","Làm xong trực nhật rồi mới đi chơi"],answer:2,explain:"Hoàn thành việc được giao trước là người có trách nhiệm."},{id:"dd4-y-nghia-lao-dong-20",type:"tf",q:"Thảo nghĩ: “Nhà có người giúp việc rồi, mình không cần làm gì.” Suy nghĩ đó là đúng.",answer:!1,explain:"Sai. Em vẫn nên tự làm việc của mình như gấp quần áo, dọn bàn học."},{id:"dd4-y-nghia-lao-dong-21",type:"mc",q:"Lớp tổ chức trồng cây, Khoa ngại bẩn tay nên đứng ngoài. Em nói với Khoa thế nào?",options:["Mình cùng làm đi, rửa tay sau là sạch mà","Đứng ngoài cũng được, đỡ bẩn tay","Kệ bạn, mình làm phần mình thôi"],answer:0,explain:"Rủ bạn cùng tham gia giúp bạn thấy niềm vui của lao động."},{id:"dd4-y-nghia-lao-dong-22",type:"multi",q:"Hà muốn rèn tính yêu lao động. Hà nên làm gì?",options:["Mỗi ngày nhận một việc nhà vừa sức","Làm cẩn thận đến cùng","Chỉ làm khi được cho tiền","Học thêm cách làm việc mới từ bố mẹ"],answers:[0,1,3],explain:"Làm đều đặn, cẩn thận và học hỏi thêm giúp Hà yêu lao động hơn."},{id:"dd4-y-nghia-lao-dong-23",type:"mc",q:"Minh gấp quần áo lộn xộn cho nhanh để đi xem ti vi. Em góp ý thế nào?",options:["Nhanh là được rồi, gấp thế nào cũng được","Bạn nên gấp cẩn thận, làm đến nơi đến chốn","Bạn cứ để đó, mẹ sẽ gấp lại"],answer:1,explain:"Làm qua loa thì việc không có ích; cần làm cẩn thận."},{id:"dd4-y-nghia-lao-dong-24",type:"tf",q:"Tự nấu được món trứng rán đơn giản với sự giúp đỡ của người lớn làm em thấy vui và tự tin.",answer:!0,explain:"Đúng. Thành quả lao động đem lại niềm vui và sự tự tin."},{id:"dd4-y-nghia-lao-dong-25",type:"mc",q:"Ngày nghỉ, bố mẹ dọn nhà. Việc làm nào của Vy là phù hợp?",options:["Ngồi chơi điện thoại trong phòng","Đòi bố mẹ đưa đi chơi ngay","Lau bàn ghế và sắp xếp lại giá sách"],answer:2,explain:"Cùng làm việc nhà là chia sẻ và yêu lao động."},{id:"dd4-y-nghia-lao-dong-26",type:"order",q:"Sắp xếp các bước trồng một cây hoa nhỏ trong chậu.",items:["Chuẩn bị chậu và đất","Đặt cây vào chậu, vun đất","Tưới nước vừa đủ"],explain:"Làm theo thứ tự giúp cây sống khỏe."},{id:"dd4-y-nghia-lao-dong-27",type:"mc",q:"Phúc nói: “Lao động chân tay là việc của người không chịu học.” Ý kiến này thế nào?",options:["Sai, vì lao động nào cũng đáng quý","Đúng, vì chỉ học giỏi mới đáng quý","Đúng, vì lao động chân tay rất dễ"],answer:0,explain:"Mọi lao động chân chính đều đáng quý, không phân biệt chân tay hay trí óc."}]}],challenge:{questions:[{id:"dd4-y-nghia-lao-dong-28",type:"multi",q:"Những câu nào nói đúng về lao động?",options:["Lao động tạo ra của cải","Lao động giúp con người phát triển","Người lười biếng vẫn được mọi người quý","Học sinh cũng cần lao động vừa sức"],answers:[0,1,3],explain:"Lao động có ích cho mỗi người và cho xã hội."},{id:"dd4-y-nghia-lao-dong-29",type:"mc",q:"Câu nào trái ngược với tinh thần yêu lao động?",options:["Làm việc đến nơi đến chốn","Ngồi mát ăn bát vàng","Siêng làm thì có"],answer:1,explain:"“Ngồi mát ăn bát vàng” chỉ người lười biếng mà muốn hưởng thụ."},{id:"dd4-y-nghia-lao-dong-30",type:"tf",q:"Người yêu lao động biết quý trọng thành quả lao động của mình và của người khác.",answer:!0,explain:"Đúng. Hiểu sự vất vả nên biết giữ gìn thành quả lao động."},{id:"dd4-y-nghia-lao-dong-20",type:"tf",q:"Thảo nghĩ: “Nhà có người giúp việc rồi, mình không cần làm gì.” Suy nghĩ đó là đúng.",answer:!1,explain:"Sai. Em vẫn nên tự làm việc của mình như gấp quần áo, dọn bàn học."},{id:"dd4-y-nghia-lao-dong-22",type:"multi",q:"Hà muốn rèn tính yêu lao động. Hà nên làm gì?",options:["Mỗi ngày nhận một việc nhà vừa sức","Làm cẩn thận đến cùng","Chỉ làm khi được cho tiền","Học thêm cách làm việc mới từ bố mẹ"],answers:[0,1,3],explain:"Làm đều đặn, cẩn thận và học hỏi thêm giúp Hà yêu lao động hơn."},{id:"dd4-y-nghia-lao-dong-26",type:"order",q:"Sắp xếp các bước trồng một cây hoa nhỏ trong chậu.",items:["Chuẩn bị chậu và đất","Đặt cây vào chậu, vun đất","Tưới nước vừa đủ"],explain:"Làm theo thứ tự giúp cây sống khỏe."}]},summary:["Lao động đem lại của cải và niềm vui cho cuộc sống.","Lao động giúp em khỏe mạnh, khéo léo và tự lập.","Yêu lao động là chăm chỉ làm việc và làm đến nơi đến chốn."]},{id:"dd4-cham-chi-lam-viec",title:"Bài 6: Chăm chỉ làm việc vừa sức",weeks:[11,12],learn:[{title:"Việc nhà vừa sức",text:"Gấp quần áo, dọn bàn học, quét nhà, nhặt rau, rửa cốc, tưới cây là những việc em làm được.",example:"👕 gấp áo · 🥬 nhặt rau"},{title:"Làm việc có kế hoạch",text:"Ghi ra những việc cần làm, chia thời gian hợp lí giữa học, làm việc nhà và nghỉ ngơi.",example:"📝 danh sách việc · ⏰ giờ giấc"},{title:"Làm việc an toàn",text:"Không tự dùng dao sắc, bếp ga, ổ điện khi chưa có người lớn hướng dẫn.",example:"⚠️ hỏi người lớn trước"}],practice:[{questions:[{id:"dd4-cham-chi-lam-viec-01",type:"multi",q:"Những việc nào vừa sức với em?",options:["Gấp quần áo","Nhặt rau","Thay bóng đèn trên trần","Tưới cây"],answers:[0,1,3],explain:"Gấp quần áo, nhặt rau, tưới cây là những việc em làm an toàn."},{id:"dd4-cham-chi-lam-viec-02",type:"tf",q:"Dọn dẹp bàn học sau khi học xong là thói quen tốt.",answer:!0,explain:"Đúng. Góc học tập gọn gàng giúp em học tốt hơn."},{id:"dd4-cham-chi-lam-viec-03",type:"tf",q:"Em có thể tự cắm và rút ổ điện bằng tay ướt.",answer:!1,explain:"Sai. Tay ướt chạm điện rất nguy hiểm, em phải lau khô tay và hỏi người lớn."},{id:"dd4-cham-chi-lam-viec-04",type:"mc",q:"Muốn làm việc nhà đều đặn, em nên làm gì?",options:["Lập danh sách việc và giờ làm mỗi ngày","Làm khi nào thấy thích thì làm","Chờ bố mẹ nhắc nhở rồi mới làm"],answer:0,explain:"Danh sách và giờ giấc rõ ràng giúp em làm đều đặn."},{id:"dd4-cham-chi-lam-viec-05",type:"mc",q:"Việc nào em KHÔNG nên tự làm khi chưa có người lớn?",options:["Quét nhà và lau bàn","Dùng dao sắc thái thịt","Gấp quần áo vào tủ"],answer:1,explain:"Dao sắc dễ gây đứt tay, cần người lớn hướng dẫn."},{id:"dd4-cham-chi-lam-viec-06",type:"tf",q:"Làm việc chăm chỉ không có nghĩa là làm quá sức.",answer:!0,explain:"Đúng. Em cần chọn việc vừa sức và nghỉ ngơi hợp lí."},{id:"dd4-cham-chi-lam-viec-07",type:"mc",q:"Biểu hiện của bạn chăm chỉ là gì?",options:["Làm được một lúc thì bỏ dở","Chỉ làm khi có người khen","Kiên trì làm cho xong việc"],answer:2,explain:"Kiên trì làm xong việc là biểu hiện của sự chăm chỉ."},{id:"dd4-cham-chi-lam-viec-08",type:"match",q:"Nối việc với nơi em thường làm.",pairs:[["Trực nhật","Ở lớp"],["Gấp chăn màn","Ở nhà"],["Nhặt rác sân trường","Ở trường"],["Tưới cây","Ở vườn"]],explain:"Em có thể lao động ở nhiều nơi khác nhau."},{id:"dd4-cham-chi-lam-viec-09",type:"tf",q:"Làm việc nhà xong thì không cần cất dụng cụ về chỗ cũ.",answer:!1,explain:"Sai. Cất dụng cụ đúng chỗ giúp nhà gọn gàng và lần sau dễ tìm."}]},{questions:[{id:"dd4-cham-chi-lam-viec-10",type:"mc",q:"Vì sao em nên lập danh sách việc cần làm?",options:["Để không quên việc và làm có trật tự","Để khoe với các bạn trong lớp","Để có cớ làm ít việc hơn mọi ngày"],answer:0,explain:"Danh sách giúp em nhớ việc và làm có trật tự."},{id:"dd4-cham-chi-lam-viec-11",type:"tf",q:"Chia thời gian hợp lí giữa học, làm việc nhà và vui chơi giúp em khỏe mạnh, vui vẻ.",answer:!0,explain:"Đúng. Cân bằng giúp em làm tốt mọi việc."},{id:"dd4-cham-chi-lam-viec-12",type:"multi",q:"Những cách làm việc nào là chăm chỉ và đúng cách?",options:["Làm cẩn thận từng bước","Hỏi người lớn khi chưa biết làm","Làm vội rồi bỏ dở","Kiểm tra lại sau khi làm"],answers:[0,1,3],explain:"Làm cẩn thận, biết hỏi và kiểm tra lại giúp công việc đạt kết quả tốt."},{id:"dd4-cham-chi-lam-viec-13",type:"mc",q:"Bạn Lan làm việc nhà rất vui vẻ. Điều đó cho thấy gì?",options:["Lan bị bắt buộc","Lan yêu lao động","Lan không có bài tập"],answer:1,explain:"Vui vẻ làm việc là dấu hiệu của tình yêu lao động."},{id:"dd4-cham-chi-lam-viec-14",type:"tf",q:"Làm thật nhiều việc nhà đến mức không còn thời gian học là chăm chỉ.",answer:!1,explain:"Sai. Chăm chỉ cần đi đôi với sắp xếp hợp lí, không bỏ bê việc học."},{id:"dd4-cham-chi-lam-viec-15",type:"mc",q:"Khi rửa bát, điều nào cần chú ý?",options:["Rửa thật nhanh, không cần sạch","Để bát bẩn qua đêm","Cầm chắc tay, cẩn thận để không vỡ"],answer:2,explain:"Cẩn thận giúp bát sạch và không bị vỡ."},{id:"dd4-cham-chi-lam-viec-16",type:"mc",q:"Vì sao không nên tự dùng bếp ga khi chưa được hướng dẫn?",options:["Vì dễ gây bỏng, cháy nổ","Vì bếp ga rất đắt tiền","Vì bếp ga rất bẩn tay"],answer:0,explain:"Bếp ga có lửa và khí ga, dùng sai cách rất nguy hiểm."},{id:"dd4-cham-chi-lam-viec-17",type:"order",q:"Sắp xếp các bước quét nhà.",items:["Dọn đồ vật gọn sang một bên","Quét từ trong ra ngoài","Gom rác lại rồi hốt vào xẻng","Đổ rác vào thùng và cất chổi"],explain:"Làm theo thứ tự giúp nhà sạch và gọn."},{id:"dd4-cham-chi-lam-viec-18",type:"tf",q:"Biết tự phục vụ bản thân là bước đầu của tính tự lập.",answer:!0,explain:"Đúng. Tự làm việc của mình giúp em ngày càng trưởng thành."}]},{questions:[{id:"dd4-cham-chi-lam-viec-19",type:"mc",q:"An hay quên trực nhật. An có thể làm gì để nhớ?",options:["Nhờ bạn khác làm thay mãi mãi","Ghi lịch trực vào sổ và đặt lời nhắc","Bỏ luôn, không trực nhật nữa"],answer:1,explain:"Ghi lịch và nhắc nhở giúp An thực hiện đều đặn."},{id:"dd4-cham-chi-lam-viec-20",type:"multi",q:"Chủ nhật, Chi muốn giúp mẹ chuẩn bị bữa cơm. Việc nào phù hợp với Chi?",options:["Nhặt và rửa rau","Bày bát đũa","Tự đun dầu để rán","Lau bàn ăn"],answers:[0,1,3],explain:"Chi làm những việc an toàn, còn việc đun nấu dầu nóng để người lớn làm."},{id:"dd4-cham-chi-lam-viec-21",type:"tf",q:"Thấy việc khó, Dũng bỏ dở và nói “để mai làm” nhiều lần là thói quen tốt.",answer:!1,explain:"Sai. Dũng nên chia nhỏ việc và kiên trì làm cho xong."},{id:"dd4-cham-chi-lam-viec-22",type:"mc",q:"Minh làm xong bài tập nhưng còn nhiều đồ chơi bừa bộn. Minh nên làm gì trước khi đi ngủ?",options:["Để mai mẹ dọn giúp","Đẩy hết vào gầm giường","Tự xếp đồ chơi vào hộp"],answer:2,explain:"Tự dọn đồ của mình là chăm chỉ và có trách nhiệm."},{id:"dd4-cham-chi-lam-viec-23",type:"mc",q:"Ngọc lần đầu tự giặt khăn mặt nhưng chưa sạch. Ngọc nên làm gì?",options:["Nhờ mẹ chỉ cách và thử lại","Bỏ, không bao giờ giặt nữa","Giấu khăn đi để mẹ không thấy"],answer:0,explain:"Học hỏi và thử lại giúp Ngọc làm tốt hơn."},{id:"dd4-cham-chi-lam-viec-24",type:"order",q:"Sắp xếp các bước rửa bát sau bữa ăn.",items:["Bỏ thức ăn thừa ra khỏi bát","Rửa bát bằng nước rửa bát","Tráng lại bằng nước sạch","Úp bát lên giá cho ráo nước"],explain:"Rửa bát theo thứ tự giúp bát sạch và gọn gàng."},{id:"dd4-cham-chi-lam-viec-25",type:"tf",q:"Khi được giao việc ở lớp, em cố gắng làm tốt dù không có ai khen.",answer:!0,explain:"Đúng. Làm việc vì trách nhiệm, không phải vì lời khen."},{id:"dd4-cham-chi-lam-viec-26",type:"mc",q:"Bạn Vy làm vườn cùng ông bị mỏi tay. Vy nên làm gì?",options:["Cố làm thật nhiều đến kiệt sức","Nghỉ một chút rồi làm tiếp","Bỏ dở và về nhà luôn"],answer:1,explain:"Nghỉ ngơi hợp lí giúp Vy làm tiếp tốt hơn."},{id:"dd4-cham-chi-lam-viec-27",type:"mc",q:"Khoa muốn tự nấu mì. Cách làm nào đúng?",options:["Tự bật bếp khi ở nhà một mình","Đổ nước sôi bằng một tay vội vàng","Nhờ người lớn đứng bên hướng dẫn"],answer:2,explain:"Có người lớn hướng dẫn giúp Khoa an toàn."}]}],challenge:{questions:[{id:"dd4-cham-chi-lam-viec-28",type:"multi",q:"Những điều nào giúp em làm việc chăm chỉ và hiệu quả?",options:["Có kế hoạch rõ ràng","Chọn việc vừa sức","Làm khi có hứng","Làm đến nơi đến chốn"],answers:[0,1,3],explain:"Kế hoạch, vừa sức và kiên trì giúp em làm việc hiệu quả."},{id:"dd4-cham-chi-lam-viec-29",type:"tf",q:"Chăm chỉ là làm được thật nhiều việc mà không cần nghỉ ngơi.",answer:!1,explain:"Sai. Nghỉ ngơi hợp lí giúp em khỏe mạnh và làm tốt hơn."},{id:"dd4-cham-chi-lam-viec-30",type:"mc",q:"Câu nào thể hiện tinh thần tự lập trong lao động?",options:["Việc của mình thì mình tự làm","Việc gì cũng chờ mẹ làm","Để khi khác rồi làm sau"],answer:0,explain:"Tự làm việc của mình là bước đầu của tính tự lập."},{id:"dd4-cham-chi-lam-viec-20",type:"multi",q:"Chủ nhật, Chi muốn giúp mẹ chuẩn bị bữa cơm. Việc nào phù hợp với Chi?",options:["Nhặt và rửa rau","Bày bát đũa","Tự đun dầu để rán","Lau bàn ăn"],answers:[0,1,3],explain:"Chi làm những việc an toàn, còn việc đun nấu dầu nóng để người lớn làm."},{id:"dd4-cham-chi-lam-viec-23",type:"mc",q:"Ngọc lần đầu tự giặt khăn mặt nhưng chưa sạch. Ngọc nên làm gì?",options:["Nhờ mẹ chỉ cách và thử lại","Bỏ, không bao giờ giặt nữa","Giấu khăn đi để mẹ không thấy"],answer:0,explain:"Học hỏi và thử lại giúp Ngọc làm tốt hơn."},{id:"dd4-cham-chi-lam-viec-24",type:"order",q:"Sắp xếp các bước rửa bát sau bữa ăn.",items:["Bỏ thức ăn thừa ra khỏi bát","Rửa bát bằng nước rửa bát","Tráng lại bằng nước sạch","Úp bát lên giá cho ráo nước"],explain:"Rửa bát theo thứ tự giúp bát sạch và gọn gàng."}]},summary:["Em chọn những việc vừa sức và làm thường xuyên.","Làm việc có kế hoạch, cẩn thận, đến nơi đến chốn.","Luôn giữ an toàn khi lao động."]}]},{id:"ton-trong-tai-san",title:"Tôn trọng tài sản của người khác",lessons:[{id:"dd4-tai-san-nguoi-khac",title:"Bài 7: Tài sản của người khác",weeks:[13,14],learn:[{title:"Tài sản là gì?",text:"Tài sản là đồ vật, tiền bạc, nhà cửa… thuộc quyền sở hữu của một người hay một gia đình.",example:"🎒 cặp sách · 🚲 xe đạp · 📱 điện thoại"},{title:"Tôn trọng tài sản của người khác",text:"Không tự ý lấy, dùng, xem, làm hỏng đồ của người khác. Muốn dùng thì phải hỏi mượn và được đồng ý.",example:"🙋 “Cho mình mượn nhé?”"},{title:"Vì sao phải tôn trọng?",text:"Tôn trọng tài sản của người khác là sống trung thực, giữ được lòng tin và đúng với quy định của pháp luật.",example:"⚖️ trung thực · 🤝 tin tưởng"}],practice:[{questions:[{id:"dd4-tai-san-nguoi-khac-01",type:"multi",q:"Đồ vật nào dưới đây là tài sản?",options:["Chiếc xe đạp của bạn","Quyển truyện của anh","Chiếc điện thoại của bố","Bộ bàn ghế trong nhà"],answers:[0,1,2,3],explain:"Đó đều là tài sản thuộc về một người hoặc một gia đình."},{id:"dd4-tai-san-nguoi-khac-02",type:"tf",q:"Muốn dùng đồ của bạn, em cần hỏi mượn và được bạn đồng ý.",answer:!0,explain:"Đúng. Hỏi mượn là tôn trọng bạn và tài sản của bạn."},{id:"dd4-tai-san-nguoi-khac-03",type:"tf",q:"Thấy bút của bạn đẹp, em có thể tự lấy dùng vì bạn sẽ không biết.",answer:!1,explain:"Sai. Tự ý lấy đồ của người khác là không trung thực."},{id:"dd4-tai-san-nguoi-khac-04",type:"mc",q:"Việc làm nào thể hiện tôn trọng tài sản của người khác?",options:["Hỏi mượn trước khi dùng","Tự ý mở cặp của bạn","Vẽ vào sách của bạn"],answer:0,explain:"Hỏi mượn trước là cách cư xử đúng."},{id:"dd4-tai-san-nguoi-khac-05",type:"mc",q:"Việc làm nào chưa tôn trọng tài sản của người khác?",options:["Trả sách mượn đúng hẹn","Bẻ hoa trong vườn nhà hàng xóm","Giữ cẩn thận đồ đi mượn"],answer:1,explain:"Bẻ hoa nhà người khác là xâm phạm tài sản của họ."},{id:"dd4-tai-san-nguoi-khac-06",type:"mc",q:"Mượn đồ của bạn xong, em cần làm gì?",options:["Giữ luôn vì bạn không đòi","Cho người khác mượn tiếp luôn","Trả lại đúng hẹn, còn nguyên vẹn"],answer:2,explain:"Trả đúng hẹn, giữ nguyên vẹn là giữ chữ tín."},{id:"dd4-tai-san-nguoi-khac-07",type:"tf",q:"Tôn trọng tài sản của người khác là thể hiện sự trung thực.",answer:!0,explain:"Đúng. Người trung thực không lấy những gì không thuộc về mình."},{id:"dd4-tai-san-nguoi-khac-08",type:"tf",q:"Đồ của bạn thân thì em được tự ý lấy dùng.",answer:!1,explain:"Sai. Dù là bạn thân, em vẫn cần hỏi trước."},{id:"dd4-tai-san-nguoi-khac-09",type:"mc",q:"Tự ý đọc nhật kí của bạn là hành vi thế nào?",options:["Chưa tôn trọng sự riêng tư của bạn","Bình thường vì là bạn cùng lớp","Đáng khen vì quan tâm đến bạn"],answer:0,explain:"Nhật kí là đồ riêng tư; em không tự ý đọc khi bạn chưa cho phép."}]},{questions:[{id:"dd4-tai-san-nguoi-khac-10",type:"mc",q:"Vì sao phải tôn trọng tài sản của người khác?",options:["Vì sợ bị người khác bắt gặp và phạt","Vì đó là sống trung thực, đúng pháp luật","Vì đồ của người khác chẳng đẹp bằng"],answer:1,explain:"Tôn trọng tài sản là sống trung thực và tuân thủ pháp luật."},{id:"dd4-tai-san-nguoi-khac-11",type:"match",q:"Nối hành vi với nhận xét đúng.",pairs:[["Hỏi mượn trước khi dùng","Lịch sự, tôn trọng"],["Làm hỏng đồ rồi giấu đi","Thiếu trung thực"],["Trả đồ đúng hẹn","Giữ chữ tín"]],explain:"Mỗi hành vi cho thấy em có tôn trọng tài sản hay không."},{id:"dd4-tai-san-nguoi-khac-12",type:"multi",q:"Những hành vi nào xâm phạm tài sản của người khác?",options:["Lấy tiền trong ví của người khác","Viết bậy lên tường nhà hàng xóm","Mượn sách và trả đúng hẹn","Tự ý dùng điện thoại của anh để chơi trò chơi"],answers:[0,1,3],explain:"Lấy, phá hỏng hay tự ý dùng đều là xâm phạm tài sản."},{id:"dd4-tai-san-nguoi-khac-13",type:"tf",q:"Làm hỏng đồ của bạn, em cần xin lỗi và tìm cách sửa hoặc đền.",answer:!0,explain:"Đúng. Nhận lỗi và sửa chữa là cách cư xử có trách nhiệm."},{id:"dd4-tai-san-nguoi-khac-14",type:"tf",q:"Chỉ những đồ đắt tiền mới cần được tôn trọng.",answer:!1,explain:"Sai. Đồ nhỏ như chiếc bút, cục tẩy cũng là tài sản cần tôn trọng."},{id:"dd4-tai-san-nguoi-khac-15",type:"mc",q:"Người tôn trọng tài sản của người khác sẽ được gì?",options:["Bị mọi người xa lánh, chê cười","Chẳng được gì cả","Được mọi người tin tưởng, quý mến"],answer:2,explain:"Lòng tin của mọi người là món quà quý của người trung thực."},{id:"dd4-tai-san-nguoi-khac-16",type:"mc",q:"Câu tục ngữ nào khuyên em dù khó khăn cũng không lấy của người khác?",options:["Đói cho sạch, rách cho thơm","Ăn vóc học hay","Uống nước nhớ nguồn"],answer:0,explain:"“Đói cho sạch, rách cho thơm” khuyên ta luôn sống trong sạch, ngay thẳng dù nghèo khó."},{id:"dd4-tai-san-nguoi-khac-17",type:"tf",q:"Tự ý trèo vào vườn nhà người khác hái quả là không tôn trọng tài sản.",answer:!0,explain:"Đúng. Muốn hái quả phải được chủ vườn đồng ý."},{id:"dd4-tai-san-nguoi-khac-18",type:"mc",q:"Vì sao không nên tự ý dùng máy tính của bố mẹ?",options:["Vì máy tính nặng, em không cầm được","Vì đó là đồ của bố mẹ, cần xin phép","Vì máy tính chẳng có gì vui cả"],answer:1,explain:"Hỏi xin phép là tôn trọng bố mẹ và đồ dùng của bố mẹ."}]},{questions:[{id:"dd4-tai-san-nguoi-khac-19",type:"mc",q:"Nam thấy bạn để quên hộp bút đẹp trên bàn. Nam nên làm gì?",options:["Mang về nhà dùng thử","Bỏ vào thùng rác cho gọn","Cất giữ và trả lại cho bạn"],answer:2,explain:"Giữ hộ và trả lại là việc làm trung thực."},{id:"dd4-tai-san-nguoi-khac-20",type:"mc",q:"Lan lỡ làm rách trang truyện mượn của Hà. Lan nên làm gì?",options:["Xin lỗi Hà và dán lại cẩn thận","Trả lại và coi như không có chuyện gì","Nói rằng em trai đã làm rách"],answer:0,explain:"Thành thật nhận lỗi và sửa chữa giữ được tình bạn."},{id:"dd4-tai-san-nguoi-khac-21",type:"tf",q:"Thấy bạn để quên tiền trong ngăn bàn, Khoa nghĩ “ai nhặt được thì của người ấy”. Khoa nghĩ đúng.",answer:!1,explain:"Sai. Khoa nên báo cô giáo để trả lại tiền cho bạn."},{id:"dd4-tai-san-nguoi-khac-22",type:"multi",q:"Bình muốn chơi chiếc xe đồ chơi của em họ. Cách làm nào đúng?",options:["Hỏi em xem có cho mượn không","Giành lấy vì mình là anh","Chơi cẩn thận rồi trả lại","Cảm ơn em sau khi chơi"],answers:[0,2,3],explain:"Hỏi, giữ gìn và cảm ơn là cách tôn trọng đồ của người khác."},{id:"dd4-tai-san-nguoi-khac-23",type:"mc",q:"Phúc mượn xe đạp của bạn nhưng làm xịt lốp. Phúc nên làm gì?",options:["Trả lại xe và im lặng không nói","Báo cho bạn biết và cùng nhờ người lớn sửa","Nói dối là xe đã hỏng từ trước"],answer:1,explain:"Trung thực và chịu trách nhiệm là cách cư xử đúng."},{id:"dd4-tai-san-nguoi-khac-24",type:"tf",q:"Vy mượn bút của bạn, dùng xong đậy nắp cẩn thận rồi trả và cảm ơn bạn. Vy làm đúng.",answer:!0,explain:"Đúng. Vy giữ gìn đồ đi mượn và biết cảm ơn."},{id:"dd4-tai-san-nguoi-khac-25",type:"mc",q:"Chi thấy bạn đang lén lấy sticker trong hộp của bạn khác. Chi nên làm gì?",options:["Giả vờ như không nhìn thấy gì","Xin bạn chia cho mình một nửa","Nhắc bạn trả lại, cần thì báo cô"],answer:2,explain:"Nhắc nhở bạn giúp bạn sửa sai và bảo vệ đồ của người khác."},{id:"dd4-tai-san-nguoi-khac-26",type:"mc",q:"Ngọc cầm nhầm áo khoác của bạn về nhà. Ngọc nên làm gì?",options:["Hôm sau mang trả bạn và xin lỗi","Giữ luôn vì áo rất đẹp","Vứt đi cho khỏi phiền phức"],answer:0,explain:"Trả lại và xin lỗi là trung thực, có trách nhiệm."},{id:"dd4-tai-san-nguoi-khac-27",type:"order",q:"Sắp xếp các việc khi mượn sách của bạn.",items:["Hỏi mượn và hẹn ngày trả","Đọc và giữ gìn cẩn thận","Trả sách đúng hẹn","Cảm ơn bạn"],explain:"Mượn và trả đúng cách giúp bạn tin em hơn."}]}],challenge:{questions:[{id:"dd4-tai-san-nguoi-khac-28",type:"multi",q:"Những câu nào nói đúng về tôn trọng tài sản của người khác?",options:["Không tự ý lấy, dùng đồ của người khác","Bạn thân thì không cần hỏi","Làm hỏng thì nhận lỗi và sửa","Trả đồ mượn đúng hẹn"],answers:[0,2,3],explain:"Hỏi trước, giữ gìn, trả đúng hẹn và nhận lỗi là những điều em cần nhớ."},{id:"dd4-tai-san-nguoi-khac-29",type:"mc",q:"Dũng nói: “Mình chỉ mượn tạm điện thoại của anh, không cần hỏi vì anh đang ngủ.” Em nghĩ sao?",options:["Dũng làm đúng","Dũng nên chờ anh dậy và hỏi mượn","Dũng nên giấu điện thoại đi"],answer:1,explain:"Dù là người thân, em vẫn cần hỏi trước khi dùng đồ."},{id:"dd4-tai-san-nguoi-khac-30",type:"tf",q:"Tôn trọng tài sản của người khác chỉ cần làm khi có người nhìn thấy.",answer:!1,explain:"Sai. Người trung thực tôn trọng tài sản cả khi không ai nhìn thấy."},{id:"dd4-tai-san-nguoi-khac-20",type:"mc",q:"Lan lỡ làm rách trang truyện mượn của Hà. Lan nên làm gì?",options:["Xin lỗi Hà và dán lại cẩn thận","Trả lại và coi như không có chuyện gì","Nói rằng em trai đã làm rách"],answer:0,explain:"Thành thật nhận lỗi và sửa chữa giữ được tình bạn."},{id:"dd4-tai-san-nguoi-khac-22",type:"multi",q:"Bình muốn chơi chiếc xe đồ chơi của em họ. Cách làm nào đúng?",options:["Hỏi em xem có cho mượn không","Giành lấy vì mình là anh","Chơi cẩn thận rồi trả lại","Cảm ơn em sau khi chơi"],answers:[0,2,3],explain:"Hỏi, giữ gìn và cảm ơn là cách tôn trọng đồ của người khác."},{id:"dd4-tai-san-nguoi-khac-23",type:"mc",q:"Phúc mượn xe đạp của bạn nhưng làm xịt lốp. Phúc nên làm gì?",options:["Trả lại xe và im lặng không nói","Báo cho bạn biết và cùng nhờ người lớn sửa","Nói dối là xe đã hỏng từ trước"],answer:1,explain:"Trung thực và chịu trách nhiệm là cách cư xử đúng."}]},summary:["Tài sản của người khác cần được tôn trọng như của chính mình.","Không tự ý lấy, dùng hay làm hỏng đồ của người khác.","Tôn trọng tài sản giúp em được mọi người tin yêu."]},{id:"dd4-muon-nhat-duoc-do",title:"Bài 8: Ứng xử với đồ đi mượn và đồ nhặt được",weeks:[15,16],learn:[{title:"Khi mượn đồ",text:"Hỏi mượn lịch sự, hẹn ngày trả, giữ gìn cẩn thận, trả đúng hẹn và cảm ơn.",example:"📘 mượn – giữ – trả – cảm ơn"},{title:"Khi nhặt được đồ",text:"Tìm cách trả lại người mất: hỏi xung quanh, đưa cho thầy cô, bảo vệ hoặc công an. Không giữ làm của riêng.",example:"👛 nhặt được ví → trả lại"},{title:"Khi làm hỏng, làm mất",text:"Thành thật báo cho chủ đồ vật, xin lỗi và tìm cách sửa chữa hoặc đền bù.",example:"🙇 “Mình xin lỗi, mình sẽ sửa lại.”"}],practice:[{questions:[{id:"dd4-muon-nhat-duoc-do-01",type:"tf",q:"Nhặt được của rơi, em tìm cách trả lại người mất.",answer:!0,explain:"Đúng. Đó là việc làm trung thực đáng khen."},{id:"dd4-muon-nhat-duoc-do-02",type:"tf",q:"Nhặt được tiền ở sân trường thì được giữ làm của riêng.",answer:!1,explain:"Sai. Em cần đưa cho thầy cô để tìm người đánh rơi."},{id:"dd4-muon-nhat-duoc-do-03",type:"mc",q:"Nhặt được chiếc ví trên đường, em nên đưa cho ai?",options:["Công an hoặc người lớn tin cậy","Một bạn nhỏ đang chơi gần đó","Người lạ đi ngang qua"],answer:0,explain:"Công an hoặc người lớn tin cậy sẽ giúp tìm người mất."},{id:"dd4-muon-nhat-duoc-do-04",type:"mc",q:"Ở trường, nhặt được đồ của người khác, em đưa cho ai?",options:["Bạn ngồi cùng bàn","Thầy cô hoặc bác bảo vệ","Không đưa cho ai cả"],answer:1,explain:"Thầy cô, bác bảo vệ sẽ giúp trả lại cho người mất."},{id:"dd4-muon-nhat-duoc-do-05",type:"order",q:"Sắp xếp các việc khi mượn đồ dùng của bạn.",items:["Hỏi mượn lịch sự","Giữ gìn cẩn thận","Trả đúng hẹn","Cảm ơn bạn"],explain:"Mượn đúng cách là tôn trọng bạn và đồ của bạn."},{id:"dd4-muon-nhat-duoc-do-06",type:"tf",q:"Làm mất đồ đi mượn, em cần báo cho chủ và tìm cách đền bù.",answer:!0,explain:"Đúng. Thành thật và chịu trách nhiệm là cách cư xử đúng."},{id:"dd4-muon-nhat-duoc-do-07",type:"mc",q:"Câu nói nào phù hợp khi mượn đồ?",options:["Đưa cái thước đây cho mình","Mình lấy cái thước nhé","Cho mình mượn thước nhé"],answer:2,explain:"Lời hỏi mượn lịch sự làm người khác vui lòng."},{id:"dd4-muon-nhat-duoc-do-08",type:"mc",q:"Hành vi nào là trung thực?",options:["Nhặt được bút thì hỏi xem của bạn nào","Nhặt được bút thì giấu vào cặp mình","Thấy đồ rơi thì đá đi chỗ khác"],answer:0,explain:"Hỏi để trả lại là việc làm trung thực."},{id:"dd4-muon-nhat-duoc-do-09",type:"tf",q:"Mượn sách của thư viện thì không cần giữ gìn vì là của chung.",answer:!1,explain:"Sai. Sách thư viện còn phục vụ nhiều bạn, cần giữ gìn cẩn thận."}]},{questions:[{id:"dd4-muon-nhat-duoc-do-10",type:"match",q:"Nối tình huống với cách ứng xử đúng.",pairs:[["Nhặt được ví","Đưa cho công an hoặc người lớn"],["Làm hỏng đồ mượn","Xin lỗi và sửa hoặc đền"],["Mượn truyện của bạn","Giữ gìn và trả đúng hẹn"],["Cầm nhầm đồ của bạn","Trả lại và xin lỗi"]],explain:"Mỗi tình huống có một cách ứng xử trung thực, có trách nhiệm."},{id:"dd4-muon-nhat-duoc-do-11",type:"mc",q:"Vì sao phải trả lại của rơi?",options:["Vì trả lại thì chắc chắn được thưởng","Vì người mất đang rất lo lắng","Vì sợ có người nhìn thấy mình nhặt"],answer:1,explain:"Hiểu nỗi lo của người mất, em sẽ muốn trả lại ngay."},{id:"dd4-muon-nhat-duoc-do-12",type:"tf",q:"Trả lại của rơi giúp em được mọi người tin tưởng.",answer:!0,explain:"Đúng. Người trung thực luôn được tin yêu."},{id:"dd4-muon-nhat-duoc-do-13",type:"tf",q:"Giấu đồ bị hỏng để bạn không biết là cách giữ tình bạn.",answer:!1,explain:"Sai. Giấu giếm làm mất lòng tin; nói thật mới giữ được tình bạn."},{id:"dd4-muon-nhat-duoc-do-14",type:"multi",q:"Những việc làm nào là đúng khi mượn đồ?",options:["Hẹn ngày trả","Dùng đúng mục đích","Cho người khác mượn lại mà không hỏi","Trả lại sạch sẽ"],answers:[0,1,3],explain:"Mượn đồ cần hẹn trả, dùng đúng và giữ sạch."},{id:"dd4-muon-nhat-duoc-do-15",type:"mc",q:"Bạn hỏi mượn đồ mà em đang cần dùng, em có thể nói gì?",options:["Không, mình không bao giờ cho ai mượn đồ","Lờ đi, coi như không nghe bạn hỏi","Mình đang dùng, lát nữa cho bạn mượn nhé"],answer:2,explain:"Từ chối khéo léo và hẹn lúc khác vẫn là cư xử lịch sự."},{id:"dd4-muon-nhat-duoc-do-16",type:"mc",q:"Câu nào nói về sự trung thực?",options:["Thật thà là cha quỷ quái","Chậm mà chắc","Nói một đằng làm một nẻo"],answer:0,explain:"Câu tục ngữ khen người thật thà, trung thực."},{id:"dd4-muon-nhat-duoc-do-17",type:"tf",q:"Khi chưa tìm được người mất, em có thể nhờ cô giáo thông báo cho cả trường.",answer:!0,explain:"Đúng. Thông báo giúp người mất biết để đến nhận lại."},{id:"dd4-muon-nhat-duoc-do-18",type:"order",q:"Sắp xếp các việc khi nhặt được chiếc mũ ở sân trường.",items:["Hỏi các bạn xung quanh","Mang đến cho cô giáo","Cô thông báo tìm người mất","Trả lại cho người mất"],explain:"Làm theo thứ tự giúp chiếc mũ về đúng với chủ."}]},{questions:[{id:"dd4-muon-nhat-duoc-do-19",type:"mc",q:"Minh nhặt được một chiếc điện thoại ở công viên. Minh nên làm gì?",options:["Mang về nhà chơi trò chơi","Nhờ bố mẹ đưa đến công an","Cho bạn thân để bạn dùng"],answer:1,explain:"Nhờ người lớn giúp là cách an toàn và trung thực."},{id:"dd4-muon-nhat-duoc-do-20",type:"mc",q:"Hà mượn bộ bút màu của Chi và lỡ làm gãy một cây. Hà nên làm gì?",options:["Trả lại và im lặng như không có gì","Nói rằng chính Chi làm gãy","Xin lỗi Chi và đền cây bút khác"],answer:2,explain:"Thành thật nhận lỗi và đền bù là cách giữ tình bạn."},{id:"dd4-muon-nhat-duoc-do-21",type:"tf",q:"An nhặt được tiền, tìm mãi không thấy người mất nên nộp cho cô giáo. An làm đúng.",answer:!0,explain:"Đúng. Cô giáo sẽ giúp tìm người mất."},{id:"dd4-muon-nhat-duoc-do-22",type:"multi",q:"Bạn mượn em quyển truyện đã lâu chưa trả. Em có thể làm gì?",options:["Nhẹ nhàng nhắc bạn","Hỏi bạn đã đọc xong chưa","Đi kể xấu bạn khắp lớp","Lấy đồ của bạn để trừ"],answers:[0,1],explain:"Nhắc nhẹ nhàng là cách cư xử lịch sự, giữ tình bạn."},{id:"dd4-muon-nhat-duoc-do-23",type:"mc",q:"Tùng mượn sách thư viện và để em nhỏ vẽ vào. Tùng nên làm gì?",options:["Báo với cô thư viện và xin đền bù","Trả lại và mong không ai nhìn thấy","Giữ luôn quyển sách, coi như mất"],answer:0,explain:"Thành thật với cô thư viện là cách làm đúng."},{id:"dd4-muon-nhat-duoc-do-24",type:"tf",q:"Thấy bạn cũ không nhớ đã cho mình mượn tiền, Khoa không trả nữa. Khoa làm đúng.",answer:!1,explain:"Sai. Mượn thì phải trả, dù người cho mượn có quên."},{id:"dd4-muon-nhat-duoc-do-25",type:"mc",q:"Vy nhặt được chiếc vòng tay đẹp trên xe buýt. Vy nên làm gì?",options:["Đeo luôn vì không ai biết","Đưa cho bác tài xế","Để lại trên ghế rồi xuống xe"],answer:1,explain:"Người phụ trách xe sẽ giúp tìm người đánh rơi."},{id:"dd4-muon-nhat-duoc-do-26",type:"mc",q:"Thảo hứa trả sách hôm thứ Hai nhưng quên mang. Thảo nên làm gì?",options:["Không nói gì, coi như quên","Bảo bạn tự đến nhà mình lấy","Xin lỗi bạn và hẹn trả ngay hôm sau"],answer:2,explain:"Giữ lời hứa, nếu lỡ quên thì xin lỗi và sửa ngay."},{id:"dd4-muon-nhat-duoc-do-27",type:"mc",q:"Phúc nhặt được chiếc chìa khóa trước cổng nhà hàng xóm. Phúc nên làm gì?",options:["Hỏi xem có phải chìa khóa nhà bác không","Vứt vào bụi cây cho gọn","Giữ lại để làm đồ chơi"],answer:0,explain:"Hỏi những người gần nơi nhặt được giúp trả lại nhanh nhất."}]}],challenge:{questions:[{id:"dd4-muon-nhat-duoc-do-28",type:"multi",q:"Những việc nào thể hiện sự trung thực, có trách nhiệm với đồ của người khác?",options:["Trả lại của rơi","Đền khi làm hỏng đồ mượn","Nói dối để khỏi bị trách","Nhắc bạn trả lại đồ lấy nhầm"],answers:[0,1,3],explain:"Trung thực và có trách nhiệm là những đức tính đáng quý."},{id:"dd4-muon-nhat-duoc-do-29",type:"tf",q:"Nhặt được đồ ít tiền thì không cần trả lại.",answer:!1,explain:"Sai. Đồ nhỏ hay lớn đều là của người khác, em vẫn cần trả lại."},{id:"dd4-muon-nhat-duoc-do-30",type:"mc",q:"Chi mượn áo mưa của bạn, hôm sau trời nắng. Chi nên làm gì?",options:["Giữ luôn, khi nào mưa trả","Phơi khô, gấp gọn và trả bạn","Cho người khác mượn tiếp"],answer:1,explain:"Trả lại sớm, sạch sẽ là tôn trọng đồ của bạn."},{id:"dd4-muon-nhat-duoc-do-19",type:"mc",q:"Minh nhặt được một chiếc điện thoại ở công viên. Minh nên làm gì?",options:["Mang về nhà chơi trò chơi","Nhờ bố mẹ đưa đến công an","Cho bạn thân để bạn dùng"],answer:1,explain:"Nhờ người lớn giúp là cách an toàn và trung thực."},{id:"dd4-muon-nhat-duoc-do-22",type:"multi",q:"Bạn mượn em quyển truyện đã lâu chưa trả. Em có thể làm gì?",options:["Nhẹ nhàng nhắc bạn","Hỏi bạn đã đọc xong chưa","Đi kể xấu bạn khắp lớp","Lấy đồ của bạn để trừ"],answers:[0,1],explain:"Nhắc nhẹ nhàng là cách cư xử lịch sự, giữ tình bạn."},{id:"dd4-muon-nhat-duoc-do-23",type:"mc",q:"Tùng mượn sách thư viện và để em nhỏ vẽ vào. Tùng nên làm gì?",options:["Báo với cô thư viện và xin đền bù","Trả lại và mong không ai nhìn thấy","Giữ luôn quyển sách, coi như mất"],answer:0,explain:"Thành thật với cô thư viện là cách làm đúng."}]},summary:["Đồ đi mượn phải giữ gìn và trả đúng hẹn.","Nhặt được của rơi thì tìm cách trả lại người mất.","Làm hỏng, làm mất đồ thì thành thật nhận lỗi và sửa chữa."]}]},{id:"bao-ve-cua-cong",title:"Bảo vệ của công",lessons:[{id:"dd4-cua-cong",title:"Bài 9: Của công quanh em",weeks:[17,18],learn:[{title:"Của công là gì?",text:"Của công là tài sản chung của Nhà nước, của tập thể, phục vụ lợi ích của mọi người.",example:"🏫 trường học · 🌳 công viên · 🚏 nhà chờ xe buýt"},{title:"Vì sao phải bảo vệ của công?",text:"Của công được làm ra bằng công sức, tiền bạc của nhiều người và phục vụ mọi người, nên ai cũng có trách nhiệm giữ gìn.",example:"💡 đèn đường · 🛝 cầu trượt"},{title:"Hành vi làm hại của công",text:"Vẽ bậy, bẻ cây, phá đèn đường, lấy cắp đồ dùng chung, lãng phí điện nước nơi công cộng.",example:"🚫 vẽ bậy · 🚫 bẻ cây"}],practice:[{questions:[{id:"dd4-cua-cong-01",type:"multi",q:"Đâu là của công?",options:["Bàn ghế trong lớp học","Cây xanh trên vỉa hè","Đèn chiếu sáng trên đường","Chiếc cặp sách của em"],answers:[0,1,2],explain:"Bàn ghế, cây xanh, đèn đường là tài sản chung; cặp sách là đồ riêng của em."},{id:"dd4-cua-cong-02",type:"tf",q:"Của công là tài sản chung phục vụ lợi ích của mọi người.",answer:!0,explain:"Đúng. Trường học, công viên, đường sá… đều là của công."},{id:"dd4-cua-cong-03",type:"tf",q:"Của công là của chung nên ai muốn lấy về nhà cũng được.",answer:!1,explain:"Sai. Của chung phục vụ mọi người, không ai được lấy làm của riêng."},{id:"dd4-cua-cong-04",type:"mc",q:"Việc làm nào là bảo vệ của công?",options:["Giữ gìn sách thư viện cẩn thận","Viết tên lên ghế đá công viên","Đu lên cành cây ven đường"],answer:0,explain:"Giữ gìn sách thư viện là bảo vệ tài sản chung."},{id:"dd4-cua-cong-05",type:"mc",q:"Việc làm nào là phá hoại của công?",options:["Tắt quạt khi ra khỏi lớp","Ném đá vào đèn đường","Xếp ghế gọn gàng"],answer:1,explain:"Ném đá vào đèn đường làm hỏng tài sản chung và gây nguy hiểm."},{id:"dd4-cua-cong-06",type:"mc",q:"Cây xanh trong công viên thuộc về ai?",options:["Là của người đã trồng cây","Là của người ở gần công viên","Là của công, phục vụ mọi người"],answer:2,emoji:"🌳",explain:"Cây xanh nơi công cộng là của công, mọi người cùng hưởng và cùng giữ gìn."},{id:"dd4-cua-cong-07",type:"tf",q:"Tắt đèn, tắt quạt khi ra khỏi lớp là bảo vệ của công.",answer:!0,explain:"Đúng. Tiết kiệm điện ở trường cũng là giữ gìn của công."},{id:"dd4-cua-cong-08",type:"tf",q:"Vẽ lên tường nhà vệ sinh của trường thì không sao vì ít người thấy.",answer:!1,explain:"Sai. Đó vẫn là làm hỏng của công."},{id:"dd4-cua-cong-09",type:"mc",q:"Ai có trách nhiệm bảo vệ của công?",options:["Tất cả mọi người, kể cả học sinh","Chỉ bác bảo vệ trông coi","Chỉ những người lớn tuổi"],answer:0,explain:"Của công phục vụ mọi người nên ai cũng có trách nhiệm giữ gìn."}]},{questions:[{id:"dd4-cua-cong-10",type:"mc",q:"Vì sao phải bảo vệ của công?",options:["Vì của công là đồ của riêng người quản lí","Vì của công phục vụ tất cả mọi người","Vì sợ bị bác bảo vệ nhìn thấy và nhắc nhở"],answer:1,explain:"Bảo vệ của công là giữ lợi ích chung của tất cả mọi người."},{id:"dd4-cua-cong-11",type:"match",q:"Nối của công với cách giữ gìn.",pairs:[["Bàn ghế lớp học","Không viết vẽ, không đứng lên"],["Sách thư viện","Không làm rách, trả đúng hạn"],["Cây xanh","Không bẻ cành, khắc lên thân"],["Vòi nước ở trường","Dùng xong khóa chặt"]],explain:"Mỗi loại của công có cách giữ gìn phù hợp."},{id:"dd4-cua-cong-12",type:"tf",q:"Khi của công bị hỏng, tất cả mọi người đều chịu thiệt.",answer:!0,explain:"Đúng. Của công hỏng thì không ai dùng được, lại tốn tiền sửa chữa."},{id:"dd4-cua-cong-13",type:"multi",q:"Hành vi nào làm hại của công?",options:["Để vòi nước ở trường chảy mãi","Khắc tên lên thân cây","Nhặt rác bỏ vào thùng","Bẻ hoa ở vườn trường"],answers:[0,1,3],explain:"Lãng phí và phá hoại đều làm hại của công."},{id:"dd4-cua-cong-14",type:"tf",q:"Lãng phí điện nước ở trường không phải là làm hại của công.",answer:!1,explain:"Sai. Lãng phí điện nước cũng là làm hao tốn của công."},{id:"dd4-cua-cong-15",type:"mc",q:"Bảo vệ của công thể hiện đức tính gì?",options:["Chỉ biết lo cho bản thân","Thích được người khác khen","Có trách nhiệm với cộng đồng"],answer:2,explain:"Người bảo vệ của công là người có trách nhiệm với mọi người."},{id:"dd4-cua-cong-16",type:"mc",q:"Phá hoại của công là hành vi thế nào?",options:["Sai trái, vi phạm quy định và pháp luật","Được phép nếu người làm là trẻ em","Bình thường, ai cũng từng làm"],answer:0,explain:"Phá hoại của công là vi phạm nội quy và pháp luật."},{id:"dd4-cua-cong-17",type:"tf",q:"Ngồi trên xe buýt, không rạch ghế, không vẽ lên kính là bảo vệ của công.",answer:!0,explain:"Đúng. Xe buýt công cộng phục vụ rất nhiều người."},{id:"dd4-cua-cong-18",type:"mc",q:"Vì sao không nên đứng lên ghế đá công viên?",options:["Vì ghế đá rất lạnh vào mùa đông","Vì dễ làm bẩn, hỏng ghế và dễ bị ngã","Vì ghế đá quá thấp so với em"],answer:1,explain:"Giữ ghế đá sạch đẹp cho người khác ngồi và giữ an toàn cho em."}]},{questions:[{id:"dd4-cua-cong-19",type:"mc",q:"Nam thấy bạn khắc tên lên bàn học. Nam nên làm gì?",options:["Khắc tên mình bên cạnh","Mặc kệ bạn làm gì thì làm","Nhắc bạn dừng lại"],answer:2,explain:"Nhắc nhở bạn là góp phần bảo vệ của công."},{id:"dd4-cua-cong-20",type:"mc",q:"Ra về, Lan thấy vòi nước ở sân trường đang chảy. Lan nên làm gì?",options:["Khóa vòi lại","Đi luôn","Chờ người khác khóa"],answer:0,explain:"Khóa vòi nước là việc nhỏ giúp tiết kiệm của công."},{id:"dd4-cua-cong-21",type:"tf",q:"Thấy cột đèn đường bị đổ dây điện xuống đất, em tránh xa và báo người lớn.",answer:!0,explain:"Đúng. Em giữ an toàn và báo người lớn để báo cho người có trách nhiệm sửa."},{id:"dd4-cua-cong-22",type:"multi",q:"Đi chơi công viên, lớp Hà có thể làm gì để bảo vệ của công?",options:["Bỏ rác đúng nơi","Không bẻ cây, hái hoa","Leo lên tượng để chụp ảnh","Đi đúng lối, không giẫm lên cỏ"],answers:[0,1,3],explain:"Giữ vệ sinh, không phá cây và đi đúng lối là bảo vệ công viên."},{id:"dd4-cua-cong-23",type:"mc",q:"Bình thấy một nhóm anh lớn đang phá ghế ở nhà chờ xe buýt. Bình nên làm gì?",options:["Lao vào ngăn cản một mình","Tránh xa và báo người lớn hoặc công an","Đứng lại xem cho vui"],answer:1,explain:"Báo người có trách nhiệm là cách an toàn để bảo vệ của công."},{id:"dd4-cua-cong-24",type:"tf",q:"Chi mượn sách thư viện rồi xé trang có hình đẹp để dán vào vở. Chi làm vậy không sao.",answer:!1,explain:"Sai. Xé sách thư viện là làm hỏng của công, các bạn khác không đọc được."},{id:"dd4-cua-cong-25",type:"mc",q:"Thấy cửa sổ lớp bị lỏng bản lề, Khoa nên làm gì?",options:["Đập mạnh cho rơi luôn","Tự trèo lên cửa sổ để sửa","Báo cô giáo để nhờ người sửa"],answer:2,explain:"Báo người lớn giúp sửa kịp thời và an toàn."},{id:"dd4-cua-cong-26",type:"order",q:"Sắp xếp các việc khi mượn sách ở thư viện trường.",items:["Chọn sách muốn đọc","Đưa sách cho cô thủ thư ghi mượn","Đọc và giữ gìn sách cẩn thận","Trả sách đúng hạn"],explain:"Mượn và trả đúng cách giúp sách thư viện phục vụ được nhiều bạn."},{id:"dd4-cua-cong-27",type:"mc",q:"Vy nói: “Đèn đường của Nhà nước, hỏng thì Nhà nước sửa, mình không cần giữ.” Em nghĩ sao?",options:["Chưa đúng, của chung thì ai cũng phải giữ","Đúng, vì đèn đường không phải của nhà mình","Đúng, vì hỏng thì sẽ có đèn mới đẹp hơn"],answer:0,explain:"Của công là của chung, mọi người đều cần giữ gìn."}]}],challenge:{questions:[{id:"dd4-cua-cong-28",type:"multi",q:"Những câu nào nói đúng về của công?",options:["Là tài sản chung","Phục vụ lợi ích mọi người","Ai lấy trước là của người đó","Mọi người đều có trách nhiệm giữ gìn"],answers:[0,1,3],explain:"Của công thuộc về tất cả và cần mọi người cùng bảo vệ."},{id:"dd4-cua-cong-29",type:"tf",q:"Bảo vệ của công là việc riêng của cơ quan nhà nước.",answer:!1,explain:"Sai. Đó là trách nhiệm của mọi người, kể cả học sinh."},{id:"dd4-cua-cong-30",type:"mc",q:"Câu nào thể hiện thái độ đúng với của công?",options:["Cha chung không ai khóc","Giữ của chung như giữ của nhà mình","Của chung thì không cần giữ gìn"],answer:1,explain:"Giữ của chung như của nhà là thái độ có trách nhiệm."},{id:"dd4-cua-cong-22",type:"multi",q:"Đi chơi công viên, lớp Hà có thể làm gì để bảo vệ của công?",options:["Bỏ rác đúng nơi","Không bẻ cây, hái hoa","Leo lên tượng để chụp ảnh","Đi đúng lối, không giẫm lên cỏ"],answers:[0,1,3],explain:"Giữ vệ sinh, không phá cây và đi đúng lối là bảo vệ công viên."},{id:"dd4-cua-cong-23",type:"mc",q:"Bình thấy một nhóm anh lớn đang phá ghế ở nhà chờ xe buýt. Bình nên làm gì?",options:["Lao vào ngăn cản một mình","Tránh xa và báo người lớn hoặc công an","Đứng lại xem cho vui"],answer:1,explain:"Báo người có trách nhiệm là cách an toàn để bảo vệ của công."},{id:"dd4-cua-cong-26",type:"order",q:"Sắp xếp các việc khi mượn sách ở thư viện trường.",items:["Chọn sách muốn đọc","Đưa sách cho cô thủ thư ghi mượn","Đọc và giữ gìn sách cẩn thận","Trả sách đúng hạn"],explain:"Mượn và trả đúng cách giúp sách thư viện phục vụ được nhiều bạn."}]},summary:["Của công là tài sản chung phục vụ lợi ích của mọi người.","Mỗi người đều có trách nhiệm bảo vệ của công.","Phá hoại, lãng phí của công là việc làm sai."]},{id:"dd4-giu-gin-cua-cong",title:"Bài 10: Em giữ gìn của công",weeks:[19,20],learn:[{title:"Giữ gìn ở trường",text:"Không viết, vẽ lên bàn ghế, tường; giữ gìn sách thư viện, đồ dùng chung; tiết kiệm điện nước.",example:"🏫 lớp sạch · 📚 sách lành"},{title:"Giữ gìn nơi công cộng",text:"Không bẻ cây, hái hoa, giẫm lên cỏ; không phá ghế đá, đèn đường, biển báo; bỏ rác đúng nơi.",example:"🌷 vườn hoa · 🚏 biển báo"},{title:"Khi thấy của công bị phá",text:"Nhắc nhở nhẹ nhàng nếu an toàn; nếu nguy hiểm thì tránh xa và báo người lớn, thầy cô, công an.",example:"📢 báo người lớn"}],practice:[{questions:[{id:"dd4-giu-gin-cua-cong-01",type:"tf",q:"Bỏ rác vào thùng ở công viên là giữ gìn của công.",answer:!0,explain:"Đúng. Công viên sạch đẹp là niềm vui chung."},{id:"dd4-giu-gin-cua-cong-02",type:"tf",q:"Hái hoa ở vườn hoa công cộng để tặng mẹ là việc làm tốt.",answer:!1,explain:"Sai. Hoa nơi công cộng để mọi người cùng ngắm, không được hái."},{id:"dd4-giu-gin-cua-cong-03",type:"mc",q:"Biển báo giao thông bị cong là do có người đu lên. Hành vi đó thế nào?",options:["Làm hỏng của công và nguy hiểm","Vui và vô hại, không sao cả","Một cách rèn luyện sức khỏe"],answer:0,explain:"Biển báo hỏng làm người đi đường không nhìn rõ, dễ xảy ra tai nạn."},{id:"dd4-giu-gin-cua-cong-04",type:"mc",q:"Việc nào giúp giữ gìn sách thư viện?",options:["Gấp mép trang để đánh dấu","Dùng thẻ đánh dấu trang","Ăn uống khi đọc sách"],answer:1,explain:"Dùng thẻ đánh dấu giúp sách không bị quăn mép."},{id:"dd4-giu-gin-cua-cong-05",type:"multi",q:"Ở trường, em giữ gìn của công bằng cách nào?",options:["Không vẽ lên tường","Tắt điện khi ra về","Dùng đồ chơi chung nhẹ nhàng","Đá bóng vào cửa kính"],answers:[0,1,2],explain:"Giữ gìn đồ chung giúp trường luôn sạch đẹp."},{id:"dd4-giu-gin-cua-cong-06",type:"tf",q:"Thấy bạn đá vào thùng rác của trường, em có thể nhắc bạn dừng lại.",answer:!0,explain:"Đúng. Nhắc nhở nhẹ nhàng giúp bạn sửa sai."},{id:"dd4-giu-gin-cua-cong-07",type:"mc",q:"Thấy người lạ đang cắt trộm dây điện, em nên làm gì?",options:["Đến gần hỏi xem họ làm gì","Đứng lại xem một lúc rồi về","Tránh xa, báo ngay người lớn hoặc công an"],answer:2,explain:"Em phải giữ an toàn cho mình trước, rồi báo người có trách nhiệm."},{id:"dd4-giu-gin-cua-cong-08",type:"mc",q:"Ở bể bơi công cộng, việc làm nào đúng?",options:["Giữ vệ sinh, theo nội quy","Vứt vỏ chai xuống bể bơi","Rạch thủng phao bơi chung"],answer:0,explain:"Theo nội quy giúp mọi người cùng sử dụng an toàn, sạch sẽ."},{id:"dd4-giu-gin-cua-cong-09",type:"tf",q:"Giẫm lên thảm cỏ có biển “Không giẫm lên cỏ” một chút thì không sao.",answer:!1,explain:"Sai. Mỗi người giẫm một chút, thảm cỏ sẽ trụi hết."}]},{questions:[{id:"dd4-giu-gin-cua-cong-10",type:"match",q:"Nối của công với hành vi làm hại cần tránh.",pairs:[["Bàn ghế","Viết, vẽ, khắc lên"],["Cây xanh","Bẻ cành, khắc thân"],["Đèn đường","Ném đá"],["Nhà vệ sinh trường","Vẽ bậy lên tường"]],explain:"Biết hành vi làm hại để em tránh và nhắc bạn tránh."},{id:"dd4-giu-gin-cua-cong-11",type:"tf",q:"Giữ gìn của công cũng giúp tiết kiệm tiền của cho đất nước.",answer:!0,explain:"Đúng. Của công bền lâu thì ít tốn tiền sửa chữa, thay mới."},{id:"dd4-giu-gin-cua-cong-12",type:"mc",q:"Tại sao khi thấy kẻ xấu phá hoại của công, em không nên tự ngăn cản?",options:["Vì đó không phải việc của em","Vì có thể nguy hiểm cho em","Vì phá hoại của công là chuyện nhỏ"],answer:1,explain:"Em bảo vệ của công nhưng luôn phải giữ an toàn cho bản thân."},{id:"dd4-giu-gin-cua-cong-13",type:"multi",q:"Những việc nào là lãng phí của công?",options:["Bật quạt lớp khi không có ai","Xả nước rửa tay mà không khóa vòi","Tắt đèn khi ra về","Lấy nhiều giấy vệ sinh để nghịch"],answers:[0,1,3],explain:"Lãng phí điện, nước, đồ dùng chung đều là làm hao tổn của công."},{id:"dd4-giu-gin-cua-cong-14",type:"tf",q:"Của công ở xa nhà mình thì mình không cần giữ gìn.",answer:!1,explain:"Sai. Của công ở đâu cũng phục vụ mọi người, em đều cần giữ gìn."},{id:"dd4-giu-gin-cua-cong-15",type:"mc",q:"Lớp em được giao chăm sóc một bồn hoa của trường. Lớp nên làm gì?",options:["Thỉnh thoảng nhớ ra thì tưới","Để bác bảo vệ làm hết mọi việc","Phân công tưới cây, nhổ cỏ đều đặn"],answer:2,explain:"Phân công rõ ràng giúp bồn hoa luôn tươi tốt."},{id:"dd4-giu-gin-cua-cong-16",type:"mc",q:"Bạn Phúc viết lên tường lớp vì “tường đã bẩn sẵn”. Lời góp ý nào phù hợp?",options:["Mình cùng giữ cho tường sạch dần nhé","Tường bẩn rồi thì viết thêm cũng được","Bạn viết nhỏ thôi là không ai thấy"],answer:0,explain:"Mỗi người góp phần giữ sạch thì tường mới sạch được."},{id:"dd4-giu-gin-cua-cong-17",type:"tf",q:"Đi tham quan bảo tàng, không chạm vào hiện vật khi chưa được phép là bảo vệ của công.",answer:!0,explain:"Đúng. Hiện vật bảo tàng là tài sản quý của đất nước."},{id:"dd4-giu-gin-cua-cong-18",type:"order",q:"Sắp xếp các việc khi thấy bạn làm hỏng đồ chơi chung ở sân trường.",items:["Nhắc bạn dừng lại","Báo thầy cô hoặc bác bảo vệ","Đồ chơi được sửa chữa","Các bạn lại cùng chơi an toàn"],explain:"Báo kịp thời giúp sửa chữa và giữ an toàn cho mọi người."}]},{questions:[{id:"dd4-giu-gin-cua-cong-19",type:"mc",q:"Đi xe buýt, Tùng thấy bạn nhỏ dùng bút vẽ lên ghế. Tùng có thể làm gì?",options:["Lấy bút vẽ cùng bạn cho vui","Nhẹ nhàng nhắc bạn dừng lại","Quát mắng bạn thật to"],answer:1,explain:"Nhắc nhẹ nhàng giúp bạn hiểu và bảo vệ ghế xe chung."},{id:"dd4-giu-gin-cua-cong-20",type:"multi",q:"Khu phố tổ chức trồng cây xanh. Thảo có thể góp phần thế nào?",options:["Cùng bố mẹ tham gia trồng cây","Tưới cây trước nhà","Nhổ cây non về trồng ở nhà","Nhắc các em nhỏ không bẻ cây"],answers:[0,1,3],explain:"Trồng, chăm sóc và bảo vệ cây xanh là giữ gìn của công."},{id:"dd4-giu-gin-cua-cong-21",type:"tf",q:"Dũng nhặt được chiếc ghế nhựa của lớp bị gãy chân nên báo ngay cho cô. Dũng làm đúng.",answer:!0,explain:"Đúng. Báo kịp thời giúp sửa ghế và tránh bạn khác bị ngã."},{id:"dd4-giu-gin-cua-cong-22",type:"mc",q:"Ngọc mượn bóng của trường để chơi giờ ra chơi. Hết giờ, Ngọc nên làm gì?",options:["Mang bóng về nhà","Để bóng ngoài sân","Cất bóng về đúng chỗ"],answer:2,explain:"Cất đồ chung đúng chỗ để lần sau các bạn khác dùng tiếp."},{id:"dd4-giu-gin-cua-cong-23",type:"mc",q:"Một nhóm bạn hái trộm xoài ở vườn trường. Minh nên làm gì?",options:["Không tham gia và nhắc các bạn","Hái cùng vì xoài của trường mà","Đứng canh cho các bạn hái"],answer:0,explain:"Minh không tham gia và giúp các bạn hiểu đó là việc sai."},{id:"dd4-giu-gin-cua-cong-24",type:"tf",q:"Thấy ống nước ở công viên bị vỡ, nước chảy lênh láng, An bỏ đi vì không phải nhà mình. An làm đúng.",answer:!1,explain:"Sai. An nên báo người lớn hoặc người quản lí công viên để sửa kịp thời."},{id:"dd4-giu-gin-cua-cong-25",type:"mc",q:"Lớp tổ chức thi “Lớp học xanh – sạch – đẹp”. Ý tưởng nào là bảo vệ của công?",options:["Mang đồ ở nhà đến để rồi vứt lại","Làm bảng nhắc tắt điện, khóa nước","Dán băng dính khắp bàn để trang trí"],answer:1,explain:"Bảng nhắc nhở giúp cả lớp tiết kiệm và giữ gìn của công."},{id:"dd4-giu-gin-cua-cong-26",type:"order",q:"Sắp xếp các bước tổ chức buổi “Ngày giữ gìn của công” ở lớp.",items:["Cùng cô lên kế hoạch","Chia nhóm và phân công việc","Lau bàn ghế, dọn sách thư viện lớp","Cùng nhau nhận xét, rút kinh nghiệm"],explain:"Có kế hoạch và phân công giúp buổi làm việc hiệu quả."},{id:"dd4-giu-gin-cua-cong-27",type:"mc",q:"Hà thấy trên mạng có người khoe ảnh vẽ bậy lên tượng đài. Hà nên nghĩ thế nào?",options:["Thật vui, ảnh chụp rất đẹp","Mình cũng muốn thử một lần","Đó là việc làm sai, không nên bắt chước"],answer:2,explain:"Tượng đài là của công và công trình văn hóa, cần được tôn trọng."}]}],challenge:{questions:[{id:"dd4-giu-gin-cua-cong-28",type:"multi",q:"Những việc làm nào thể hiện em giữ của chung như của nhà mình?",options:["Tiết kiệm điện nước ở trường","Bảo quản sách thư viện","Mang đồ chung về nhà dùng","Nhắc nhở bạn khi bạn làm hỏng đồ chung"],answers:[0,1,3],explain:"Tiết kiệm, giữ gìn và nhắc nhở là bảo vệ của công."},{id:"dd4-giu-gin-cua-cong-29",type:"tf",q:"Chỉ cần không phá hoại là đủ, không cần quan tâm khi thấy người khác làm hỏng của công.",answer:!1,explain:"Sai. Em còn cần nhắc nhở hoặc báo người lớn khi thấy của công bị phá."},{id:"dd4-giu-gin-cua-cong-30",type:"mc",q:"Tại sao nói bảo vệ của công là bảo vệ quyền lợi của chính mình?",options:["Vì em cũng là người được sử dụng của công","Vì của công là đồ riêng của em","Vì em sẽ được thưởng rất nhiều tiền"],answer:0,explain:"Của công tốt thì em và mọi người đều được dùng."},{id:"dd4-giu-gin-cua-cong-19",type:"mc",q:"Đi xe buýt, Tùng thấy bạn nhỏ dùng bút vẽ lên ghế. Tùng có thể làm gì?",options:["Lấy bút vẽ cùng bạn cho vui","Nhẹ nhàng nhắc bạn dừng lại","Quát mắng bạn thật to"],answer:1,explain:"Nhắc nhẹ nhàng giúp bạn hiểu và bảo vệ ghế xe chung."},{id:"dd4-giu-gin-cua-cong-22",type:"mc",q:"Ngọc mượn bóng của trường để chơi giờ ra chơi. Hết giờ, Ngọc nên làm gì?",options:["Mang bóng về nhà","Để bóng ngoài sân","Cất bóng về đúng chỗ"],answer:2,explain:"Cất đồ chung đúng chỗ để lần sau các bạn khác dùng tiếp."},{id:"dd4-giu-gin-cua-cong-23",type:"mc",q:"Một nhóm bạn hái trộm xoài ở vườn trường. Minh nên làm gì?",options:["Không tham gia và nhắc các bạn","Hái cùng vì xoài của trường mà","Đứng canh cho các bạn hái"],answer:0,explain:"Minh không tham gia và giúp các bạn hiểu đó là việc sai."}]},summary:["Em giữ gìn của công ở trường và nơi công cộng.","Thấy của công bị phá thì nhắc nhở hoặc báo người lớn.","Giữ của chung như giữ của nhà mình."]}]},{id:"quan-he-ban-be",title:"Thiết lập và duy trì quan hệ bạn bè",lessons:[{id:"dd4-ket-ban",title:"Bài 11: Kết bạn và giữ gìn tình bạn",weeks:[21,22],learn:[{title:"Vì sao cần có bạn?",text:"Bạn bè cùng học, cùng chơi, chia sẻ vui buồn và giúp nhau tiến bộ.",example:"👫 cùng học · ⚽ cùng chơi"},{title:"Cách làm quen",text:"Chủ động chào hỏi, giới thiệu về mình, hỏi về sở thích của bạn, rủ bạn cùng chơi.",example:"👋 “Chào bạn, mình là An.”"},{title:"Giữ gìn tình bạn",text:"Quan tâm, tôn trọng, trung thực, giữ lời hứa, chia sẻ và giúp đỡ nhau.",example:"💛 tôn trọng · 🤞 giữ lời hứa"}],practice:[{questions:[{id:"dd4-ket-ban-01",type:"tf",q:"Chủ động chào hỏi là cách tốt để làm quen với bạn mới.",answer:!0,explain:"Đúng. Lời chào thân thiện mở đầu cho một tình bạn."},{id:"dd4-ket-ban-02",type:"multi",q:"Những việc làm nào giúp giữ gìn tình bạn?",options:["Giữ lời hứa với bạn","Hỏi thăm khi bạn ốm","Nói xấu bạn sau lưng","Chia sẻ đồ dùng khi bạn cần"],answers:[0,1,3],explain:"Giữ lời hứa, quan tâm và chia sẻ làm tình bạn thêm bền chặt."},{id:"dd4-ket-ban-03",type:"mc",q:"Câu làm quen nào thân thiện?",options:["Chào bạn, mình là Minh, bạn thích gì?","Bạn là ai mà ngồi chỗ này thế?","Tránh ra cho mình ngồi đi, nhanh lên!"],answer:0,explain:"Lời chào kèm câu hỏi về sở thích giúp hai bạn dễ làm quen."},{id:"dd4-ket-ban-04",type:"tf",q:"Bạn tốt là bạn luôn cho mình chép bài.",answer:!1,explain:"Sai. Bạn tốt giúp nhau hiểu bài và tiến bộ, không cho chép bài."},{id:"dd4-ket-ban-05",type:"mc",q:"Điều gì giúp tình bạn bền lâu?",options:["Chỉ chơi khi bạn có đồ chơi mới","Tôn trọng và trung thực với nhau","Luôn bắt bạn nghe theo mình"],answer:1,explain:"Tôn trọng và trung thực là nền tảng của tình bạn."},{id:"dd4-ket-ban-06",type:"mc",q:"Bạn bè mang lại điều gì cho em?",options:["Chỉ là người để mình sai bảo","Làm em học kém đi","Niềm vui, sự chia sẻ và giúp đỡ"],answer:2,explain:"Bạn tốt giúp em vui hơn và tiến bộ hơn."},{id:"dd4-ket-ban-07",type:"tf",q:"Biết lắng nghe bạn nói cũng là cách quan tâm đến bạn.",answer:!0,explain:"Đúng. Lắng nghe giúp bạn cảm thấy được tôn trọng."},{id:"dd4-ket-ban-08",type:"tf",q:"Chỉ nên kết bạn với những bạn học giỏi.",answer:!1,explain:"Sai. Mỗi bạn có điểm đáng quý riêng; em có thể kết bạn với nhiều bạn."},{id:"dd4-ket-ban-09",type:"mc",q:"Câu tục ngữ nào nói về tình bạn tốt?",options:["Học thầy không tày học bạn","Mất lòng trước được lòng sau","Ăn chắc mặc bền"],answer:0,explain:"Câu tục ngữ cho thấy bạn bè giúp nhau học hỏi rất nhiều."}]},{questions:[{id:"dd4-ket-ban-10",type:"match",q:"Nối việc làm với phẩm chất của người bạn tốt.",pairs:[["Giữ lời hứa","Đáng tin cậy"],["Hỏi thăm khi bạn ốm","Quan tâm"],["Nói thật với bạn","Trung thực"],["Không chê bai bạn","Tôn trọng"]],explain:"Người bạn tốt có nhiều phẩm chất đáng quý."},{id:"dd4-ket-ban-11",type:"mc",q:"Bạn mới chuyển đến lớp còn rụt rè. Cách làm nào giúp bạn hòa nhập?",options:["Để bạn ngồi một mình cho quen","Rủ bạn cùng chơi với cả nhóm","Hỏi bạn những câu khó để thử"],answer:1,explain:"Sự thân thiện giúp bạn mới thấy được chào đón."},{id:"dd4-ket-ban-12",type:"tf",q:"Bạn bè tốt là người dám góp ý khi bạn làm sai.",answer:!0,explain:"Đúng. Góp ý chân thành giúp bạn sửa sai, tiến bộ."},{id:"dd4-ket-ban-13",type:"multi",q:"Những hành vi nào làm tổn hại tình bạn?",options:["Thất hứa nhiều lần","Kể bí mật của bạn cho người khác","Chúc mừng khi bạn đạt điểm cao","Chế giễu ngoại hình của bạn"],answers:[0,1,3],explain:"Thất hứa, tiết lộ bí mật và chế giễu làm bạn buồn, mất lòng tin."},{id:"dd4-ket-ban-14",type:"tf",q:"Bạn thân thì không cần nói lời cảm ơn hay xin lỗi.",answer:!1,explain:"Sai. Cảm ơn và xin lỗi giúp tình bạn thêm tôn trọng, gắn bó."},{id:"dd4-ket-ban-15",type:"mc",q:"Khi bạn đạt giải, em nên làm gì?",options:["Ghen tị, không nói chuyện","Nói bạn gặp may","Chúc mừng bạn"],answer:2,explain:"Vui với niềm vui của bạn là biểu hiện của tình bạn đẹp."},{id:"dd4-ket-ban-16",type:"mc",q:"Bạn tâm sự với em một chuyện buồn và nhờ giữ kín. Em nên làm gì?",options:["Giữ kín và an ủi bạn","Kể cho cả lớp cùng nghe","Cười bạn vì chuyện đó"],answer:0,explain:"Giữ kín chuyện bạn tin tưởng là giữ lòng tin. Nếu chuyện đó có thể làm bạn gặp nguy hiểm, em hãy khuyên bạn nói với người lớn tin cậy."},{id:"dd4-ket-ban-17",type:"tf",q:"Rủ bạn cùng tham gia hoạt động của lớp là cách gắn kết tình bạn.",answer:!0,explain:"Đúng. Cùng làm việc chung giúp các bạn hiểu và gần nhau hơn."},{id:"dd4-ket-ban-18",type:"mc",q:"Bạn nào là người bạn đáng tin?",options:["Bạn Tùng hay hứa rồi quên","Bạn Khoa nói được làm được","Bạn Vy hay kể chuyện của người khác"],answer:1,explain:"Nói được làm được là người bạn đáng tin cậy."}]},{questions:[{id:"dd4-ket-ban-19",type:"mc",q:"An mới chuyển trường, chưa quen ai. An nên làm gì?",options:["Ngồi một mình mãi cho đến khi quen","Chờ các bạn đến làm quen trước","Chủ động chào hỏi, chơi cùng các bạn"],answer:2,explain:"Chủ động làm quen giúp An nhanh có bạn mới."},{id:"dd4-ket-ban-20",type:"tf",q:"Hà hứa đến dự sinh nhật bạn nhưng không đến và cũng không báo. Hà cư xử đúng.",answer:!1,explain:"Sai. Nếu không đến được, Hà cần báo và xin lỗi bạn."},{id:"dd4-ket-ban-21",type:"multi",q:"Bạn Lan đang buồn vì bị điểm kém. Em có thể làm gì?",options:["Hỏi han, động viên Lan","Rủ Lan cùng ôn bài","Nói với cả lớp Lan bị điểm kém","Kể cho Lan nghe chuyện vui"],answers:[0,1,3],explain:"Động viên và giúp đỡ là cách làm bạn vui lên."},{id:"dd4-ket-ban-22",type:"mc",q:"Khoa rủ Nam trốn học đi chơi. Nam nên làm gì?",options:["Từ chối và khuyên Khoa không nên trốn học","Đi theo Khoa một lúc cho vui","Đi chơi rồi về nói dối bố mẹ"],answer:0,explain:"Bạn tốt giúp nhau làm điều đúng, không cùng làm điều sai."},{id:"dd4-ket-ban-23",type:"mc",q:"Thảo rất thân với Vy, nhưng Vy lại chơi thêm với Ngọc. Thảo nên nghĩ thế nào?",options:["Giận Vy và không nói chuyện nữa","Vui vì mình có thể cùng chơi với cả Ngọc","Bắt Vy chọn chơi với một người"],answer:1,explain:"Tình bạn rộng mở giúp ai cũng có thêm niềm vui."},{id:"dd4-ket-ban-24",type:"tf",q:"Dũng viết thiệp chúc mừng sinh nhật người bạn ở xa và gọi điện hỏi thăm. Dũng biết giữ gìn tình bạn.",answer:!0,explain:"Đúng. Quan tâm thường xuyên giúp tình bạn bền lâu dù ở xa."},{id:"dd4-ket-ban-25",type:"mc",q:"Minh và bạn có sở thích khác nhau. Điều đó có sao không?",options:["Không thể làm bạn với nhau được","Phải bắt bạn thích giống hệt mình","Vẫn là bạn tốt, còn học thêm điều mới"],answer:2,explain:"Khác sở thích không ngăn tình bạn, còn giúp hai bạn hiểu thêm nhiều điều."},{id:"dd4-ket-ban-26",type:"order",q:"Sắp xếp các bước làm quen với một bạn mới.",items:["Mỉm cười, chào bạn","Giới thiệu tên của mình","Hỏi về sở thích của bạn","Rủ bạn cùng chơi"],explain:"Làm quen theo từng bước giúp em tự tin hơn."},{id:"dd4-ket-ban-27",type:"mc",q:"Phúc thấy bạn thân quay cóp trong giờ kiểm tra. Phúc nên làm gì?",options:["Sau giờ, khuyên bạn trung thực hơn","Che cho bạn để cô không thấy","Quay cóp theo bạn cho nhanh"],answer:0,explain:"Giúp bạn sửa sai mới là người bạn thật lòng."}]}],challenge:{questions:[{id:"dd4-ket-ban-28",type:"multi",q:"Những điều nào giúp em có nhiều bạn tốt?",options:["Thân thiện, cởi mở","Biết lắng nghe","Hay khoe khoang","Biết giúp đỡ bạn"],answers:[0,1,3],explain:"Thân thiện, lắng nghe và giúp đỡ giúp em được nhiều bạn quý mến."},{id:"dd4-ket-ban-29",type:"tf",q:"Bạn thân thì phải bênh nhau trong mọi việc, kể cả việc sai.",answer:!1,explain:"Sai. Bạn thân cần giúp nhau nhận ra và sửa điều sai."},{id:"dd4-ket-ban-30",type:"mc",q:"Câu nào nói về người bạn chỉ chơi khi có lợi?",options:["Bạn bè có nhau lúc khó khăn","Lúc vui thì đến, lúc khó thì xa","Một người bạn đáng tin"],answer:1,explain:"Bạn tốt luôn ở bên nhau cả khi vui lẫn khi khó khăn."},{id:"dd4-ket-ban-21",type:"multi",q:"Bạn Lan đang buồn vì bị điểm kém. Em có thể làm gì?",options:["Hỏi han, động viên Lan","Rủ Lan cùng ôn bài","Nói với cả lớp Lan bị điểm kém","Kể cho Lan nghe chuyện vui"],answers:[0,1,3],explain:"Động viên và giúp đỡ là cách làm bạn vui lên."},{id:"dd4-ket-ban-22",type:"mc",q:"Khoa rủ Nam trốn học đi chơi. Nam nên làm gì?",options:["Từ chối và khuyên Khoa không nên trốn học","Đi theo Khoa một lúc cho vui","Đi chơi rồi về nói dối bố mẹ"],answer:0,explain:"Bạn tốt giúp nhau làm điều đúng, không cùng làm điều sai."},{id:"dd4-ket-ban-27",type:"mc",q:"Phúc thấy bạn thân quay cóp trong giờ kiểm tra. Phúc nên làm gì?",options:["Sau giờ, khuyên bạn trung thực hơn","Che cho bạn để cô không thấy","Quay cóp theo bạn cho nhanh"],answer:0,explain:"Giúp bạn sửa sai mới là người bạn thật lòng."}]},summary:["Bạn bè giúp em vui vẻ và cùng nhau tiến bộ.","Em chủ động, thân thiện khi làm quen với bạn mới.","Tình bạn bền lâu nhờ quan tâm, tôn trọng và trung thực."]},{id:"dd4-giai-quyet-bat-hoa",title:"Bài 12: Khi giận nhau với bạn",weeks:[23,25],learn:[{title:"Bất hòa là chuyện thường",text:"Bạn bè có thể giận nhau vì hiểu lầm, khác ý kiến hay lỡ lời. Điều quan trọng là cách làm lành.",example:"😤 → 😊"},{title:"Các bước làm lành",text:"Bình tĩnh lại, rồi nói chuyện và lắng nghe nhau, cùng tìm cách giải quyết, cuối cùng là xin lỗi hoặc tha thứ.",example:"🧘 bình tĩnh · 👂 lắng nghe"},{title:"Điều không nên làm",text:"Đánh nhau, nói xấu, lôi kéo bạn khác tẩy chay, nói lời xúc phạm. Nếu không tự giải quyết được, hãy nhờ thầy cô giúp.",example:"🚫 đánh nhau · 🚫 tẩy chay"}],practice:[{questions:[{id:"dd4-giai-quyet-bat-hoa-01",type:"tf",q:"Khi giận bạn, việc đầu tiên nên làm là bình tĩnh lại.",answer:!0,explain:"Đúng. Bình tĩnh giúp em suy nghĩ rõ ràng và nói năng nhẹ nhàng."},{id:"dd4-giai-quyet-bat-hoa-02",type:"tf",q:"Đánh nhau là cách nhanh nhất để giải quyết bất hòa.",answer:!1,explain:"Sai. Đánh nhau gây đau và làm tình bạn tệ hơn."},{id:"dd4-giai-quyet-bat-hoa-03",type:"mc",q:"Khi mình làm bạn buồn, em nên nói gì?",options:["Mình xin lỗi, mình không cố ý","Tại bạn cả, không phải tại mình","Kệ bạn, mình chẳng sao"],answer:0,explain:"Lời xin lỗi chân thành giúp hai bạn làm lành."},{id:"dd4-giai-quyet-bat-hoa-04",type:"mc",q:"Khi bạn đã xin lỗi chân thành, em nên làm gì?",options:["Giận thêm vài hôm","Tha thứ và vui vẻ trở lại","Bắt bạn xin lỗi trước cả lớp"],answer:1,explain:"Tha thứ giúp tình bạn trở lại tốt đẹp."},{id:"dd4-giai-quyet-bat-hoa-05",type:"multi",q:"Những cách nào giúp em bình tĩnh khi giận?",options:["Hít thở sâu vài lần","Đếm chậm từ 1 đến 10","Hét thật to vào mặt bạn","Đi uống nước rồi quay lại nói chuyện"],answers:[0,1,3],explain:"Những cách nhẹ nhàng giúp em dịu cơn giận."},{id:"dd4-giai-quyet-bat-hoa-06",type:"mc",q:"Nguyên nhân nào thường gây bất hòa giữa bạn bè?",options:["Cùng làm bài tập","Cùng đi học","Hiểu lầm nhau"],answer:2,explain:"Hiểu lầm là lí do hay gặp; nói chuyện thẳng thắn sẽ giúp gỡ rối."},{id:"dd4-giai-quyet-bat-hoa-07",type:"tf",q:"Nếu không tự làm lành được, em có thể nhờ thầy cô giúp.",answer:!0,explain:"Đúng. Thầy cô sẽ giúp hai bạn hiểu nhau hơn."},{id:"dd4-giai-quyet-bat-hoa-08",type:"tf",q:"Lôi kéo cả lớp không chơi với bạn mình đang giận là cách làm đúng.",answer:!1,explain:"Sai. Tẩy chay làm bạn tổn thương và chia rẽ cả lớp."},{id:"dd4-giai-quyet-bat-hoa-09",type:"mc",q:"Câu nói nào giúp làm lành?",options:["Mình buồn chuyện hôm qua, nói chuyện nhé","Mình không bao giờ chơi với bạn nữa","Bạn thật đáng ghét, tránh xa mình ra"],answer:0,explain:"Nói rõ cảm xúc một cách nhẹ nhàng mở lối để làm lành."}]},{questions:[{id:"dd4-giai-quyet-bat-hoa-10",type:"order",q:"Sắp xếp các bước làm lành với bạn.",items:["Bình tĩnh lại","Nói chuyện và lắng nghe nhau","Cùng tìm cách giải quyết","Xin lỗi hoặc tha thứ, vui vẻ trở lại"],explain:"Làm theo các bước giúp hai bạn hiểu nhau và làm lành."},{id:"dd4-giai-quyet-bat-hoa-11",type:"match",q:"Nối cách cư xử với kết quả của nó.",pairs:[["Lắng nghe bạn","Hiểu được ý bạn"],["Nói lời xúc phạm","Bạn thêm buồn giận"],["Xin lỗi chân thành","Dễ làm lành"],["Nói xấu sau lưng","Mất lòng tin"]],explain:"Cách cư xử của em quyết định tình bạn tốt lên hay xấu đi."},{id:"dd4-giai-quyet-bat-hoa-12",type:"tf",q:"Lắng nghe bạn giải thích có thể giúp em nhận ra mình đã hiểu lầm.",answer:!0,explain:"Đúng. Lắng nghe giúp xóa bỏ hiểu lầm."},{id:"dd4-giai-quyet-bat-hoa-13",type:"mc",q:"Vì sao nên nói “Mình buồn khi…” thay vì “Bạn thật tệ”?",options:["Vì câu đó dài hơn nên lịch sự hơn","Vì bạn hiểu mà không bị xúc phạm","Vì nói vậy để bạn phải sợ mình"],answer:1,explain:"Nói về cảm xúc giúp cuộc trò chuyện nhẹ nhàng hơn."},{id:"dd4-giai-quyet-bat-hoa-14",type:"tf",q:"Người xin lỗi trước là người thua cuộc.",answer:!1,explain:"Sai. Dám xin lỗi là người dũng cảm và biết quý tình bạn."},{id:"dd4-giai-quyet-bat-hoa-15",type:"multi",q:"Những việc nên làm khi hai bạn khác ý kiến trong nhóm?",options:["Nghe ý kiến của từng bạn","Cùng bàn chọn cách tốt nhất","Ai nói to hơn thì thắng","Nhờ cô góp ý nếu cần"],answers:[0,1,3],explain:"Lắng nghe và bàn bạc giúp nhóm hợp tác tốt."},{id:"dd4-giai-quyet-bat-hoa-16",type:"mc",q:"Câu nào phù hợp khi tha thứ cho bạn?",options:["Lần này thôi đấy, lần sau mình mách cô","Bạn phải đưa mình kẹo mới hết giận","Không sao đâu, mình vẫn là bạn nhé"],answer:2,explain:"Lời tha thứ chân thành giúp bạn nhẹ lòng."},{id:"dd4-giai-quyet-bat-hoa-17",type:"mc",q:"Vì sao không nên giận bạn quá lâu?",options:["Vì giận lâu làm tình bạn xa cách","Vì giận lâu sẽ quên mất bạn","Vì giận lâu thì được nhiều quà"],answer:0,explain:"Làm lành sớm giúp hai bạn vui vẻ trở lại."},{id:"dd4-giai-quyet-bat-hoa-18",type:"tf",q:"Mỗi bạn có thể nhìn một sự việc theo cách khác nhau.",answer:!0,explain:"Đúng. Hiểu điều này giúp em dễ thông cảm với bạn."}]},{questions:[{id:"dd4-giai-quyet-bat-hoa-19",type:"mc",q:"Nam vô tình làm đổ nước vào vở của Bình. Bình tức giận. Nam nên làm gì?",options:["Bỏ đi chỗ khác cho nhanh","Xin lỗi và giúp Bình lau khô vở","Bảo Bình tự lo lấy vở của mình"],answer:1,explain:"Xin lỗi và sửa chữa cho thấy Nam có trách nhiệm."},{id:"dd4-giai-quyet-bat-hoa-20",type:"mc",q:"Lan nghe bạn kể rằng Hà nói xấu mình. Lan nên làm gì trước?",options:["Nói xấu lại Hà với các bạn khác","Không bao giờ nhìn mặt Hà nữa","Bình tĩnh, hỏi thẳng Hà một cách nhẹ nhàng"],answer:2,explain:"Hỏi lại trực tiếp giúp tránh hiểu lầm do nghe kể."},{id:"dd4-giai-quyet-bat-hoa-21",type:"tf",q:"Khoa và Tùng tranh nhau quả bóng, cả hai cùng thống nhất mỗi người chơi một lượt. Đó là cách giải quyết tốt.",answer:!0,explain:"Đúng. Thay phiên nhau là cách công bằng, vui vẻ."},{id:"dd4-giai-quyet-bat-hoa-22",type:"multi",q:"Chi và Vy giận nhau đã ba ngày. Ngọc là bạn của cả hai có thể làm gì?",options:["Khuyên mỗi bạn bình tĩnh nói chuyện","Tạo dịp để hai bạn cùng chơi","Kể lời của bạn này cho bạn kia nghe thêm","Nhờ cô giáo giúp nếu cần"],answers:[0,1,3],explain:"Ngọc làm cầu nối nhẹ nhàng, không làm hai bạn giận thêm."},{id:"dd4-giai-quyet-bat-hoa-23",type:"mc",q:"Minh bị bạn trêu đùa quá trớn. Minh nên làm gì?",options:["Nói rõ là mình không thích, cần thì báo cô","Đánh bạn một trận để bạn chừa","Khóc thật to và xin nghỉ học"],answer:0,explain:"Nói rõ cảm xúc và nhờ thầy cô là cách an toàn."},{id:"dd4-giai-quyet-bat-hoa-24",type:"tf",q:"Thảo đăng lên nhóm chat của lớp chuyện xấu của bạn mà Thảo đang giận. Thảo làm đúng.",answer:!1,explain:"Sai. Đăng chuyện xấu của bạn lên mạng làm bạn tổn thương và khó làm lành."},{id:"dd4-giai-quyet-bat-hoa-25",type:"mc",q:"Phúc đã xin lỗi nhưng Dũng vẫn còn giận. Phúc nên làm gì?",options:["Giận lại Dũng cho công bằng","Kiên nhẫn chờ, vẫn đối xử tốt với Dũng","Bắt Dũng phải tha thứ ngay"],answer:1,explain:"Cho bạn thời gian và vẫn tử tế giúp bạn sớm nguôi giận."},{id:"dd4-giai-quyet-bat-hoa-26",type:"order",q:"Sắp xếp cách giải quyết khi nhóm em cãi nhau vì chọn đề tài vẽ.",items:["Tạm dừng, cả nhóm bình tĩnh","Mỗi bạn nêu ý kiến","Cùng bàn chọn đề tài hợp lí","Phân công nhau cùng vẽ"],explain:"Nhóm biết bàn bạc thì làm việc vui vẻ và hiệu quả."},{id:"dd4-giai-quyet-bat-hoa-27",type:"mc",q:"Hà lỡ lời nói Vy “chậm như rùa”. Vy buồn. Hà nên làm gì?",options:["Coi như không có chuyện gì","Nói thêm vài câu cho vui","Xin lỗi Vy và hứa sẽ cẩn thận lời nói"],answer:2,explain:"Lời nói có thể làm bạn đau lòng; biết xin lỗi là cư xử đẹp."}]}],challenge:{questions:[{id:"dd4-giai-quyet-bat-hoa-28",type:"multi",q:"Những cách nào là giải quyết bất hòa tích cực?",options:["Bình tĩnh, lắng nghe","Nói rõ cảm xúc","Tẩy chay bạn","Xin lỗi và tha thứ"],answers:[0,1,3],explain:"Cách giải quyết tích cực giúp tình bạn bền chặt hơn."},{id:"dd4-giai-quyet-bat-hoa-29",type:"mc",q:"Câu “Một điều nhịn, chín điều lành” khuyên em điều gì?",options:["Biết nhường nhịn thì mọi chuyện êm đẹp","Lúc nào cũng phải chịu thiệt về mình","Không bao giờ được nói ý kiến"],answer:0,explain:"Nhường nhịn đúng lúc giúp tránh cãi vã và giữ hòa khí."},{id:"dd4-giai-quyet-bat-hoa-30",type:"tf",q:"Nếu bạn sai trước thì mình được trả đũa.",answer:!1,explain:"Sai. Trả đũa làm mâu thuẫn lớn thêm; hãy bình tĩnh nói chuyện."},{id:"dd4-giai-quyet-bat-hoa-19",type:"mc",q:"Nam vô tình làm đổ nước vào vở của Bình. Bình tức giận. Nam nên làm gì?",options:["Bỏ đi chỗ khác cho nhanh","Xin lỗi và giúp Bình lau khô vở","Bảo Bình tự lo lấy vở của mình"],answer:1,explain:"Xin lỗi và sửa chữa cho thấy Nam có trách nhiệm."},{id:"dd4-giai-quyet-bat-hoa-22",type:"multi",q:"Chi và Vy giận nhau đã ba ngày. Ngọc là bạn của cả hai có thể làm gì?",options:["Khuyên mỗi bạn bình tĩnh nói chuyện","Tạo dịp để hai bạn cùng chơi","Kể lời của bạn này cho bạn kia nghe thêm","Nhờ cô giáo giúp nếu cần"],answers:[0,1,3],explain:"Ngọc làm cầu nối nhẹ nhàng, không làm hai bạn giận thêm."},{id:"dd4-giai-quyet-bat-hoa-25",type:"mc",q:"Phúc đã xin lỗi nhưng Dũng vẫn còn giận. Phúc nên làm gì?",options:["Giận lại Dũng cho công bằng","Kiên nhẫn chờ, vẫn đối xử tốt với Dũng","Bắt Dũng phải tha thứ ngay"],answer:1,explain:"Cho bạn thời gian và vẫn tử tế giúp bạn sớm nguôi giận."}]},summary:["Bạn bè có lúc bất đồng; quan trọng là bình tĩnh, lắng nghe để làm lành.","Biết xin lỗi khi sai và tha thứ khi bạn đã nhận lỗi.","Không giải quyết bằng đánh nhau, nói xấu hay tẩy chay."]}]},{id:"quyen-bon-phan-tre-em",title:"Quyền và bổn phận của trẻ em",lessons:[{id:"dd4-quyen-tre-em",title:"Bài 13: Quyền của trẻ em",weeks:[26,27],learn:[{title:"Trẻ em có quyền",text:"Theo Luật Trẻ em của Việt Nam, trẻ em là người dưới 16 tuổi. Trẻ em có những quyền được pháp luật bảo vệ.",example:"👧 👦 dưới 16 tuổi"},{title:"Một số quyền cơ bản",text:"Quyền được sống, được chăm sóc sức khỏe, được học tập, được vui chơi, được bảo vệ, được bày tỏ ý kiến, được tôn trọng đời sống riêng tư.",example:"🏥 sức khỏe · 🏫 học tập · 🎈 vui chơi"},{title:"Ai bảo đảm quyền trẻ em?",text:"Gia đình, nhà trường, Nhà nước và xã hội đều có trách nhiệm chăm lo, bảo vệ trẻ em. Khi cần giúp, trẻ em có thể gọi Tổng đài 111.",example:"📞 111 – miễn phí"}],practice:[{questions:[{id:"dd4-quyen-tre-em-01",type:"multi",q:"Những điều nào là quyền của trẻ em?",options:["Được đi học","Được vui chơi, giải trí","Được chăm sóc sức khỏe","Được làm mọi điều mình thích"],answers:[0,1,2],explain:"Học tập, vui chơi, chăm sóc sức khỏe là quyền của trẻ em; còn làm mọi điều mình thích thì không phải là quyền."},{id:"dd4-quyen-tre-em-02",type:"tf",q:"Theo Luật Trẻ em của Việt Nam, trẻ em là người dưới 16 tuổi.",answer:!0,explain:"Đúng. Người dưới 16 tuổi được gọi là trẻ em."},{id:"dd4-quyen-tre-em-03",type:"mc",q:"Tổng đài điện thoại quốc gia bảo vệ trẻ em là số nào?",options:["111","113","115"],answer:0,emoji:"📞",explain:"Số 111 là tổng đài bảo vệ trẻ em, gọi miễn phí."},{id:"dd4-quyen-tre-em-04",type:"tf",q:"Trẻ em gái thì không cần được đi học như trẻ em trai.",answer:!1,explain:"Sai. Mọi trẻ em, trai hay gái, đều có quyền học tập như nhau."},{id:"dd4-quyen-tre-em-05",type:"mc",q:"Được tiêm phòng, khám bệnh khi ốm là quyền gì?",options:["Quyền được vui chơi","Quyền được chăm sóc sức khỏe","Quyền được bày tỏ ý kiến"],answer:1,explain:"Chăm sóc sức khỏe giúp trẻ em lớn lên khỏe mạnh."},{id:"dd4-quyen-tre-em-06",type:"mc",q:"Được nói lên suy nghĩ của mình về việc liên quan đến bản thân là quyền gì?",options:["Quyền được học tập","Quyền được chăm sóc sức khỏe","Quyền được bày tỏ ý kiến"],answer:2,explain:"Trẻ em được bày tỏ ý kiến và người lớn lắng nghe."},{id:"dd4-quyen-tre-em-07",type:"tf",q:"Gia đình, nhà trường và xã hội đều có trách nhiệm bảo vệ trẻ em.",answer:!0,explain:"Đúng. Mọi người cùng chung tay chăm lo cho trẻ em."},{id:"dd4-quyen-tre-em-08",type:"tf",q:"Chỉ trẻ em thành phố mới có quyền được vui chơi.",answer:!1,explain:"Sai. Trẻ em ở đâu cũng có quyền như nhau."},{id:"dd4-quyen-tre-em-09",type:"mc",q:"Ngày nào là Ngày Quốc tế Thiếu nhi?",options:["Ngày 1 tháng 6","Ngày 20 tháng 11","Ngày 8 tháng 3"],answer:0,explain:"Ngày 1 tháng 6 hằng năm là Ngày Quốc tế Thiếu nhi."}]},{questions:[{id:"dd4-quyen-tre-em-10",type:"match",q:"Nối việc làm với quyền của trẻ em.",pairs:[["Đến trường học","Quyền được học tập"],["Được khám bệnh","Quyền được chăm sóc sức khỏe"],["Chơi ở sân chơi","Quyền được vui chơi"],["Góp ý trong họp lớp","Quyền được bày tỏ ý kiến"]],explain:"Mỗi hoạt động hằng ngày gắn với một quyền của trẻ em."},{id:"dd4-quyen-tre-em-11",type:"mc",q:"Việc làm nào xâm phạm quyền trẻ em?",options:["Bố mẹ đưa con đi học","Bắt trẻ em bỏ học để đi làm việc nặng","Cô giáo lắng nghe ý kiến học sinh"],answer:1,explain:"Bắt trẻ bỏ học làm việc nặng là xâm phạm quyền học tập, vui chơi và quyền được bảo vệ."},{id:"dd4-quyen-tre-em-12",type:"tf",q:"Tự ý đọc tin nhắn, nhật kí của trẻ em là chưa tôn trọng quyền riêng tư.",answer:!0,explain:"Đúng. Trẻ em có quyền được tôn trọng đời sống riêng tư; khi có lo lắng về an toàn, người lớn sẽ cùng trò chuyện với em."},{id:"dd4-quyen-tre-em-13",type:"multi",q:"Những nơi nào em có thể tìm sự giúp đỡ khi bị bắt nạt?",options:["Bố mẹ, người thân","Thầy cô giáo","Tổng đài 111","Người lạ trên mạng"],answers:[0,1,2],explain:"Người thân, thầy cô và Tổng đài 111 là nơi em tin cậy."},{id:"dd4-quyen-tre-em-14",type:"tf",q:"Trẻ em có quyền được bày tỏ ý kiến nên người lớn phải làm theo mọi ý kiến của trẻ.",answer:!1,explain:"Sai. Người lớn lắng nghe và cân nhắc; không phải ý kiến nào cũng được làm theo."},{id:"dd4-quyen-tre-em-15",type:"mc",q:"Vì sao trẻ em cần được bảo vệ đặc biệt?",options:["Vì trẻ em rất hay nghịch ngợm","Vì trẻ em chưa biết nói chuyện","Vì trẻ em chưa tự bảo vệ mình đầy đủ"],answer:2,explain:"Trẻ em đang lớn nên cần người lớn bảo vệ, chăm sóc."},{id:"dd4-quyen-tre-em-16",type:"mc",q:"Câu nào thể hiện quyền được vui chơi?",options:["Sau giờ học, em được chơi đá cầu cùng bạn","Em phải học suốt ngày, không nghỉ","Em phải làm việc nặng cả buổi tối"],answer:0,explain:"Vui chơi, nghỉ ngơi hợp lí là quyền của trẻ em."},{id:"dd4-quyen-tre-em-17",type:"tf",q:"Trẻ em khuyết tật cũng có đầy đủ quyền như mọi trẻ em khác.",answer:!0,explain:"Đúng. Mọi trẻ em đều bình đẳng về quyền."},{id:"dd4-quyen-tre-em-18",type:"mc",q:"Khi thấy một bạn bị đánh đập thường xuyên, em nên làm gì?",options:["Giữ im lặng cho bạn","Kể với thầy cô hoặc gọi 111","Tự đến nhà bạn để đánh lại"],answer:1,explain:"Báo người lớn tin cậy giúp bạn được bảo vệ an toàn."}]},{questions:[{id:"dd4-quyen-tre-em-19",type:"mc",q:"Họp lớp bàn chuyện đi dã ngoại, Lan có ý kiến khác. Lan nên làm gì?",options:["Im lặng, không nói gì cả","Bỏ về vì thấy không vui","Giơ tay nói ý kiến của mình lễ phép"],answer:2,explain:"Lan dùng quyền bày tỏ ý kiến một cách lễ phép."},{id:"dd4-quyen-tre-em-20",type:"tf",q:"Bình bị ốm, bố mẹ đưa đi khám bác sĩ. Đó là Bình được hưởng quyền chăm sóc sức khỏe.",answer:!0,explain:"Đúng. Gia đình đang bảo đảm quyền của Bình."},{id:"dd4-quyen-tre-em-21",type:"multi",q:"Bạn Nam kể bị một anh lớn hay chặn đường đòi tiền. Nam nên làm gì?",options:["Kể ngay với bố mẹ","Báo thầy cô","Giữ bí mật vì sợ","Đi cùng bạn bè hoặc người lớn trên đường về"],answers:[0,1,3],explain:"Nói với người lớn tin cậy giúp Nam được bảo vệ."},{id:"dd4-quyen-tre-em-22",type:"mc",q:"Chi muốn tham gia câu lạc bộ vẽ nhưng bố mẹ muốn Chi học thêm môn khác. Chi nên làm gì?",options:["Lễ phép nói mong muốn với bố mẹ","Giận bố mẹ và bỏ ăn mấy bữa","Không nói gì và buồn mãi"],answer:0,explain:"Bày tỏ ý kiến lễ phép giúp bố mẹ hiểu Chi hơn."},{id:"dd4-quyen-tre-em-23",type:"tf",q:"Hà lớn rồi nên có thể nghỉ học để ở nhà trông em cả ngày. Điều đó là đúng.",answer:!1,explain:"Sai. Hà có quyền được đi học; trông em chỉ nên là việc giúp đỡ vừa sức."},{id:"dd4-quyen-tre-em-24",type:"mc",q:"Một người lạ nhắn tin rủ Khoa đi chơi và dặn đừng kể với ai. Khoa nên làm gì?",options:["Đi theo vì thấy vui","Không trả lời, kể ngay với bố mẹ","Giữ bí mật như đã hứa"],answer:1,explain:"Lời dặn “đừng kể với ai” là dấu hiệu nguy hiểm; Khoa cần báo người lớn."},{id:"dd4-quyen-tre-em-25",type:"mc",q:"Vy thấy bạn trong lớp không được ăn sáng, hay buồn. Vy nên làm gì?",options:["Trêu bạn cho bạn vui lên","Không để ý đến bạn ấy nữa","Quan tâm bạn và kể với cô giáo"],answer:2,explain:"Cô giáo có thể tìm hiểu và giúp bạn được chăm sóc tốt hơn."},{id:"dd4-quyen-tre-em-26",type:"order",q:"Sắp xếp các việc nên làm khi em hoặc bạn bị bắt nạt.",items:["Tránh xa nơi nguy hiểm","Kể với người lớn tin cậy","Người lớn cùng tìm cách giúp","Theo dõi để việc bắt nạt không lặp lại"],explain:"Kể với người lớn là bước quan trọng nhất để được bảo vệ."},{id:"dd4-quyen-tre-em-27",type:"mc",q:"Tùng nói: “Quyền trẻ em chỉ là chuyện của người lớn.” Em nghĩ sao?",options:["Chưa đúng, trẻ em cũng cần biết quyền mình","Đúng, trẻ em chỉ cần đi học thôi","Đúng, vì trẻ em chưa hiểu được gì"],answer:0,explain:"Biết quyền của mình giúp em tự tin và biết tìm sự giúp đỡ."}]}],challenge:{questions:[{id:"dd4-quyen-tre-em-28",type:"multi",q:"Những câu nào nói đúng về quyền trẻ em?",options:["Mọi trẻ em đều bình đẳng về quyền","Quyền trẻ em được pháp luật bảo vệ","Có quyền nghĩa là làm gì cũng được","Gia đình, nhà trường, xã hội cùng bảo đảm quyền trẻ em"],answers:[0,1,3],explain:"Quyền đi kèm sự bảo vệ của pháp luật và của mọi người."},{id:"dd4-quyen-tre-em-29",type:"tf",q:"Khi bị người khác đối xử tệ, trẻ em nên giấu kín để không phiền ai.",answer:!1,explain:"Sai. Em có quyền được bảo vệ; hãy kể với người lớn tin cậy hoặc gọi 111."},{id:"dd4-quyen-tre-em-30",type:"mc",q:"Gọi Tổng đài 111 thì phải trả bao nhiêu tiền?",options:["Rất nhiều tiền","Không mất tiền","Phải nạp thẻ trước"],answer:1,explain:"Tổng đài 111 miễn phí, trẻ em có thể gọi khi cần giúp đỡ."},{id:"dd4-quyen-tre-em-19",type:"mc",q:"Họp lớp bàn chuyện đi dã ngoại, Lan có ý kiến khác. Lan nên làm gì?",options:["Im lặng, không nói gì cả","Bỏ về vì thấy không vui","Giơ tay nói ý kiến của mình lễ phép"],answer:2,explain:"Lan dùng quyền bày tỏ ý kiến một cách lễ phép."},{id:"dd4-quyen-tre-em-21",type:"multi",q:"Bạn Nam kể bị một anh lớn hay chặn đường đòi tiền. Nam nên làm gì?",options:["Kể ngay với bố mẹ","Báo thầy cô","Giữ bí mật vì sợ","Đi cùng bạn bè hoặc người lớn trên đường về"],answers:[0,1,3],explain:"Nói với người lớn tin cậy giúp Nam được bảo vệ."},{id:"dd4-quyen-tre-em-25",type:"mc",q:"Vy thấy bạn trong lớp không được ăn sáng, hay buồn. Vy nên làm gì?",options:["Trêu bạn cho bạn vui lên","Không để ý đến bạn ấy nữa","Quan tâm bạn và kể với cô giáo"],answer:2,explain:"Cô giáo có thể tìm hiểu và giúp bạn được chăm sóc tốt hơn."}]},summary:["Trẻ em có những quyền được pháp luật bảo vệ.","Gia đình, nhà trường và xã hội có trách nhiệm bảo đảm quyền trẻ em.","Khi quyền của mình bị xâm phạm, em hãy nói với người lớn tin cậy hoặc gọi 111."]},{id:"dd4-bon-phan-tre-em",title:"Bài 14: Bổn phận của trẻ em",weeks:[28,29],learn:[{title:"Bổn phận là gì?",text:"Bổn phận là những việc trẻ em cần làm, phù hợp với lứa tuổi, đối với gia đình, nhà trường, cộng đồng, đất nước và bản thân.",example:"🏠 gia đình · 🏫 nhà trường · 🌏 cộng đồng"},{title:"Bổn phận với gia đình, nhà trường",text:"Kính trọng, lễ phép với ông bà, cha mẹ; làm việc nhà vừa sức; chăm học; kính trọng thầy cô, đoàn kết với bạn; giữ gìn trường lớp.",example:"🙇 lễ phép · 📚 chăm học"},{title:"Bổn phận với cộng đồng và bản thân",text:"Tôn trọng người khác, giữ gìn vệ sinh, bảo vệ môi trường, chấp hành luật giao thông; tự chăm sóc bản thân, sống trung thực.",example:"🚸 an toàn giao thông · 🌱 môi trường"}],practice:[{questions:[{id:"dd4-bon-phan-tre-em-01",type:"tf",q:"Trẻ em vừa có quyền, vừa có bổn phận.",answer:!0,explain:"Đúng. Quyền và bổn phận luôn đi cùng nhau."},{id:"dd4-bon-phan-tre-em-02",type:"multi",q:"Những việc nào là bổn phận của trẻ em với gia đình?",options:["Kính trọng, lễ phép với ông bà, cha mẹ","Làm việc nhà vừa sức","Đòi bố mẹ mua mọi thứ","Yêu thương anh chị em"],answers:[0,1,3],explain:"Lễ phép, làm việc nhà và yêu thương nhau là bổn phận với gia đình."},{id:"dd4-bon-phan-tre-em-03",type:"mc",q:"Bổn phận của học sinh với nhà trường là gì?",options:["Chăm học, lễ phép, đoàn kết","Đi học muộn cũng không sao","Chỉ chơi với bạn thân trong lớp"],answer:0,explain:"Chăm học, lễ phép và đoàn kết là bổn phận của học sinh."},{id:"dd4-bon-phan-tre-em-04",type:"tf",q:"Bổn phận chỉ dành cho người lớn.",answer:!1,explain:"Sai. Trẻ em cũng có bổn phận phù hợp với lứa tuổi."},{id:"dd4-bon-phan-tre-em-05",type:"mc",q:"Việc nào là bổn phận với cộng đồng?",options:["Vứt rác xuống lòng đường","Giữ gìn vệ sinh nơi công cộng","Làm ồn trong thư viện xã"],answer:1,explain:"Giữ vệ sinh nơi công cộng là trách nhiệm của mỗi người."},{id:"dd4-bon-phan-tre-em-06",type:"mc",q:"Việc nào là bổn phận với bản thân?",options:["Thức khuya chơi trò chơi điện tử","Bỏ bữa sáng để ngủ thêm","Giữ vệ sinh cá nhân, ăn ngủ điều độ"],answer:2,explain:"Tự chăm sóc bản thân là bổn phận của mỗi em."},{id:"dd4-bon-phan-tre-em-07",type:"tf",q:"Chấp hành luật giao thông khi đi đường là bổn phận của trẻ em.",answer:!0,explain:"Đúng. Đó vừa là bổn phận vừa giúp em an toàn."},{id:"dd4-bon-phan-tre-em-08",type:"tf",q:"Có quyền được vui chơi nên em được chơi cả ngày, không cần học.",answer:!1,explain:"Sai. Em cần cân bằng giữa vui chơi, học tập và giúp đỡ gia đình."},{id:"dd4-bon-phan-tre-em-09",type:"mc",q:"Kính trọng, lễ phép với thầy cô là bổn phận đối với ai?",options:["Nhà trường","Gia đình","Cộng đồng"],answer:0,explain:"Đó là bổn phận của học sinh đối với nhà trường."}]},{questions:[{id:"dd4-bon-phan-tre-em-10",type:"match",q:"Nối bổn phận với nơi em thực hiện.",pairs:[["Lễ phép với ông bà","Gia đình"],["Giữ trật tự trong lớp","Nhà trường"],["Không vứt rác ở công viên","Cộng đồng"],["Tập thể dục mỗi sáng","Bản thân"]],explain:"Bổn phận của em có ở mọi nơi em sống và học tập."},{id:"dd4-bon-phan-tre-em-11",type:"mc",q:"Vì sao quyền đi kèm bổn phận?",options:["Để trẻ em phải làm thật nhiều việc","Vì được chăm lo thì em cần có trách nhiệm","Vì người lớn muốn trẻ em vất vả"],answer:1,explain:"Được yêu thương, chăm lo thì em đáp lại bằng sự cố gắng."},{id:"dd4-bon-phan-tre-em-12",type:"tf",q:"Chăm chỉ học tập vừa là quyền vừa là bổn phận của trẻ em.",answer:!0,explain:"Đúng. Em được đi học và có bổn phận học tập chăm chỉ."},{id:"dd4-bon-phan-tre-em-13",type:"multi",q:"Bạn nào đang thực hiện tốt bổn phận của mình?",options:["Lan tự gấp chăn sau khi ngủ dậy","Nam đội mũ bảo hiểm khi ngồi xe máy","Khoa nói trống không với ông bà","Chi giúp bạn cùng lớp học bài"],answers:[0,1,3],explain:"Lan, Nam và Chi đều thực hiện tốt bổn phận."},{id:"dd4-bon-phan-tre-em-14",type:"tf",q:"Đội mũ bảo hiểm khi đi xe máy là việc không cần thiết với trẻ em.",answer:!1,explain:"Sai. Đội mũ bảo hiểm là quy định và giúp bảo vệ đầu khi có va chạm."},{id:"dd4-bon-phan-tre-em-15",type:"mc",q:"Thực hiện tốt bổn phận giúp em điều gì?",options:["Được làm mọi điều mình muốn","Không phải đi học nữa","Trở thành người có ích"],answer:2,explain:"Làm tốt bổn phận giúp em lớn lên tự tin và có ích."},{id:"dd4-bon-phan-tre-em-16",type:"mc",q:"Việc làm nào chưa thực hiện bổn phận với đất nước?",options:["Đùa nghịch trong giờ chào cờ","Hát Quốc ca nghiêm trang khi chào cờ","Giữ gìn di tích lịch sử"],answer:0,explain:"Nghiêm trang khi chào cờ là thể hiện lòng yêu nước."},{id:"dd4-bon-phan-tre-em-17",type:"tf",q:"Trung thực, giữ lời hứa là bổn phận đối với bản thân.",answer:!0,explain:"Đúng. Rèn đức tính tốt cho mình là bổn phận của em."},{id:"dd4-bon-phan-tre-em-18",type:"mc",q:"Câu nào nói đúng về quyền và bổn phận?",options:["Chỉ cần đòi đủ quyền lợi","Hưởng quyền và làm tròn bổn phận","Chỉ cần làm bổn phận thôi"],answer:1,explain:"Quyền và bổn phận luôn đi đôi với nhau."}]},{questions:[{id:"dd4-bon-phan-tre-em-19",type:"mc",q:"Minh muốn đi chơi nhưng đến giờ làm việc nhà được giao. Minh nên làm gì?",options:["Đi chơi ngay rồi về làm sau","Nhờ em làm hộ mà không hỏi","Làm xong việc nhà rồi mới đi chơi"],answer:2,explain:"Hoàn thành bổn phận trước, rồi vui chơi là hợp lí."},{id:"dd4-bon-phan-tre-em-20",type:"tf",q:"Thảo nhắc em nhỏ đội mũ bảo hiểm trước khi bố chở đi học. Thảo thực hiện bổn phận của mình.",answer:!0,explain:"Đúng. Giữ an toàn cho mình và người thân là việc làm tốt."},{id:"dd4-bon-phan-tre-em-21",type:"multi",q:"Phúc muốn thực hiện tốt bổn phận với nhà trường. Phúc có thể làm gì?",options:["Đi học đúng giờ","Giữ gìn bàn ghế, sách vở","Nói chuyện riêng trong giờ học","Tham gia hoạt động của lớp"],answers:[0,1,3],explain:"Đúng giờ, giữ gìn và tham gia tích cực là bổn phận của học sinh."},{id:"dd4-bon-phan-tre-em-22",type:"mc",q:"Hà đòi bố mẹ mua điện thoại đắt tiền vì “em có quyền vui chơi”. Em nghĩ sao?",options:["Chưa đúng, vui chơi không phải đòi hỏi","Đúng, bố mẹ phải mua cho Hà ngay","Đúng, trẻ em muốn gì cũng được"],answer:0,explain:"Quyền vui chơi không có nghĩa là đòi hỏi quá khả năng của gia đình."},{id:"dd4-bon-phan-tre-em-23",type:"tf",q:"Dũng thấy bạn xả rác ở công viên nhưng nghĩ đó không phải việc của mình. Dũng nghĩ đúng.",answer:!1,explain:"Sai. Giữ gìn môi trường chung là bổn phận của mọi người, Dũng có thể nhắc bạn."},{id:"dd4-bon-phan-tre-em-24",type:"mc",q:"Ông bà đến chơi, Ngọc nên làm gì?",options:["Chào qua loa rồi xem ti vi","Lễ phép chào hỏi ông bà","Đóng cửa phòng ngồi chơi"],answer:1,explain:"Kính trọng, lễ phép với ông bà là bổn phận với gia đình."},{id:"dd4-bon-phan-tre-em-25",type:"order",q:"Sắp xếp các việc buổi sáng thể hiện bổn phận với bản thân và gia đình.",items:["Thức dậy đúng giờ","Gấp chăn màn, vệ sinh cá nhân","Ăn sáng cùng gia đình","Chào bố mẹ rồi đi học"],explain:"Một buổi sáng nề nếp cho thấy em có trách nhiệm."},{id:"dd4-bon-phan-tre-em-26",type:"mc",q:"Lớp tổ chức nhặt rác ở khu di tích. Vy nên làm gì?",options:["Tìm lí do để không phải đi","Đi nhưng chỉ đứng một chỗ chơi","Hăng hái tham gia và giữ gìn di tích"],answer:2,explain:"Bảo vệ di tích là bổn phận với cộng đồng và đất nước."},{id:"dd4-bon-phan-tre-em-27",type:"mc",q:"Tùng thường xuyên bỏ bữa sáng để chơi điện tử. Tùng chưa làm tốt bổn phận nào?",options:["Với bản thân","Với nhà trường","Với cộng đồng"],answer:0,explain:"Ăn uống điều độ để khỏe mạnh là bổn phận với bản thân."}]}],challenge:{questions:[{id:"dd4-bon-phan-tre-em-28",type:"multi",q:"Những câu nào nói đúng về bổn phận của trẻ em?",options:["Phù hợp với lứa tuổi","Thực hiện với gia đình, nhà trường, cộng đồng, bản thân","Chỉ khi có người nhắc mới làm","Giúp em trở thành người có ích"],answers:[0,1,3],explain:"Bổn phận phù hợp lứa tuổi và cần thực hiện tự giác."},{id:"dd4-bon-phan-tre-em-29",type:"tf",q:"Có quyền thì không cần bổn phận.",answer:!1,explain:"Sai. Quyền và bổn phận luôn đi cùng nhau."},{id:"dd4-bon-phan-tre-em-30",type:"mc",q:"Khoa nói: “Mình được đi học là quyền, nên học hay không là tùy mình.” Em góp ý gì?",options:["Đúng rồi, học hay không là tùy bạn","Chăm học là bổn phận của bạn","Bạn cứ nghỉ học nếu thấy chán"],answer:1,explain:"Hưởng quyền thì cũng cần làm tròn bổn phận."},{id:"dd4-bon-phan-tre-em-19",type:"mc",q:"Minh muốn đi chơi nhưng đến giờ làm việc nhà được giao. Minh nên làm gì?",options:["Đi chơi ngay rồi về làm sau","Nhờ em làm hộ mà không hỏi","Làm xong việc nhà rồi mới đi chơi"],answer:2,explain:"Hoàn thành bổn phận trước, rồi vui chơi là hợp lí."},{id:"dd4-bon-phan-tre-em-22",type:"mc",q:"Hà đòi bố mẹ mua điện thoại đắt tiền vì “em có quyền vui chơi”. Em nghĩ sao?",options:["Chưa đúng, vui chơi không phải đòi hỏi","Đúng, bố mẹ phải mua cho Hà ngay","Đúng, trẻ em muốn gì cũng được"],answer:0,explain:"Quyền vui chơi không có nghĩa là đòi hỏi quá khả năng của gia đình."},{id:"dd4-bon-phan-tre-em-25",type:"order",q:"Sắp xếp các việc buổi sáng thể hiện bổn phận với bản thân và gia đình.",items:["Thức dậy đúng giờ","Gấp chăn màn, vệ sinh cá nhân","Ăn sáng cùng gia đình","Chào bố mẹ rồi đi học"],explain:"Một buổi sáng nề nếp cho thấy em có trách nhiệm."}]},summary:["Trẻ em có quyền và cũng có bổn phận phù hợp với lứa tuổi.","Em thực hiện bổn phận với gia đình, nhà trường, cộng đồng và bản thân.","Thực hiện tốt bổn phận giúp em trở thành người có ích."]}]},{id:"phuong-tien-ky-thuat-so",title:"Sử dụng an toàn, hợp lí phương tiện kĩ thuật số",lessons:[{id:"dd4-dung-thiet-bi-so",title:"Bài 15: Dùng thiết bị số hợp lí",weeks:[30,32],learn:[{title:"Phương tiện kĩ thuật số",text:"Điện thoại thông minh, máy tính bảng, máy tính, ti vi thông minh… giúp em học tập, tìm hiểu, liên lạc và giải trí.",example:"📱 💻 📺"},{title:"Dùng hợp lí",text:"Dùng đúng mục đích, có thời gian giới hạn, được bố mẹ đồng ý. Ngồi đúng tư thế, giữ khoảng cách mắt với màn hình, nghỉ mắt sau một lúc dùng.",example:"⏰ có giờ giấc · 👀 nghỉ mắt"},{title:"Tác hại khi dùng quá nhiều",text:"Mỏi mắt, cận thị, đau lưng, mất ngủ, ít vận động, học sa sút và ít trò chuyện với gia đình.",example:"😵 mỏi mắt · 🥱 mất ngủ"}],practice:[{questions:[{id:"dd4-dung-thiet-bi-so-01",type:"multi",q:"Đâu là phương tiện kĩ thuật số?",options:["Máy tính bảng","Điện thoại thông minh","Quyển sách giấy","Máy tính xách tay"],answers:[0,1,3],explain:"Máy tính bảng, điện thoại, máy tính là phương tiện kĩ thuật số."},{id:"dd4-dung-thiet-bi-so-02",type:"tf",q:"Thiết bị số có thể giúp em học tập, tra cứu thông tin.",answer:!0,explain:"Đúng. Dùng đúng mục đích, thiết bị số rất có ích."},{id:"dd4-dung-thiet-bi-so-03",type:"tf",q:"Càng dùng điện thoại nhiều thì càng thông minh.",answer:!1,explain:"Sai. Dùng quá nhiều có hại cho mắt, giấc ngủ và việc học."},{id:"dd4-dung-thiet-bi-so-04",type:"mc",q:"Tác hại nào có thể xảy ra khi nhìn màn hình quá lâu?",options:["Mỏi mắt, cận thị","Mắt sáng hơn","Cao lớn nhanh hơn"],answer:0,explain:"Nhìn màn hình lâu làm mắt mỏi và dễ bị cận thị."},{id:"dd4-dung-thiet-bi-so-05",type:"mc",q:"Trước khi dùng máy tính bảng của gia đình, em cần làm gì?",options:["Tự lấy dùng","Xin phép bố mẹ","Dùng lúc bố mẹ ngủ"],answer:1,explain:"Xin phép giúp em dùng đúng giờ và đúng mục đích."},{id:"dd4-dung-thiet-bi-so-06",type:"mc",q:"Khi dùng máy tính, em nên ngồi thế nào?",options:["Nằm bò ra giường cho thoải mái","Dí sát mắt vào màn hình cho rõ","Ngồi thẳng lưng, mắt cách xa màn hình"],answer:2,explain:"Tư thế đúng giúp bảo vệ mắt và cột sống."},{id:"dd4-dung-thiet-bi-so-07",type:"tf",q:"Không nên dùng điện thoại ngay trước giờ đi ngủ.",answer:!0,explain:"Đúng. Ánh sáng màn hình có thể làm em khó ngủ."},{id:"dd4-dung-thiet-bi-so-08",type:"tf",q:"Vừa ăn cơm vừa xem điện thoại là thói quen tốt.",answer:!1,explain:"Sai. Như vậy em ăn không ngon và ít trò chuyện với gia đình."},{id:"dd4-dung-thiet-bi-so-09",type:"mc",q:"Thiết bị số không nên dùng vào việc nào?",options:["Chơi trò chơi suốt đêm","Xem bài giảng","Gọi điện cho ông bà"],answer:0,explain:"Chơi suốt đêm làm hại sức khỏe và việc học."}]},{questions:[{id:"dd4-dung-thiet-bi-so-10",type:"match",q:"Nối việc dùng thiết bị số với mục đích.",pairs:[["Xem video bài học","Học tập"],["Gọi video cho ông bà","Liên lạc"],["Tra từ điển trực tuyến","Tìm hiểu kiến thức"],["Nghe nhạc thiếu nhi","Giải trí"]],explain:"Thiết bị số phục vụ nhiều mục đích có ích."},{id:"dd4-dung-thiet-bi-so-11",type:"mc",q:"Vì sao cần giới hạn thời gian dùng thiết bị số?",options:["Vì dùng lâu thiết bị sẽ hỏng ngay","Để bảo vệ sức khỏe, có giờ vận động","Vì bố mẹ không thích thiết bị số"],answer:1,explain:"Giới hạn thời gian giúp em cân bằng các hoạt động."},{id:"dd4-dung-thiet-bi-so-12",type:"multi",q:"Dấu hiệu nào cho thấy em đang dùng thiết bị số quá nhiều?",options:["Mắt hay mỏi, khô","Không muốn ra ngoài chơi","Bực bội khi phải tắt máy","Ngủ đủ giấc"],answers:[0,1,2],explain:"Những dấu hiệu này nhắc em cần giảm thời gian dùng thiết bị."},{id:"dd4-dung-thiet-bi-so-13",type:"tf",q:"Sau một khoảng thời gian nhìn màn hình, em nên nhìn ra xa để mắt được nghỉ.",answer:!0,explain:"Đúng. Nghỉ mắt giúp mắt đỡ mỏi."},{id:"dd4-dung-thiet-bi-so-14",type:"tf",q:"Có thể mang điện thoại vào lớp chơi trong giờ học nếu bài dễ.",answer:!1,explain:"Sai. Trong giờ học em cần tập trung theo nội quy của lớp."},{id:"dd4-dung-thiet-bi-so-15",type:"mc",q:"Hoạt động nào nên thay cho việc xem điện thoại cả buổi chiều?",options:["Chuyển sang xem ti vi cả buổi","Nằm ngủ suốt buổi chiều cho khỏe","Chơi thể thao, đọc sách, giúp việc nhà"],answer:2,explain:"Vận động và đọc sách giúp em khỏe mạnh, hiểu biết."},{id:"dd4-dung-thiet-bi-so-16",type:"mc",q:"Bạn nào dùng thiết bị số hợp lí?",options:["Bạn Minh xem bài giảng rồi tắt máy đi chơi","Bạn Lan xem video đến nửa đêm","Bạn Hà mang máy tính bảng vào bữa ăn"],answer:0,explain:"Dùng đúng việc, đúng giờ là dùng hợp lí."},{id:"dd4-dung-thiet-bi-so-17",type:"tf",q:"Nên đặt lịch dùng thiết bị số cùng bố mẹ.",answer:!0,explain:"Đúng. Có lịch rõ ràng giúp em tự giác hơn."},{id:"dd4-dung-thiet-bi-so-18",type:"mc",q:"Vì sao không nên dùng thiết bị khi đang sạc pin trên giường?",options:["Vì máy sẽ chạy chậm hơn","Vì máy có thể nóng, gây cháy","Vì pin sẽ hết nhanh hơn"],answer:1,explain:"Thiết bị đang sạc có thể nóng lên, đặt trên đệm dễ gây cháy."}]},{questions:[{id:"dd4-dung-thiet-bi-so-19",type:"mc",q:"Khoa xem video mãi không dừng được. Cách nào giúp Khoa?",options:["Xem tiếp cho đến khi chán","Giấu máy vào chăn để xem","Đặt hẹn giờ và nhờ bố mẹ nhắc"],answer:2,explain:"Hẹn giờ và nhờ người lớn nhắc giúp Khoa tự kiểm soát."},{id:"dd4-dung-thiet-bi-so-20",type:"tf",q:"Chi dùng máy tính tra cứu tranh ảnh về loài chim cho bài thuyết trình. Chi dùng thiết bị số đúng mục đích.",answer:!0,explain:"Đúng. Đó là dùng thiết bị số để học tập."},{id:"dd4-dung-thiet-bi-so-21",type:"multi",q:"Gia đình Nam muốn có “giờ không màn hình”. Cả nhà có thể làm gì trong giờ đó?",options:["Cùng nấu ăn","Chơi cờ, đọc truyện","Đi dạo công viên","Mỗi người ôm một chiếc điện thoại"],answers:[0,1,2],explain:"Giờ không màn hình giúp cả nhà gần gũi, vui vẻ hơn."},{id:"dd4-dung-thiet-bi-so-22",type:"mc",q:"Tối nay Hà có bài kiểm tra, nhưng bạn rủ chơi trò chơi trực tuyến. Hà nên làm gì?",options:["Từ chối, ôn bài xong rồi nghỉ ngơi","Chơi đến khuya rồi mới học","Vừa chơi vừa học cho vui"],answer:0,explain:"Ưu tiên việc quan trọng giúp Hà làm bài tốt."},{id:"dd4-dung-thiet-bi-so-23",type:"tf",q:"Vy đeo tai nghe bật âm lượng thật to trong nhiều giờ. Điều đó tốt cho tai.",answer:!1,explain:"Sai. Nghe to và lâu có thể làm hại thính giác."},{id:"dd4-dung-thiet-bi-so-24",type:"mc",q:"Tùng thấy mắt mờ, hay dụi mắt sau khi chơi máy tính bảng. Tùng nên làm gì?",options:["Chơi tiếp vì chắc sẽ tự khỏi","Nghỉ mắt và báo bố mẹ","Tăng độ sáng màn hình cho rõ hơn"],answer:1,explain:"Bảo vệ mắt là việc cần làm ngay."},{id:"dd4-dung-thiet-bi-so-25",type:"order",q:"Sắp xếp các bước dùng máy tính để làm bài tập.",items:["Xin phép bố mẹ","Ngồi đúng tư thế","Làm bài tập trên máy","Tắt máy, cất gọn"],explain:"Làm theo các bước giúp em dùng máy an toàn, đúng mục đích."},{id:"dd4-dung-thiet-bi-so-26",type:"mc",q:"Ngọc nhận được điện thoại cũ của chị. Ngọc nên làm gì đầu tiên?",options:["Cài thật nhiều trò chơi vào máy","Mang vào lớp để khoe với các bạn","Cùng bố mẹ thống nhất giờ dùng"],answer:2,explain:"Thống nhất quy tắc từ đầu giúp Ngọc dùng điện thoại hợp lí."},{id:"dd4-dung-thiet-bi-so-27",type:"mc",q:"Phúc nói: “Ngày nghỉ thì chơi điện tử cả ngày cũng được.” Em góp ý thế nào?",options:["Ngày nghỉ cũng nên chơi có giờ giấc","Đúng, ngày nghỉ thì chơi bao lâu cũng được","Chơi cả đêm nữa mới thích"],answer:0,explain:"Ngày nào cũng cần cân bằng để khỏe mạnh."}]}],challenge:{questions:[{id:"dd4-dung-thiet-bi-so-28",type:"multi",q:"Những điều nào giúp em dùng thiết bị số hợp lí?",options:["Dùng đúng mục đích","Có giới hạn thời gian","Ngồi đúng tư thế","Dùng khi đang ăn"],answers:[0,1,2],explain:"Đúng mục đích, có giờ giấc và đúng tư thế là dùng hợp lí."},{id:"dd4-dung-thiet-bi-so-29",type:"tf",q:"Dùng thiết bị số chỉ có hại, không có lợi.",answer:!1,explain:"Sai. Thiết bị số rất có ích nếu dùng đúng cách."},{id:"dd4-dung-thiet-bi-so-30",type:"mc",q:"Câu nào nói đúng nhất về thiết bị số?",options:["Càng dùng nhiều thì càng tốt","Là công cụ có ích nếu biết dùng đúng cách","Trẻ em không bao giờ được dùng"],answer:1,explain:"Biết dùng đúng cách, thiết bị số giúp em học tập và kết nối."},{id:"dd4-dung-thiet-bi-so-20",type:"tf",q:"Chi dùng máy tính tra cứu tranh ảnh về loài chim cho bài thuyết trình. Chi dùng thiết bị số đúng mục đích.",answer:!0,explain:"Đúng. Đó là dùng thiết bị số để học tập."},{id:"dd4-dung-thiet-bi-so-22",type:"mc",q:"Tối nay Hà có bài kiểm tra, nhưng bạn rủ chơi trò chơi trực tuyến. Hà nên làm gì?",options:["Từ chối, ôn bài xong rồi nghỉ ngơi","Chơi đến khuya rồi mới học","Vừa chơi vừa học cho vui"],answer:0,explain:"Ưu tiên việc quan trọng giúp Hà làm bài tốt."},{id:"dd4-dung-thiet-bi-so-25",type:"order",q:"Sắp xếp các bước dùng máy tính để làm bài tập.",items:["Xin phép bố mẹ","Ngồi đúng tư thế","Làm bài tập trên máy","Tắt máy, cất gọn"],explain:"Làm theo các bước giúp em dùng máy an toàn, đúng mục đích."}]},summary:["Thiết bị số rất có ích khi dùng đúng mục đích và có giờ giấc.","Dùng quá nhiều gây hại cho sức khỏe và việc học.","Em cùng bố mẹ thống nhất thời gian dùng thiết bị."]},{id:"dd4-an-toan-internet",title:"Bài 16: An toàn khi dùng Internet",weeks:[33,35],learn:[{title:"Thông tin cá nhân",text:"Họ tên đầy đủ, địa chỉ nhà, số điện thoại, tên trường lớp, mật khẩu, ảnh riêng là thông tin cá nhân, không chia sẻ với người lạ trên mạng.",example:"🔒 giữ kín mật khẩu"},{title:"Cẩn thận với người lạ",text:"Người quen trên mạng có thể không phải là người như họ nói. Không hẹn gặp người lạ quen trên mạng.",example:"🚫 hẹn gặp người lạ"},{title:"Khi gặp điều đáng sợ",text:"Gặp nội dung làm em sợ hãi, khó chịu, hoặc bị đe dọa, trêu chọc trên mạng: dừng lại, không trả lời, kể ngay với người lớn tin cậy.",example:"🛑 dừng · 🗣️ kể với người lớn"},{title:"Cư xử văn minh trên mạng",text:"Nói lời lịch sự, không bình luận ác ý, không chia sẻ ảnh của người khác khi chưa được phép.",example:"💬 lịch sự · 🤝 tôn trọng"}],practice:[{questions:[{id:"dd4-an-toan-internet-01",type:"multi",q:"Đâu là thông tin cá nhân cần giữ kín trên mạng?",options:["Địa chỉ nhà","Mật khẩu","Số điện thoại","Màu sắc em thích"],answers:[0,1,2],explain:"Địa chỉ, mật khẩu, số điện thoại cần được giữ kín."},{id:"dd4-an-toan-internet-02",type:"tf",q:"Không nên cho người lạ trên mạng biết địa chỉ nhà mình.",answer:!0,explain:"Đúng. Người lạ có thể dùng thông tin đó để làm hại em."},{id:"dd4-an-toan-internet-03",type:"tf",q:"Bạn thân hỏi mật khẩu thì em nên cho ngay.",answer:!1,explain:"Sai. Mật khẩu là của riêng em, chỉ bố mẹ nên biết."},{id:"dd4-an-toan-internet-04",type:"mc",q:"Gặp nội dung làm em sợ hãi trên mạng, em nên làm gì?",options:["Tắt đi và kể với người lớn tin cậy","Xem tiếp cho biết","Gửi cho bạn bè cùng xem"],answer:0,explain:"Kể với người lớn giúp em được bảo vệ."},{id:"dd4-an-toan-internet-05",type:"mc",q:"Người lạ trên mạng rủ em gặp mặt, em nên làm gì?",options:["Đi gặp một mình","Từ chối và kể với bố mẹ","Hẹn ở nơi vắng vẻ"],answer:1,explain:"Không bao giờ hẹn gặp người lạ quen trên mạng."},{id:"dd4-an-toan-internet-06",type:"mc",q:"Mật khẩu nào an toàn hơn?",options:["Dãy số 123456 dễ nhớ","Tên và ngày sinh của em","Dãy chữ, số, kí hiệu khó đoán"],answer:2,explain:"Mật khẩu khó đoán giúp bảo vệ tài khoản của em."},{id:"dd4-an-toan-internet-07",type:"tf",q:"Bình luận lịch sự trên mạng cũng là tôn trọng người khác.",answer:!0,explain:"Đúng. Trên mạng hay ngoài đời em đều cần lịch sự."},{id:"dd4-an-toan-internet-08",type:"tf",q:"Chia sẻ ảnh xấu của bạn lên mạng cho vui là không sao.",answer:!1,explain:"Sai. Việc đó làm bạn xấu hổ, tổn thương."},{id:"dd4-an-toan-internet-09",type:"mc",q:"Khi thấy quảng cáo “Bấm vào đây để nhận quà”, em nên làm gì?",options:["Không bấm, hỏi ý kiến người lớn","Bấm ngay để nhận quà","Điền thông tin của bố mẹ vào"],answer:0,explain:"Những đường dẫn lạ có thể lừa đảo hoặc có virus."}]},{questions:[{id:"dd4-an-toan-internet-10",type:"match",q:"Nối tình huống trên mạng với cách xử lí đúng.",pairs:[["Người lạ hỏi địa chỉ","Không trả lời, báo bố mẹ"],["Bị nhắn tin trêu chọc","Không đáp lại, lưu lại, kể với người lớn"],["Thấy đường dẫn lạ","Không bấm vào"],["Muốn đăng ảnh của bạn","Hỏi bạn trước"]],explain:"Mỗi tình huống có một cách xử lí an toàn."},{id:"dd4-an-toan-internet-11",type:"mc",q:"Vì sao không nên tin hết những gì người lạ nói trên mạng?",options:["Vì người lạ trên mạng luôn nói đúng","Vì người đó có thể giả danh","Vì mạng Internet hay bị chậm"],answer:1,explain:"Trên mạng, người ta có thể giả làm người khác."},{id:"dd4-an-toan-internet-12",type:"tf",q:"Bắt nạt qua mạng cũng làm người khác tổn thương như bắt nạt ngoài đời.",answer:!0,explain:"Đúng. Lời lẽ ác ý trên mạng gây buồn đau thật sự."},{id:"dd4-an-toan-internet-13",type:"multi",q:"Những việc nào là cư xử văn minh trên mạng?",options:["Dùng lời lẽ lịch sự","Hỏi trước khi đăng ảnh của người khác","Bình luận chê bai ngoại hình người khác","Không lan truyền tin đồn"],answers:[0,1,3],explain:"Cư xử văn minh giúp mạng thành nơi an toàn, vui vẻ."},{id:"dd4-an-toan-internet-14",type:"tf",q:"Đăng ảnh có tên trường và địa chỉ nhà lên mạng là an toàn.",answer:!1,explain:"Sai. Người lạ có thể biết em ở đâu, rất nguy hiểm."},{id:"dd4-an-toan-internet-15",type:"mc",q:"Thông tin trên mạng có luôn đúng không?",options:["Luôn luôn đúng, không cần kiểm tra","Đúng nếu có nhiều người chia sẻ","Không, cần kiểm tra ở nguồn tin cậy"],answer:2,explain:"Nhiều thông tin trên mạng chưa chính xác, em cần kiểm tra."},{id:"dd4-an-toan-internet-16",type:"mc",q:"Khi dùng máy tính ở nơi công cộng, em nên làm gì sau khi dùng xong?",options:["Đăng xuất tài khoản","Để nguyên tài khoản","Lưu mật khẩu lại trên máy"],answer:0,explain:"Đăng xuất giúp người khác không dùng được tài khoản của em."},{id:"dd4-an-toan-internet-17",type:"tf",q:"Nếu lỡ chia sẻ thông tin cá nhân, em nên kể ngay với bố mẹ.",answer:!0,explain:"Đúng. Bố mẹ sẽ giúp em xử lí kịp thời."},{id:"dd4-an-toan-internet-18",type:"order",q:"Sắp xếp các bước khi bị người lạ nhắn tin làm em sợ.",items:["Dừng lại, không trả lời","Chụp màn hình hoặc giữ lại tin nhắn","Kể với bố mẹ hoặc thầy cô","Cùng người lớn chặn và báo cáo tài khoản đó"],explain:"Bình tĩnh và nhờ người lớn giúp em an toàn."}]},{questions:[{id:"dd4-an-toan-internet-19",type:"mc",q:"Một tài khoản lạ tự nhận là “bạn cùng tuổi”, hỏi tên trường và giờ tan học của Lan. Lan nên làm gì?",options:["Trả lời đầy đủ","Không trả lời và kể với bố mẹ","Hẹn gặp để xem có đúng không"],answer:1,explain:"Câu hỏi về trường và giờ tan học là dấu hiệu nguy hiểm."},{id:"dd4-an-toan-internet-20",type:"tf",q:"Nam được người lạ trên trò chơi trực tuyến hứa tặng vật phẩm nếu gửi ảnh và số điện thoại. Nam nên gửi.",answer:!1,explain:"Sai. Đó có thể là lừa đảo; Nam không gửi và kể ngay với người lớn."},{id:"dd4-an-toan-internet-21",type:"multi",q:"Nhóm chat lớp có bạn bị chế giễu. Em có thể làm gì?",options:["Không hùa theo","Nhắn riêng động viên bạn bị chế giễu","Thả biểu tượng cười vào lời chế giễu","Báo cô chủ nhiệm"],answers:[0,1,3],explain:"Không hùa theo và báo người lớn giúp bảo vệ bạn."},{id:"dd4-an-toan-internet-22",type:"mc",q:"Minh thấy tin “Ngày mai trường nghỉ học” lan truyền trên mạng. Minh nên làm gì?",options:["Chia sẻ ngay cho mọi người cùng biết","Ở nhà nghỉ học luôn","Hỏi lại cô giáo hoặc bố mẹ để kiểm tra"],answer:2,explain:"Kiểm tra tin ở nguồn tin cậy trước khi tin và chia sẻ."},{id:"dd4-an-toan-internet-23",type:"mc",q:"Chi muốn đăng ảnh chụp chung với các bạn. Chi nên làm gì?",options:["Hỏi các bạn và bố mẹ trước khi đăng","Đăng luôn cho nhanh, không cần hỏi","Đăng kèm địa chỉ nhà từng bạn"],answer:0,explain:"Tôn trọng quyền riêng tư của bạn và giữ an toàn cho mọi người."},{id:"dd4-an-toan-internet-24",type:"tf",q:"Thảo thấy video có nội dung bạo lực, Thảo tắt đi và kể với mẹ. Thảo làm đúng.",answer:!0,explain:"Đúng. Thảo tự bảo vệ mình và nhờ người lớn giúp."},{id:"dd4-an-toan-internet-25",type:"mc",q:"Dũng nhận được tin nhắn: “Đừng kể với bố mẹ chuyện chúng mình nói nhé.” Dũng nên làm gì?",options:["Giữ bí mật","Kể ngay với bố mẹ","Nhắn tin tiếp"],answer:1,explain:"Người lạ bảo giữ bí mật với bố mẹ là dấu hiệu nguy hiểm."},{id:"dd4-an-toan-internet-26",type:"order",q:"Sắp xếp các bước tạo một mật khẩu an toàn cùng bố mẹ.",items:["Chọn một cụm từ dễ nhớ với em nhưng khó đoán","Thêm chữ hoa, chữ số và kí hiệu","Ghi nhớ mật khẩu","Giữ kín, chỉ bố mẹ biết"],explain:"Mật khẩu tốt giúp bảo vệ tài khoản của em."},{id:"dd4-an-toan-internet-27",type:"mc",q:"Vy lỡ bấm vào một đường dẫn lạ, máy hiện nhiều cửa sổ quảng cáo. Vy nên làm gì?",options:["Bấm tiếp các quảng cáo","Giấu đi không nói","Dừng lại và báo bố mẹ ngay"],answer:2,explain:"Báo người lớn kịp thời giúp xử lí máy an toàn."}]}],challenge:{questions:[{id:"dd4-an-toan-internet-28",type:"multi",q:"Những quy tắc an toàn trên mạng em cần nhớ là gì?",options:["Giữ kín thông tin cá nhân","Không hẹn gặp người lạ","Kể với người lớn khi gặp điều đáng sợ","Bấm vào mọi đường dẫn có quà"],answers:[0,1,2],explain:"Ba quy tắc này giúp em an toàn khi dùng Internet."},{id:"dd4-an-toan-internet-29",type:"tf",q:"Trên mạng không ai biết mình là ai nên có thể nói gì cũng được.",answer:!1,explain:"Sai. Lời nói trên mạng vẫn ảnh hưởng đến người khác; em cần lịch sự, có trách nhiệm."},{id:"dd4-an-toan-internet-30",type:"mc",q:"Người lạ khen em rất nhiều rồi xin ảnh riêng của em. Em nên làm gì?",options:["Không gửi, kể ngay với bố mẹ","Gửi ảnh vì người đó rất tốt","Gửi một tấm ảnh cũ thôi"],answer:0,explain:"Không gửi ảnh riêng cho người lạ; kể ngay với người lớn tin cậy."},{id:"dd4-an-toan-internet-19",type:"mc",q:"Một tài khoản lạ tự nhận là “bạn cùng tuổi”, hỏi tên trường và giờ tan học của Lan. Lan nên làm gì?",options:["Trả lời đầy đủ","Không trả lời và kể với bố mẹ","Hẹn gặp để xem có đúng không"],answer:1,explain:"Câu hỏi về trường và giờ tan học là dấu hiệu nguy hiểm."},{id:"dd4-an-toan-internet-23",type:"mc",q:"Chi muốn đăng ảnh chụp chung với các bạn. Chi nên làm gì?",options:["Hỏi các bạn và bố mẹ trước khi đăng","Đăng luôn cho nhanh, không cần hỏi","Đăng kèm địa chỉ nhà từng bạn"],answer:0,explain:"Tôn trọng quyền riêng tư của bạn và giữ an toàn cho mọi người."},{id:"dd4-an-toan-internet-25",type:"mc",q:"Dũng nhận được tin nhắn: “Đừng kể với bố mẹ chuyện chúng mình nói nhé.” Dũng nên làm gì?",options:["Giữ bí mật","Kể ngay với bố mẹ","Nhắn tin tiếp"],answer:1,explain:"Người lạ bảo giữ bí mật với bố mẹ là dấu hiệu nguy hiểm."}]},summary:["Giữ kín thông tin cá nhân và mật khẩu.","Không hẹn gặp người lạ quen trên mạng.","Gặp điều đáng sợ trên mạng thì kể ngay với người lớn tin cậy.","Cư xử lịch sự, tôn trọng người khác trên mạng."]}]}],g={grade:4,subject:n,title:i,review:h,topics:t};export{g as default,c as grade,h as review,n as subject,i as title,t as topics};
